const DOCS={"scene01":{"source":"Documentation/Story/Academy_Kakashi_Origin_Scene_01_Rooftop_Verbatim_Lock_2026-09-17.md","sections":[{"level":1,"title":"Academy Kakashi Origin — Scene 01 Rooftop Verbatim Lock","path":"Academy Kakashi Origin — Scene 01 Rooftop Verbatim Lock","text":"Status: **STEPHEN-APPROVED — VERBATIM PLAYER-FACING AUTHORITY — DO NOT CHANGE**\n\nDate: 2026-09-17\n\nThis file is the binding player-facing Writing authority for **Academy Kakashi Origin — Scene 1**."},{"level":2,"title":"HARD RULE","path":"Academy Kakashi Origin — Scene 01 Rooftop Verbatim Lock > HARD RULE","text":"The dialogue and narration below are locked **verbatim**.\n\nDo not paraphrase, condense, expand, reorder, modernize, rewrite, substitute, or \"improve\" any line without Stephen's explicit approval **before** any changed wording is written to GitHub.\n\nDo not infer alternate dialogue from older runtime files, prior modernization passes, Scene Board presentation code, or branch summaries."},{"level":2,"title":"Scene 1 — Konoha Rooftop, Night","path":"Academy Kakashi Origin — Scene 01 Rooftop Verbatim Lock > Scene 1 — Konoha Rooftop, Night","text":"**Purpose:** Establish Kakashi, the ANBU operative, the Hokage-authorised assignment, the mission objective, and the sealed envelope."},{"level":3,"title":"Exact player-facing sequence","path":"Academy Kakashi Origin — Scene 01 Rooftop Verbatim Lock > Scene 1 — Konoha Rooftop, Night > Exact player-facing sequence","text":"1. **NARRATION**\n   `Kakashi stands alone on a Konoha rooftop, the village lights spread out below him. A masked ANBU operative lands behind him without warning.`\n\n2. **DIALOGUE — ANBU OPERATIVE**\n   `Kakashi Hatake.`\n\n3. **NARRATION**\n   `Kakashi turns to face him.`\n\n4. **DIALOGUE — ANBU OPERATIVE**\n   `You have orders. Stop this package from falling into the wrong hands.`\n\n5. **NARRATION**\n   `The operative holds out a sealed envelope.`\n\n6. **NARRATION**\n   `Kakashi crosses the rooftop and takes it.`\n\n7. **DIALOGUE — KAKASHI**\n   `Why are you coming to me with this?`\n\n8. **DIALOGUE — ANBU OPERATIVE**\n   `Hokage's orders.`\n\n9. **NARRATION**\n   `Kakashi looks down at the seal.`\n\n10. **NARRATION**\n    `He breaks it. A target photograph waits inside.`"},{"level":2,"title":"Exact spoken dialogue set","path":"Academy Kakashi Origin — Scene 01 Rooftop Verbatim Lock > Exact spoken dialogue set","text":"The only spoken dialogue in Scene 1 is:\n\n- **ANBU OPERATIVE:** `Kakashi Hatake.`\n- **ANBU OPERATIVE:** `You have orders. Stop this package from falling into the wrong hands.`\n- **KAKASHI:** `Why are you coming to me with this?`\n- **ANBU OPERATIVE:** `Hokage's orders.`"},{"level":2,"title":"Explicitly prohibited substitutions","path":"Academy Kakashi Origin — Scene 01 Rooftop Verbatim Lock > Explicitly prohibited substitutions","text":"The following are **not** Scene 1 authority and must not appear as replacements:\n\n- `What do you want?`\n- `Hatake Kakashi.`\n- `The Hokage approved you to assist us...`\n- any compressed briefing that replaces the four approved spoken lines\n- any presentation that renders narration/action as character dialogue"},{"level":2,"title":"Ordering lock","path":"Academy Kakashi Origin — Scene 01 Rooftop Verbatim Lock > Ordering lock","text":"The sequence is binding:\n\n`orders -> envelope offered -> Kakashi crosses and takes it -> Kakashi questions ANBU -> Hokage's orders -> Kakashi looks at seal -> Kakashi opens envelope -> target photograph`\n\nNo runtime or presentation layer may reorder those beats."},{"level":2,"title":"Authority precedence","path":"Academy Kakashi Origin — Scene 01 Rooftop Verbatim Lock > Authority precedence","text":"For Scene 1 player-facing wording and ordering, this file supersedes any conflicting older Kakashi Origin runtime/presentation copy, including stale dialogue embedded in previous restoration or Scene Board presentation files.\n\nSemantic Story facts, resolver ownership, Battle logic, rewards, progression, custody, and Chronicle history are unchanged by this lock."},{"level":2,"title":"Future dialogue-change gate","path":"Academy Kakashi Origin — Scene 01 Rooftop Verbatim Lock > Future dialogue-change gate","text":"Any proposed change to any locked dialogue line in Shinobi Chronicles Story content must be presented to Stephen for approval **before** that changed dialogue is written to GitHub.\n\nNo specialist may silently paraphrase approved dialogue as part of modernization, implementation, localisation preparation, UI presentation, runtime binding, refactoring, or bug fixing."}]},"scene02":{"source":"Documentation/Story/Academy_Kakashi_Origin_Scene_02_The_Tail_Verbatim_Lock_2026-09-17.md","sections":[{"level":1,"title":"Academy Kakashi Origin — Scene 02: The Tail — Verbatim Lock","path":"Academy Kakashi Origin — Scene 02: The Tail — Verbatim Lock","text":"Status: **STEPHEN-APPROVED / LOCKED VERBATIM — DO NOT CHANGE**\n\nThis file is the exact player-facing authority for Kakashi Origin Scene 2. Coding must implement it verbatim. Do not paraphrase, condense, expand, reorder, substitute, or add dialogue/choices."},{"level":2,"title":"Backdrop","path":"Academy Kakashi Origin — Scene 02: The Tail — Verbatim Lock > Backdrop","text":"Konoha alleyway — night."},{"level":2,"title":"Narration","path":"Academy Kakashi Origin — Scene 02: The Tail — Verbatim Lock > Narration","text":"Kakashi did not need long to find the man from the envelope.\n\nThe difficult part was making sure the man never realised he had been found.\n\nKonoha changed shape when Kakashi followed someone through it. Streets stopped being streets and became sightlines. Crowds became cover. Roof edges became distances to clear before the person below could turn his head.\n\nANBU Marked Target moved without the nervous scanning of someone who expected immediate pursuit.\n\nKakashi kept it that way.\n\nHe followed from above until the route tightened into older streets and narrower angles, then dropped lower when the rooftops would have made him too obvious.\n\nThe target never looked directly at him.\n\nNot once.\n\nThat did not make Kakashi relax.\n\nIt made him wonder who the man expected to meet.\n\nBy the time the route bent toward the Sakura tree and the alley beyond it, Kakashi had his answer.\n\nSomeone was waiting."},{"level":2,"title":"Dialogue","path":"Academy Kakashi Origin — Scene 02: The Tail — Verbatim Lock > Dialogue","text":"None."},{"level":2,"title":"Choices","path":"Academy Kakashi Origin — Scene 02: The Tail — Verbatim Lock > Choices","text":"- `SCENE_02 / CHOICE_01 / BRANCH_A` — **Observe Exchange**  \n  Player-facing choice: **WATCH THE EXCHANGE**\n\n- `SCENE_02 / CHOICE_01 / BRANCH_B` — **Get Closer**  \n  Player-facing choice: **MOVE IN CLOSER**\n\n- `SCENE_02 / CHOICE_01 / BRANCH_C` — **Attack**  \n  Player-facing choice: **STRIKE BEFORE THE HANDOFF**\n\n- `SCENE_02 / CHOICE_01 / BRANCH_D` — **Attempt Pickpocket**  \n  Player-facing choice: **SLIP IN FOR THE PACKAGE**\n\nThe previously proposed standalone pre-choice Scene 3 is retired. These choices are the end of Scene 2. The next authored scene begins from the selected Scene 2 branch."}]},"scene03a":{"source":"Documentation/Story/Academy_Kakashi_Origin_Scene_03A_Watch_The_Exchange_Verbatim_Lock_2026-09-17.md","sections":[{"level":1,"title":"Academy Kakashi Origin — Scene 03A: WATCH THE EXCHANGE — Verbatim Lock","path":"Academy Kakashi Origin — Scene 03A: WATCH THE EXCHANGE — Verbatim Lock","text":"Status: **STEPHEN-APPROVED / LOCKED VERBATIM — DO NOT CHANGE**\n\nThis file is the exact player-facing authority for Kakashi Origin Scene 3A, reached from Scene 2 by selecting **WATCH THE EXCHANGE**. Coding must implement it verbatim. Do not paraphrase, condense, expand, reorder, substitute, or add dialogue/choices."},{"level":2,"title":"Backdrop","path":"Academy Kakashi Origin — Scene 03A: WATCH THE EXCHANGE — Verbatim Lock > Backdrop","text":"Sakura tree / main street — night."},{"level":2,"title":"Narration","path":"Academy Kakashi Origin — Scene 03A: WATCH THE EXCHANGE — Verbatim Lock > Narration","text":"Kakashi stays where he is.\n\nNot passive.\n\nWatching.\n\nANBU Marked Target shifts the package from beneath his clothing and places it into Package Smuggler's hand.\n\nThe moment custody changes, the whole problem changes with it.\n\nKakashi's eye follows the package.\n\nANBU Marked Target is already moving away.\n\nPackage Smuggler turns in the opposite direction.\n\nKakashi has one additional fact now—who received the package—and less control over the situation than he had a few seconds earlier.\n\nThe trade was information for escalation.\n\nThen the darkness beside the alley moved.\n\nNot slowly.\n\nA figure tore out of it like a lightning streak.\n\nMasked Interceptor hit the new situation at speed, driving straight toward Package Smuggler and forcing him to react before he had properly cleared the exchange.\n\nANBU Marked Target broke away.\n\nPackage Smuggler tightened around the package.\n\nMasked Interceptor cut across his escape line.\n\nAnd Kakashi, still unseen for one more heartbeat, had to choose what mattered most now."},{"level":2,"title":"Dialogue","path":"Academy Kakashi Origin — Scene 03A: WATCH THE EXCHANGE — Verbatim Lock > Dialogue","text":"None."},{"level":2,"title":"Choices","path":"Academy Kakashi Origin — Scene 03A: WATCH THE EXCHANGE — Verbatim Lock > Choices","text":"- `SCENE_03A / CHOICE_01 / BRANCH_A` — **STOP THE ASSASSIN**\n- `SCENE_03A / CHOICE_01 / BRANCH_B` — **SECURE THE PACKAGE**\n- `SCENE_03A / CHOICE_01 / BRANCH_C` — **SECURE THE PACKAGE BEFORE THE ASSASSIN**\n- `SCENE_03A / CHOICE_01 / BRANCH_D` — **DEFEAT THE ASSASSIN, THEN SECURE THE PACKAGE**\n- `SCENE_03A / CHOICE_01 / BRANCH_E` — **GO AFTER THE ORIGINAL TARGET**"}]},"scene04a":{"source":"Documentation/Story/Academy_Kakashi_Origin_Scene_04A_Stop_The_Assassin_Verbatim_Lock_2026-09-18.md","sections":[{"level":1,"title":"Academy Kakashi Origin — Scene 04A: Stop the Assassin — Verbatim Lock","path":"Academy Kakashi Origin — Scene 04A: Stop the Assassin — Verbatim Lock","text":"Status: **STEPHEN-APPROVED / LOCKED VERBATIM — DO NOT CHANGE**\n\nSource branch: `SCENE_03A / CHOICE_01 / BRANCH_A — STOP THE ASSASSIN`\n\nThis file is the exact player-facing authority for Kakashi Origin Scene 4A. Coding must implement it verbatim. Do not paraphrase, condense, expand, reorder, substitute, or add dialogue."},{"level":2,"title":"Backdrop","path":"Academy Kakashi Origin — Scene 04A: Stop the Assassin — Verbatim Lock > Backdrop","text":"Sakura tree / main street — night."},{"level":2,"title":"Objective","path":"Academy Kakashi Origin — Scene 04A: Stop the Assassin — Verbatim Lock > Objective","text":"**Retrieve the package.**"},{"level":2,"title":"Narration","path":"Academy Kakashi Origin — Scene 04A: Stop the Assassin — Verbatim Lock > Narration","text":"Kakashi moves.\n\nNot toward ANBU Marked Target.\n\nNot toward the package.\n\nToward Masked Interceptor.\n\nShe is already closing on Package Smuggler when Kakashi drops between them.\n\nPackage Smuggler sees the opening immediately.\n\nHe turns and runs.\n\nThe package goes with him.\n\nKakashi does not follow.\n\nMasked Interceptor changes direction without hesitation.\n\nHer attention settles on Kakashi.\n\nHe has made himself the obstacle now.\n\nShe comes straight through him.\n\nKakashi meets her head-on."},{"level":2,"title":"Dialogue","path":"Academy Kakashi Origin — Scene 04A: Stop the Assassin — Verbatim Lock > Dialogue","text":"None."},{"level":2,"title":"System / Resolver","path":"Academy Kakashi Origin — Scene 04A: Stop the Assassin — Verbatim Lock > System / Resolver","text":"**PL BATTLE:** Kakashi Hatake vs Masked Interceptor  \n**Format:** 1-v-1"},{"level":2,"title":"Choices","path":"Academy Kakashi Origin — Scene 04A: Stop the Assassin — Verbatim Lock > Choices","text":"None."}]},"scene05w":{"source":"Documentation/Story/Academy_Kakashi_Origin_Scene_05A_W_Kakashi_Wins_Verbatim_Lock_2026-09-18.md","sections":[{"level":1,"title":"Academy Kakashi Origin — Scene 05A-W: Kakashi Wins — Verbatim Lock","path":"Academy Kakashi Origin — Scene 05A-W: Kakashi Wins — Verbatim Lock","text":"> **2026-09-20 CURRENT POST-BATTLE CHOICE NOTICE**  \n> The historical `KILL HER / ATTEMPT TO KILL HER` and `RESTRAIN / ATTEMPT TO RESTRAIN` control-state split below is superseded for the current player-facing choice surface by:\n> `Academy_Kakashi_Post_Battle_Disposition_Simplification_2026-09-19.md`\n> and the current post-restraint collection authority.\n>\n> Current authored choices are not renamed/hidden by `CONTROLLED_DEFEATED`.\n>\n> Legacy MI lethal-attempt outcome files remain valid for already-committed historical/save-state provenance; they are not permission to restore hidden-control gating to the current menu.\n\n**Date:** 2026-09-19  \n**Owner:** Stephen / Writing — Konoha  \n**Status:** **STEPHEN-APPROVED / LOCKED VERBATIM — DO NOT CHANGE**\n\n**Source branch:** `SCENE_03A / CHOICE_01 / BRANCH_A — STOP THE ASSASSIN`  \n**Entry:** Scene 04A PL Battle resolves with **Kakashi Hatake victory over Masked Interceptor**.\n\nThis file is the exact player-facing and scene-continuation authority for Kakashi Origin Scene 05A-W.\n\nIt supersedes the prior player-facing 1–3 / Package-Smuggler-only version."},{"level":2,"title":"Backdrop","path":"Academy Kakashi Origin — Scene 05A-W: Kakashi Wins — Verbatim Lock > Backdrop","text":"`fight_at_sakura_tree.png`"},{"level":2,"title":"Objective","path":"Academy Kakashi Origin — Scene 05A-W: Kakashi Wins — Verbatim Lock > Objective","text":"**Retrieve the package.**"},{"level":2,"title":"Narration","path":"Academy Kakashi Origin — Scene 05A-W: Kakashi Wins — Verbatim Lock > Narration","text":"Masked Interceptor hits the stone beneath the Sakura tree.\n\nKakashi lands a few steps away.\n\nFor a moment, the street is still.\n\nThen his eye moves past her.\n\nToward the routes the others took."},{"level":3,"title":"If Kakashi wins within 1–4 turns","path":"Academy Kakashi Origin — Scene 05A-W: Kakashi Wins — Verbatim Lock > Narration > If Kakashi wins within 1–4 turns","text":"Package Smuggler cuts across the far end of the street.\n\nStill moving.\n\nThe package is still with him.\n\nHigher up, movement flashes across a distant roofline.\n\nANBU Marked Target.\n\nFarther away.\n\nBut not gone.\n\nNot yet.\n\nKakashi looks between them.\n\nOne route leads to the package.\n\nThe other to the man who carried it here.\n\nThen his eye drops back to Masked Interceptor.\n\nShe lies where he put her.\n\nThree problems.\n\nNot enough time for all of them at once.\n\nWhatever Kakashi does next will decide which ones remain within reach."},{"level":3,"title":"If Kakashi wins on turn 5 or later","path":"Academy Kakashi Origin — Scene 05A-W: Kakashi Wins — Verbatim Lock > Narration > If Kakashi wins on turn 5 or later","text":"The street ahead is empty.\n\nKakashi searches the rooftops.\n\nThe alleys.\n\nThe next junction.\n\nNothing.\n\nPackage Smuggler had too much time.\n\nThe package is gone with him.\n\nANBU Marked Target is gone as well.\n\nKakashi looks back at Masked Interceptor.\n\nShe lies beneath the Sakura tree.\n\nThe pursuit is over.\n\nWhat happens to her is the only decision left here."},{"level":2,"title":"Dialogue","path":"Academy Kakashi Origin — Scene 05A-W: Kakashi Wins — Verbatim Lock > Dialogue","text":"None."},{"level":2,"title":"System / Resolver","path":"Academy Kakashi Origin — Scene 05A-W: Kakashi Wins — Verbatim Lock > System / Resolver","text":"Consume:\n\n**PL BATTLE — Kakashi Hatake vs Masked Interceptor**  \n**Result: Kakashi Victory**\n\nRead the completed Battle turn count and Masked Interceptor's exact post-Battle control state."},{"level":3,"title":"Victory within 1–4 turns","path":"Academy Kakashi Origin — Scene 05A-W: Kakashi Wins — Verbatim Lock > System / Resolver > Victory within 1–4 turns","text":"Immediate pursuit state:\n\n- Package Smuggler remains reachable.\n- ANBU Marked Target remains reachable.\n- Kakashi may pursue **one** immediately.\n- Choosing ANBU Marked Target closes Package Smuggler pursuit.\n- Choosing Package Smuggler preserves possible later ANBU Marked Target pursuit only through the separately authorised PS **1–3-turn** continuation gate.\n\nMasked Interceptor remains available for a post-Battle decision where her factual state permits it."},{"level":3,"title":"Victory on turn 5 or later","path":"Academy Kakashi Origin — Scene 05A-W: Kakashi Wins — Verbatim Lock > System / Resolver > Victory on turn 5 or later","text":"- Package Smuggler is no longer reachable.\n- ANBU Marked Target is no longer reachable.\n- No pursuit choice remains.\n- Only state-eligible Masked Interceptor dispositions remain."},{"level":3,"title":"Masked Interceptor state","path":"Academy Kakashi Origin — Scene 05A-W: Kakashi Wins — Verbatim Lock > System / Resolver > Masked Interceptor state","text":"If **CONTROLLED_DEFEATED**:\n\n- deterministic **KILL HER** may be available;\n- immediate ANBU custody may be available;\n- immediate Uchiha Police custody may be available;\n- on a qualifying 1–4-turn victory, **RESTRAIN HER AND CONTINUE** may be available.\n\nIf **DEFEATED_BUT_NOT_CONTROLLED**:\n\n- **ATTEMPT TO KILL HER** may be available;\n- custody actions remain subject to legitimate current-state eligibility;\n- on a qualifying 1–4-turn victory, use the resolver-owned **ATTEMPT TO RESTRAIN HER AND CONTINUE** equivalent."},{"level":3,"title":"If Kakashi wins within 1–4 turns","path":"Academy Kakashi Origin — Scene 05A-W: Kakashi Wins — Verbatim Lock > Choices > If Kakashi wins within 1–4 turns","text":"- `SCENE_05A_W / CHOICE_01 / BRANCH_A` — **GO AFTER PACKAGE SMUGGLER**\n- `SCENE_05A_W / CHOICE_01 / BRANCH_B` — **GO AFTER ANBU MARKED TARGET**\n- `SCENE_05A_W / CHOICE_01 / BRANCH_C` — **KILL HER** / **ATTEMPT TO KILL HER**\n- `SCENE_05A_W / CHOICE_01 / BRANCH_D` — **TAKE HER BACK TO ANBU**\n- `SCENE_05A_W / CHOICE_01 / BRANCH_E` — **TAKE HER TO THE UCHIHA POLICE FORCE**\n- `SCENE_05A_W / CHOICE_01 / BRANCH_F` — **RESTRAIN HER AND CONTINUE** / **ATTEMPT TO RESTRAIN HER AND CONTINUE**"},{"level":3,"title":"If Kakashi wins on turn 5 or later","path":"Academy Kakashi Origin — Scene 05A-W: Kakashi Wins — Verbatim Lock > Choices > If Kakashi wins on turn 5 or later","text":"- `SCENE_05A_W / CHOICE_01 / BRANCH_C` — **KILL HER** / **ATTEMPT TO KILL HER**\n- `SCENE_05A_W / CHOICE_01 / BRANCH_D` — **TAKE HER BACK TO ANBU**\n- `SCENE_05A_W / CHOICE_01 / BRANCH_E` — **TAKE HER TO THE UCHIHA POLICE FORCE**"}]},"scene05l":{"source":"Documentation/Story/Academy_Kakashi_Origin_Scene_05A_L_Kakashi_Loses_Verbatim_Lock_2026-09-18.md","sections":[{"level":1,"title":"Academy Kakashi Origin — Scene 05A-L: Kakashi Loses — Verbatim Lock","path":"Academy Kakashi Origin — Scene 05A-L: Kakashi Loses — Verbatim Lock","text":"**Date:** 2026-09-18  \n**Owner:** Stephen / Writing — Konoha  \n**Status:** **STEPHEN-APPROVED / LOCKED VERBATIM — DO NOT CHANGE**\n\n**Source branch:** `SCENE_03A / CHOICE_01 / BRANCH_A — STOP THE ASSASSIN`  \n**Entry:** Scene 04A PL Battle resolves with **Masked Interceptor victory over Kakashi Hatake**.\n\nThis file is the exact player-facing and scene-continuation authority for Kakashi Origin Scene 5A-L. Coding must implement it verbatim. Do not paraphrase, condense, expand, reorder, substitute, or silently alter the approved Objective switch or choice."},{"level":2,"title":"Backdrop","path":"Academy Kakashi Origin — Scene 05A-L: Kakashi Loses — Verbatim Lock > Backdrop","text":"`fight_at_sakura_tree.png`"},{"level":2,"title":"Objective","path":"Academy Kakashi Origin — Scene 05A-L: Kakashi Loses — Verbatim Lock > Objective","text":"**Retrieve the package.**"},{"level":2,"title":"Narration","path":"Academy Kakashi Origin — Scene 05A-L: Kakashi Loses — Verbatim Lock > Narration","text":"The opening is small.\n\nMasked Interceptor takes it.\n\nKakashi hits the stone beneath the Sakura tree.\n\nBefore he can recover, she is on him.\n\nHis arm is forced behind his back.\n\nHis shoulder pinned.\n\nKakashi twists once.\n\nShe tightens the hold.\n\nEnough to stop him.\n\nThen her attention shifts.\n\nNot to Kakashi.\n\nDown the street.\n\nToward the route Package Smuggler took.\n\nThe pressure disappears.\n\nKakashi turns his head just in time to see Masked Interceptor break away.\n\nShe runs.\n\nFast.\n\nAfter Package Smuggler.\n\nKakashi forces himself back to his feet.\n\nBy then she is gone.\n\nSo is Package Smuggler.\n\nThe package went with him.\n\nANBU Marked Target disappeared even earlier.\n\nKakashi looks down the empty street.\n\nNo trail.\n\nNo one left to follow.\n\nThe package is beyond his reach now."},{"level":2,"title":"Objective Switch","path":"Academy Kakashi Origin — Scene 05A-L: Kakashi Loses — Verbatim Lock > Objective Switch","text":"**Return to ANBU.**"},{"level":2,"title":"Dialogue","path":"Academy Kakashi Origin — Scene 05A-L: Kakashi Loses — Verbatim Lock > Dialogue","text":"None."},{"level":2,"title":"System / Resolver","path":"Academy Kakashi Origin — Scene 05A-L: Kakashi Loses — Verbatim Lock > System / Resolver","text":"Consume:\n\n**PL BATTLE — Kakashi Hatake vs Masked Interceptor**  \n**Result: Kakashi Defeat**\n\nCommit:\n- Masked Interceptor defeats and restrains Kakashi.\n- Package Smuggler escapes with the package.\n- ANBU Marked Target has escaped.\n- Masked Interceptor leaves Kakashi's sight pursuing Package Smuggler.\n- Kakashi does not know what happens between them afterward.\n- Package recovery and pursuit are no longer available.\n- No Pakkun."},{"level":2,"title":"Choices","path":"Academy Kakashi Origin — Scene 05A-L: Kakashi Loses — Verbatim Lock > Choices","text":"- `SCENE_05A_L / CHOICE_01 / BRANCH_A` — **RETURN TO ANBU**"}]},"moveCloser":{"source":"Documentation/Story/Academy_Kakashi_Move_In_Closer_Downstream_Verbatim_Scene_Family_2026-09-19.md","sections":[{"level":1,"title":"Academy Kakashi Origin — MOVE IN CLOSER — Downstream Verbatim Scene Family","path":"Academy Kakashi Origin — MOVE IN CLOSER — Downstream Verbatim Scene Family","text":"**Date:** 2026-09-19  \n**Owner:** Writing / Story — Konoha under Stephen delegated-authoring authority  \n**Status:** **LOCKED VERBATIM / IMPLEMENTATION READY**  \n**Root branch:** `SCENE_02 / CHOICE_01 / BRANCH_B`  \n**Player-facing root choice:** **MOVE IN CLOSER**  \n**Primary priority:** **FINISH SHINOBI CHRONICLES ALPHA**"},{"level":2,"title":"1. Preserved parent scene","path":"Academy Kakashi Origin — MOVE IN CLOSER — Downstream Verbatim Scene Family > 1. Preserved parent scene","text":"The exact `MOVE IN CLOSER` resolver SUCCESS and FAILURE scenes remain governed by:\n\n`Documentation/Story/Academy_Kakashi_Get_Closer_Resolver_Split_and_Masked_Interceptor_Eligibility_Lock_2026-09-14.md`\n\nDo not rewrite those scenes.\n\nExact spatial progression remains:\n\n- `Kakashi Origin Backdrop/konoha_alleyway.png`\n- -> `Kakashi Origin Backdrop/end_of_alleyway.png`\n\nSUCCESS preserves concealment and gives Kakashi the full contingency conversation Knowledge.\n\nFAILURE exposes Kakashi, aborts the handoff, leaves the package with ANBU Marked Target and leaves Masked Interceptor unseen.\n\n---"},{"level":1,"title":"2. SUCCESS choice surface","path":"2. SUCCESS choice surface","text":"After resolver SUCCESS present exactly:\n\n1. **LET THE HANDOFF HAPPEN**\n2. **STRIKE BEFORE THE HANDOFF**\n3. **ATTEMPT THE PICKPOCKET**\n\n---"},{"level":1,"title":"3. SUCCESS -> LET THE HANDOFF HAPPEN","path":"3. SUCCESS -> LET THE HANDOFF HAPPEN","text":"**Backdrop:** `Kakashi Origin Backdrop/end_of_alleyway.png`"},{"level":2,"title":"Narration","path":"3. SUCCESS -> LET THE HANDOFF HAPPEN > Narration","text":"Kakashi stays where the shadows still cover him.\n\nHe has already heard enough to know what the two men expect to happen.\n\nThat makes waiting easier to understand.\n\nNot safer.\n\nANBU Marked Target takes the package from beneath his clothing.\n\nPackage Smuggler's hand is still waiting.\n\nThe transfer completes.\n\nThe instant it does, Kakashi's earlier information becomes fact.\n\nANBU Marked Target starts to leave.\n\nPackage Smuggler turns with the objective.\n\nThen the darkness beside the street moves.\n\nFast.\n\nA masked figure tears into the exchange line toward Package Smuggler.\n\nKakashi's eye snaps to her.\n\nHe had moved closer to learn more.\n\nNow he has more information—\n\nand one more person."},{"level":2,"title":"Scene Board transition","path":"3. SUCCESS -> LET THE HANDOFF HAPPEN > Scene Board transition","text":"`end_of_alleyway.png`\n->\n`Kakashi Origin Backdrop/sakura_tree_night.png`"},{"level":2,"title":"System / Resolver","path":"3. SUCCESS -> LET THE HANDOFF HAPPEN > System / Resolver","text":"Commit:\n\n- handoff completed;\n- package -> Package Smuggler;\n- Kakashi retains full Get Closer SUCCESS Knowledge;\n- Masked Interceptor becomes visibly eligible only after the completed handoff;\n- AMT begins leaving;\n- MI enters against PS;\n- Pakkun absent."},{"level":2,"title":"Choice surface","path":"3. SUCCESS -> LET THE HANDOFF HAPPEN > Choice surface","text":"Project the exact current Scene 03A choices:\n\n1. **STOP THE ASSASSIN**\n2. **SECURE THE PACKAGE**\n3. **SECURE THE PACKAGE BEFORE THE ASSASSIN**\n4. **DEFEAT THE ASSASSIN, THEN SECURE THE PACKAGE**\n5. **GO AFTER THE ORIGINAL TARGET**\n\nConsume the already-locked downstream Observe scene families.\n\nDo not replay the far-distance WATCH opening.\n\nPreserve the additional Get Closer SUCCESS Knowledge in later debrief / Chronicle Receipt.\n\n---"},{"level":1,"title":"4. SUCCESS -> STRIKE BEFORE THE HANDOFF","path":"4. SUCCESS -> STRIKE BEFORE THE HANDOFF","text":"The choice means the same physical intervention regardless of the fact that Kakashi first improved his position.\n\nKakashi still intervenes before AMT transfers the package.\n\nHis extra Knowledge remains part of Chronicle history."},{"level":2,"title":"Entry performance","path":"4. SUCCESS -> STRIKE BEFORE THE HANDOFF > Entry performance","text":"**Backdrop:** `Kakashi Origin Backdrop/end_of_alleyway.png`\n\nANBU Marked Target starts to move the package toward Package Smuggler's waiting hand.\n\nKakashi has already heard what happens if the street stays empty.\n\nHe decides not to let it.\n\nHe leaves the alley shadow at speed.\n\nPackage Smuggler sees him first.\n\nToo late to keep the meeting quiet.\n\n**PACKAGE SMUGGLER:**  \n“So much for the empty street.”\n\nKakashi lands between them.\n\n**KAKASHI:**  \n“You planned for this.”\n\nPackage Smuggler's expression changes.\n\nOnly slightly.\n\nKakashi heard enough to know that much.\n\nANBU Marked Target pulls the package back.\n\n**ANBU MARKED TARGET:**  \n“Then you know I keep it.”\n\n**KAKASHI:**  \n“For now.”"},{"level":2,"title":"Transition","path":"4. SUCCESS -> STRIKE BEFORE THE HANDOFF > Transition","text":"`end_of_alleyway.png`\n->\n`Kakashi Origin Backdrop/fight_at_sakura_tree.png`"},{"level":2,"title":"Battle chain","path":"4. SUCCESS -> STRIKE BEFORE THE HANDOFF > Battle chain","text":"Consume the exact fixed direct Strike Battle chain from:\n\n`Documentation/Story/Academy_Kakashi_Strike_Before_The_Handoff_Verbatim_Scene_Family_2026-09-19.md`\n\nstarting at its first PL Battle.\n\nExact sequence remains:\n\n1. Kakashi vs AMT + PS  \n   `academy_kakashi_origin_battle_amt_ps_2v1`\n2. Kakashi loss -> AMT/PS withdraw with package; MI unseen.\n3. Kakashi victory -> package -> Kakashi.\n4. MI then becomes visibly eligible because she appears specifically to take the package Kakashi recovered.\n5. Kakashi vs MI  \n   `academy_kakashi_origin_battle_mi_1v1`\n6. MI victory -> MI escapes with package.\n7. Kakashi victory -> exact group choices:\n   - **TAKE THEM TO THE UCHIHA POLICE FORCE**\n   - **TAKE THEM TO THE ANBU**\n   - **KILL THEM**\n   - **TAKE THE PACKAGE AND LET THEM GO**"},{"level":3,"title":"Additional branch fact","path":"4. SUCCESS -> STRIKE BEFORE THE HANDOFF > Battle chain > Additional branch fact","text":"Every ending/report from this route also preserves:\n\n- Kakashi successfully moved closer;\n- Kakashi overheard the full contingency conversation before intervening.\n\nDo not let the reused physical Battle chain erase that Knowledge.\n\n---"},{"level":1,"title":"5. SUCCESS -> ATTEMPT THE PICKPOCKET","path":"5. SUCCESS -> ATTEMPT THE PICKPOCKET","text":"**Backdrop:** `Kakashi Origin Backdrop/end_of_alleyway.png`"},{"level":2,"title":"Narration","path":"5. SUCCESS -> ATTEMPT THE PICKPOCKET > Narration","text":"Kakashi has already shortened the distance.\n\nNow he uses it.\n\nANBU Marked Target's hand is still over the package.\n\nPackage Smuggler is waiting.\n\nKakashi knows exactly what happens if the street stays quiet.\n\nHe tries to remove the package before either man can find out that it will not."},{"level":2,"title":"System / Resolver","path":"5. SUCCESS -> ATTEMPT THE PICKPOCKET > System / Resolver","text":"Invoke:\n\n`academy_kakashi.resolver.pickpocket_improved`\n\nExactly two factual families are legal:\n\n- `PICKPOCKET_IMPROVED_SUCCESS_CLEAN_EXTRACTION`\n- `PICKPOCKET_IMPROVED_FAILURE_DETECTED_2V1`\n\nMasked Interceptor remains unseen for both the attempted theft itself and the immediate failure Battle.\n\n---"},{"level":2,"title":"5A. Improved Pickpocket SUCCESS","path":"5. SUCCESS -> ATTEMPT THE PICKPOCKET > 5A. Improved Pickpocket SUCCESS","text":"**Backdrop:** `Kakashi Origin Backdrop/end_of_alleyway.png`"},{"level":2,"title":"Narration","path":"5. SUCCESS -> ATTEMPT THE PICKPOCKET > Narration","text":"Kakashi gets the package cleanly.\n\nCloser distance.\n\nBetter timing.\n\nOne movement hidden inside ANBU Marked Target's own reach toward the handoff.\n\nThe package disappears from beneath his clothing.\n\nKakashi disappears with it.\n\nPackage Smuggler's hand remains extended for something that is no longer there."},{"level":2,"title":"Dialogue","path":"5. SUCCESS -> ATTEMPT THE PICKPOCKET > Dialogue","text":"**PACKAGE SMUGGLER:**  \n“Where is it?”"},{"level":2,"title":"Narration","path":"5. SUCCESS -> ATTEMPT THE PICKPOCKET > Narration","text":"ANBU Marked Target checks.\n\nToo late.\n\nKakashi is already back into the alley and moving.\n\nHe keeps the information he earned.\n\nAnd the objective."},{"level":2,"title":"System / Resolver","path":"5. SUCCESS -> ATTEMPT THE PICKPOCKET > System / Resolver","text":"Commit:\n\n- package -> Kakashi;\n- handoff prevented;\n- clean withdrawal;\n- MI unseen;\n- no Battle;\n- no Pakkun;\n- full Get Closer SUCCESS Knowledge retained.\n\nSet objective:\n\n**Return to ANBU.**"},{"level":3,"title":"ANBU report distinction","path":"5. SUCCESS -> ATTEMPT THE PICKPOCKET > System / Resolver > ANBU report distinction","text":"Kakashi may legitimately report the contingency conversation he overheard before taking the package.\n\nHe still does not know the package's downstream destination because PS never revealed one.\n\n---"},{"level":2,"title":"5B. Improved Pickpocket FAILURE","path":"5. SUCCESS -> ATTEMPT THE PICKPOCKET > 5B. Improved Pickpocket FAILURE","text":"**Backdrop:** `Kakashi Origin Backdrop/sakura_tree_night.png`"},{"level":2,"title":"Narration","path":"5. SUCCESS -> ATTEMPT THE PICKPOCKET > Narration","text":"Kakashi reaches the package.\n\nANBU Marked Target catches the movement.\n\nPackage Smuggler reacts to him immediately.\n\nThe theft fails.\n\nThe clean handoff fails with it.\n\nMasked Interceptor does not appear.\n\nThis is no longer a stealth problem.\n\nIt is two men who know exactly where Kakashi is."},{"level":2,"title":"Dialogue","path":"5. SUCCESS -> ATTEMPT THE PICKPOCKET > Dialogue","text":"**PACKAGE SMUGGLER:**  \n“You should've stayed in the alley.”\n\n**KAKASHI:**  \n“You noticed me there too.”\n\n**PACKAGE SMUGGLER:**  \n“Eventually.”"},{"level":2,"title":"Battle","path":"5. SUCCESS -> ATTEMPT THE PICKPOCKET > Battle","text":"**Backdrop:** `Kakashi Origin Backdrop/fight_at_sakura_tree.png`\n\nKakashi vs AMT + PS\n\n`academy_kakashi_origin_battle_amt_ps_2v1`\n\nPakkun absent.\n\nMI unseen.\n\nAbsent another exact custody change, AMT retains the package at Battle entry.\n\n---"},{"level":3,"title":"5B-D. Kakashi loses","path":"5. SUCCESS -> ATTEMPT THE PICKPOCKET > Battle > 5B-D. Kakashi loses","text":"ANBU Marked Target and Package Smuggler break away after the fight.\n\nAMT keeps the package.\n\nThe failed handoff never becomes the Observe handoff.\n\nMI remains unseen.\n\nSet:\n\n**Return to ANBU.**\n\nCommit:\n\n- AMT escapes with package;\n- PS escapes;\n- no custody;\n- no Pakkun;\n- Get Closer SUCCESS Knowledge remains reportable.\n\n---"},{"level":2,"title":"Narration","path":"5. SUCCESS -> ATTEMPT THE PICKPOCKET > Narration","text":"Both men go down.\n\nKakashi goes to ANBU Marked Target first.\n\nThe package is still there.\n\nHe takes it.\n\nSecures it.\n\nThen looks at the two defeated men.\n\nNo masked shinobi appears.\n\nThis route never gave her a visible opening.\n\nThe package is safe.\n\nThe two men are still Kakashi's decision."},{"level":2,"title":"Choices","path":"5. SUCCESS -> ATTEMPT THE PICKPOCKET > Choices","text":"Present exactly:\n\n1. **TAKE THEM TO THE UCHIHA POLICE FORCE**\n2. **TAKE THEM TO THE ANBU**\n3. **KILL THEM**\n4. **TAKE THE PACKAGE AND LET THEM GO**"},{"level":3,"title":"Exact group continuation","path":"5. SUCCESS -> ATTEMPT THE PICKPOCKET > Choices > Exact group continuation","text":"Consume:\n\n`Documentation/Story/Academy_Kakashi_AMT_PS_Two_Target_Group_Disposition_Verbatim_Lock_2026-09-19.md`\n\ncurrent exact commit lineage includes:\n`7efacbb01328a91e5fe4cebb051e48d884ab52fd`.\n\nFor this improved-Pickpocket chronology:\n- Pakkun = absent;\n- full Get Closer SUCCESS Knowledge remains retained;\n- no MI appears.\n\n---"},{"level":1,"title":"6. FAILURE choice surface","path":"6. FAILURE choice surface","text":"After Get Closer resolver FAILURE present exactly:\n\n1. **STAY ON THE PACKAGE**\n2. **STOP PACKAGE SMUGGLER**\n3. **CUT THEM OFF AT THE SAKURA TREE**\n\n---"},{"level":1,"title":"7. FAILURE -> STAY ON THE PACKAGE","path":"7. FAILURE -> STAY ON THE PACKAGE","text":"Consume the existing Stephen-approved authority:\n\n`Documentation/Story/Academy_Kakashi_Get_Closer_Failure_Stay_On_Package_Pursuit_and_Pakkun_Interception_Lock_2026-09-14.md`\n\nCurrent exact asset correction:\n\nsuccessful Pakkun interception uses:\n\n`Kakashi Origin Backdrop/alleyway_konoha_night.png`\n\nThe approved pursuit SUCCESS choice surface remains:\n\n1. **DEMAND THE PACKAGE**\n2. **TAKE HIM DOWN**\n3. **ASK WHERE THE PACKAGE WAS GOING**\n\nConsume existing Demand / Take Him Down / Ask Where Package authority.\n\nPakkun remains until explicit departure.\n\nNo MI appears because the original handoff never completed.\n\n---"},{"level":1,"title":"8. FAILURE -> STOP PACKAGE SMUGGLER","path":"8. FAILURE -> STOP PACKAGE SMUGGLER","text":"The existing confrontation opening remains valid and is preserved:\n\nANBU Marked Target is already moving away.\n\nThe package goes with him.\n\nPackage Smuggler is coming toward Kakashi instead.\n\nKakashi looks once toward the Sakura tree.\n\nThen stops looking.\n\nHe steps out of the alley.\n\nPackage Smuggler slows.\n\n**PACKAGE SMUGGLER:**  \n“Wrong one.”\n\nKakashi's eye settles on him.\n\n**KAKASHI:**  \n“You were waiting for it.”\n\nThe man glances toward the street where ANBU Marked Target disappeared.\n\n**PACKAGE SMUGGLER:**  \n“Was.”\n\n**KAKASHI:**  \n“Then you know where it was going.”\n\nA faint smile.\n\n**PACKAGE SMUGGLER:**  \n“And you chose me instead of following it.”\n\nKakashi shifts his footing.\n\n**KAKASHI:**  \n“I chose to stop you.”\n\nThe smile disappears.\n\nPackage Smuggler reaches for his weapon.\n\n**PACKAGE SMUGGLER:**  \n“Then stop me.”"},{"level":2,"title":"Battle","path":"8. FAILURE -> STOP PACKAGE SMUGGLER > Battle","text":"PS-focused environment:\n\n`Kakashi Origin Backdrop/konoha_alleyway_alt_night.png`\n\nKakashi vs Package Smuggler\n\n`academy_kakashi_origin_battle_ps_1v1`\n\nMeanwhile:\n\n- AMT escapes with package;\n- MI unseen;\n- Pakkun absent.\n\n---"},{"level":2,"title":"8A. PS defeats Kakashi","path":"8. FAILURE -> STOP PACKAGE SMUGGLER > 8A. PS defeats Kakashi","text":"Package Smuggler gets away.\n\nANBU Marked Target is already gone with the objective.\n\nKakashi ends with neither package nor prisoner.\n\nSet:\n\n**Return to ANBU.**\n\n---"},{"level":2,"title":"8B. Kakashi defeats PS","path":"8. FAILURE -> STOP PACKAGE SMUGGLER > 8B. Kakashi defeats PS","text":"The package is still gone with AMT.\n\nPackage Smuggler is defeated and physically available.\n\nPresent exactly:\n\n1. **KILL HIM**\n2. **RESTRAIN HIM**\n3. **BRING HIM TO THE ANBU**\n4. **TAKE HIM TO THE UCHIHA POLICE FORCE**"},{"level":3,"title":"Exact singular PS continuation","path":"8. FAILURE -> STOP PACKAGE SMUGGLER > 8B. Kakashi defeats PS > Exact singular PS continuation","text":"Consume:\n\n`Documentation/Story/Academy_Kakashi_Package_Missing_PS_Post_Battle_Disposition_Verbatim_Lock_2026-09-19.md`\n\ncurrent exact commit:\n`ea3752e0023b8c5cbd838a749f40353af8157184`.\n\nThat lock owns exact:\n- **KILL HIM**\n- **RESTRAIN HIM**\n- **BRING HIM TO THE ANBU**\n- **TAKE HIM TO THE UCHIHA POLICE FORCE**\n\nincluding the package-missing PS ANBU return and Police handoff.\n\n---"},{"level":1,"title":"9. FAILURE -> CUT THEM OFF AT THE SAKURA TREE","path":"9. FAILURE -> CUT THEM OFF AT THE SAKURA TREE","text":"The existing opening remains:\n\nKakashi does not follow either man.\n\nHe cuts across both of them.\n\nStraight for the Sakura tree.\n\nANBU Marked Target sees him first.\n\nPackage Smuggler sees what Kakashi is doing half a second later.\n\n**PACKAGE SMUGGLER:**  \n“Don't let him get in front of you!”\n\nToo late.\n\nKakashi reaches the remaining exit line.\n\nANBU Marked Target turns—\n\nand stops.\n\nA small ninken is standing in the street he was about to use.\n\nThe man stares down at him.\n\n**ANBU MARKED TARGET:**  \n“Oh, come on.”\n\nPakkun looks past him.\n\nAt Kakashi.\n\n**PAKKUN:**  \n“This yours?”\n\nKakashi reaches the other side of the choke point.\n\nPackage Smuggler arrives behind him.\n\nKakashi looks at ANBU Marked Target.\n\n**KAKASHI:**  \n“Apparently.”\n\nA beat.\n\n**KAKASHI:**  \n“Thanks.”\n\nNo names are exchanged."},{"level":2,"title":"Pakkun scope correction","path":"9. FAILURE -> CUT THEM OFF AT THE SAKURA TREE > Pakkun scope correction","text":"Pakkun is visibly and factually present in Story.\n\nHowever the current exact Combat configuration:\n\n`academy_kakashi_origin_battle_amt_ps_2v1`\n\nhas **no Pakkun Battle action source**.\n\nTherefore:\n\n- Pakkun helps create/hold the Story choke point;\n- Pakkun does not receive a selectable Combat action in this exact Battle;\n- no Summon ownership is created;\n- after Battle Pakkun remains present in Story until explicit departure."},{"level":2,"title":"Battle","path":"9. FAILURE -> CUT THEM OFF AT THE SAKURA TREE > Battle","text":"**Backdrop:** `Kakashi Origin Backdrop/fight_at_sakura_tree.png`\n\nKakashi vs AMT + PS\n\n`academy_kakashi_origin_battle_amt_ps_2v1`\n\nAMT holds the package at Battle entry.\n\nMI remains unseen.\n\n---"},{"level":2,"title":"9A. Kakashi loses","path":"9. FAILURE -> CUT THEM OFF AT THE SAKURA TREE > 9A. Kakashi loses","text":"Both men break containment.\n\nAMT escapes with package.\n\nPS escapes.\n\nPakkun remains with Kakashi after the field clears.\n\nSet:\n\n**Return to ANBU.**\n\nUse the existing explicit/neutral Pakkun departure before private Minato evaluation.\n\n---"},{"level":2,"title":"Narration","path":"9. FAILURE -> CUT THEM OFF AT THE SAKURA TREE > Narration","text":"Both men go down inside the space Kakashi cut them into.\n\nPakkun stays near the exit.\n\nKakashi goes to ANBU Marked Target.\n\nThe package is still there.\n\nHe recovers it.\n\nThen looks at both defeated men.\n\nNeither has automatically become a prisoner.\n\nNeither has automatically escaped merely because the Battle ended."},{"level":2,"title":"Choices","path":"9. FAILURE -> CUT THEM OFF AT THE SAKURA TREE > Choices","text":"Present exactly:\n\n1. **TAKE THEM TO THE UCHIHA POLICE FORCE**\n2. **TAKE THEM TO THE ANBU**\n3. **KILL THEM**\n4. **TAKE THE PACKAGE AND LET THEM GO**"},{"level":3,"title":"Exact group continuation","path":"9. FAILURE -> CUT THEM OFF AT THE SAKURA TREE > Choices > Exact group continuation","text":"Consume:\n\n`Documentation/Story/Academy_Kakashi_AMT_PS_Two_Target_Group_Disposition_Verbatim_Lock_2026-09-19.md`\n\ncurrent exact commit:\n`7efacbb01328a91e5fe4cebb051e48d884ab52fd`.\n\nFor this CUT THEM OFF chronology:\n- Pakkun = present in Story;\n- Pakkun remains until explicit departure;\n- package = Kakashi;\n- AMT + PS = defeated/available;\n- MI = unseen.\n\n---"},{"level":1,"title":"10. Group handoff / report law for MOVE IN CLOSER","path":"10. Group handoff / report law for MOVE IN CLOSER","text":"Where a branch produces multiple restrained captives, reuse the established state-driven group transfer architecture:\n\n- one player intent;\n- participant-level institutional commits;\n- exact package transfer separately;\n- Pakkun only where legitimately present;\n- no “group prisoner” factual shortcut.\n\nWhere a branch ends in factual report rather than custody transfer:\n\nANBU debrief must preserve:\n\n- Get Closer SUCCESS or FAILURE;\n- exact Knowledge earned;\n- package holder/history;\n- each materially encountered participant;\n- Battle result(s);\n- exact disposition;\n- Pakkun involvement where applicable.\n\n---"},{"level":3,"title":"SUCCESS","path":"11. Knowledge continuity > SUCCESS","text":"Kakashi retains:\n\n- the contingency conversation;\n- that AMT was meant to hand the package to PS;\n- that if followed, AMT was meant to keep walking with it;\n- that PS did not reveal the downstream destination."},{"level":3,"title":"FAILURE","path":"11. Knowledge continuity > FAILURE","text":"Kakashi retains only the partial conversation heard before detection.\n\nDo not upgrade FAILURE Knowledge to SUCCESS Knowledge merely because later fights expose the same participants.\n\n---"},{"level":1,"title":"12. Final lock","path":"12. Final lock","text":"> **MOVE IN CLOSER remains a resolver split with distinct SUCCESS and FAILURE histories.**\n\n> **SUCCESS -> LET THE HANDOFF HAPPEN reconverges into the Observe escalation without replaying the far-distance WATCH opening and preserves extra Knowledge.**\n\n> **SUCCESS -> STRIKE BEFORE THE HANDOFF uses the fixed AMT+PS 2-v-1 -> package recovery -> MI arrival -> MI 1-v-1 chain while retaining Get Closer Knowledge.**\n\n> **SUCCESS -> ATTEMPT THE PICKPOCKET success is a clean extraction; failure is AMT+PS 2-v-1 with MI unseen.**\n\n> **FAILURE -> STAY ON THE PACKAGE retains the approved Pakkun pursuit family.**\n\n> **FAILURE -> STOP PACKAGE SMUGGLER uses the PS-specific alternate-night backdrop and modern post-Battle agency.**\n\n> **FAILURE -> CUT THEM OFF AT THE SAKURA TREE keeps Pakkun present in Story but does not grant him Combat actions in a non-Pakkun config; victory produces package recovery plus a clean group disposition instead of automatic AMT custody / PS escape.**"}]},"directStrike":{"source":"Documentation/Story/Academy_Kakashi_Strike_Before_The_Handoff_Verbatim_Scene_Family_2026-09-19.md","sections":[{"level":1,"title":"Academy Kakashi Origin — STRIKE BEFORE THE HANDOFF — Verbatim Scene Family","path":"Academy Kakashi Origin — STRIKE BEFORE THE HANDOFF — Verbatim Scene Family","text":"**Date:** 2026-09-19  \n**Owner:** Writing / Story — Konoha under Stephen delegated-authoring authority  \n**Status:** **LOCKED VERBATIM — IMPLEMENTATION READY**  \n**Branch:** `SCENE_02 / CHOICE_01 / BRANCH_C`  \n**Player-facing entry choice:** **STRIKE BEFORE THE HANDOFF**  \n**Primary priority:** **FINISH SHINOBI CHRONICLES ALPHA**"},{"level":2,"title":"Stephen correction / branch identity","path":"Academy Kakashi Origin — STRIKE BEFORE THE HANDOFF — Verbatim Scene Family > Stephen correction / branch identity","text":"Stephen has closed the direct Scene 02 Attack route as a fixed Battle chain:\n\n`STRIKE BEFORE THE HANDOFF`\n-> Kakashi vs ANBU Marked Target + Package Smuggler **2-v-1**\n-> if Kakashi wins, Kakashi secures the package\n-> Masked Interceptor makes her appearance specifically to take the package\n-> Kakashi vs Masked Interceptor **1-v-1**\n-> final factual disposition.\n\nThis supersedes the older five-class resolver lottery for **this direct Scene 02 branch**.\n\nIt does **not** silently rewrite the separate:\n\n`MOVE IN CLOSER -> STRIKE BEFORE THE HANDOFF`\n\ncontinuation.\n\n---"},{"level":1,"title":"1. STRIKE BEFORE THE HANDOFF","path":"1. STRIKE BEFORE THE HANDOFF","text":"**Backdrop:** `Kakashi Origin Backdrop/sakura_tree_night.png`\n\n**Objective:** **Stop the handoff.**"},{"level":2,"title":"Narration","path":"1. STRIKE BEFORE THE HANDOFF > Narration","text":"ANBU Marked Target reaches for the package.\n\nPackage Smuggler shifts forward to receive it.\n\nKakashi moves before either man can finish.\n\nNo waiting.\n\nNo attempt to learn more.\n\nHe drops directly into the space between them.\n\nANBU Marked Target pulls the package back.\n\nPackage Smuggler turns toward Kakashi instead.\n\nThe quiet handoff is over before it can happen."},{"level":2,"title":"Dialogue","path":"1. STRIKE BEFORE THE HANDOFF > Dialogue","text":"**PACKAGE SMUGGLER:**  \n“You could've kept watching.”\n\n**KAKASHI:**  \n“I saw enough.”"},{"level":2,"title":"Narration","path":"1. STRIKE BEFORE THE HANDOFF > Narration","text":"ANBU Marked Target shifts the package away from Kakashi.\n\nPackage Smuggler moves to the other side.\n\nTwo angles.\n\nOne objective.\n\nKakashi settles into stance."},{"level":2,"title":"Dialogue","path":"1. STRIKE BEFORE THE HANDOFF > Dialogue","text":"**ANBU MARKED TARGET:**  \n“You're alone.”\n\n**KAKASHI:**  \n“For now.”"},{"level":2,"title":"Narration","path":"1. STRIKE BEFORE THE HANDOFF > Narration","text":"Neither man gives him time to explain what he means.\n\n---"},{"level":1,"title":"2. First PL Battle — Kakashi vs AMT + PS","path":"2. First PL Battle — Kakashi vs AMT + PS","text":"**Backdrop:** `Kakashi Origin Backdrop/fight_at_sakura_tree.png`\n\nBattle config:\n\n`academy_kakashi_origin_battle_amt_ps_2v1`\n\nOpposition:\n\n- ANBU Marked Target;\n- Package Smuggler.\n\nMasked Interceptor is **not yet present**.\n\nPakkun is not present.\n\nAt Battle entry:\n\n- the clean handoff has been prevented;\n- package remains with ANBU Marked Target;\n- no participant custody/death has committed.\n\n---"},{"level":1,"title":"3. Kakashi loses the 2-v-1","path":"3. Kakashi loses the 2-v-1","text":"**Backdrop:** `Kakashi Origin Backdrop/fight_at_sakura_tree.png`"},{"level":2,"title":"Narration","path":"3. Kakashi loses the 2-v-1 > Narration","text":"Kakashi loses the fight before he ever gets control of the package.\n\nANBU Marked Target does not wait for a second chance.\n\nPackage Smuggler pulls back with him.\n\nThe interrupted handoff never becomes clean.\n\nIt no longer needs to.\n\nThey already know Kakashi is there.\n\nANBU Marked Target keeps the package and both men withdraw together.\n\nKakashi forces himself back to his feet.\n\nThe street is empty.\n\nNo masked shinobi appears.\n\nThere is nothing left here for her to take from Kakashi.\n\nHe never had the package."},{"level":2,"title":"Objective switch","path":"3. Kakashi loses the 2-v-1 > Objective switch","text":"Remove:\n\n**Stop the handoff.**\n\nSet:\n\n**Return to ANBU.**"},{"level":2,"title":"System / Resolver","path":"3. Kakashi loses the 2-v-1 > System / Resolver","text":"Commit:\n\n- Kakashi loses the AMT + PS 2-v-1;\n- package remains with ANBU Marked Target;\n- AMT escapes;\n- PS escapes with him;\n- intended clean handoff was interrupted and does not retroactively become the Observe handoff;\n- MI remains unseen;\n- no Pakkun;\n- no participant custody;\n- no participant death.\n\nProceed to factual ANBU report / terminal evaluation.\n\n---"},{"level":1,"title":"4. Kakashi wins the 2-v-1","path":"4. Kakashi wins the 2-v-1","text":"**Backdrop:** `Kakashi Origin Backdrop/fight_at_sakura_tree.png`"},{"level":2,"title":"Narration","path":"4. Kakashi wins the 2-v-1 > Narration","text":"Package Smuggler goes down first.\n\nANBU Marked Target lasts longer.\n\nNot long enough.\n\nWhen the fight ends, both men are on the ground.\n\nKakashi's attention goes straight to the package.\n\nANBU Marked Target still has it.\n\nKakashi takes it.\n\nChecks the seal.\n\nSecures it against himself.\n\nThe handoff is stopped.\n\nThe objective is finally in his control.\n\nThen the street changes."},{"level":2,"title":"System / Resolver","path":"4. Kakashi wins the 2-v-1 > System / Resolver","text":"Commit independently:\n\n- AMT Battle-defeated;\n- PS Battle-defeated;\n- package custody -> Kakashi;\n- no AMT/PS death from Battle victory;\n- no AMT/PS institutional custody from Battle victory.\n\nDo not surface a disposition menu yet.\n\nA new participant action interrupts first.\n\n---"},{"level":1,"title":"5. Masked Interceptor arrives","path":"5. Masked Interceptor arrives","text":"**Backdrop:** `Kakashi Origin Backdrop/sakura_tree_night.png`"},{"level":2,"title":"Narration","path":"5. Masked Interceptor arrives > Narration","text":"Movement cuts across the far side of the Sakura tree.\n\nFast.\n\nDirect.\n\nA masked shinobi lands between Kakashi and the open street.\n\nHer attention does not go to either defeated man.\n\nIt goes to the package secured against Kakashi.\n\nKakashi notices."},{"level":2,"title":"Dialogue","path":"5. Masked Interceptor arrives > Dialogue","text":"**KAKASHI:**  \n“You're late.”\n\n**MASKED INTERCEPTOR:**  \n“Not for what I came for.”"},{"level":2,"title":"Narration","path":"5. Masked Interceptor arrives > Narration","text":"Her eyes stay on the package.\n\nKakashi shifts his weight."},{"level":2,"title":"Dialogue","path":"5. Masked Interceptor arrives > Dialogue","text":"**KAKASHI:**  \n“You want this.”\n\n**MASKED INTERCEPTOR:**  \n“I want you to put it down.”\n\n**KAKASHI:**  \n“No.”"},{"level":2,"title":"Narration","path":"5. Masked Interceptor arrives > Narration","text":"Masked Interceptor moves.\n\nSo does Kakashi.\n\n---"},{"level":1,"title":"6. Second PL Battle — Kakashi vs MI","path":"6. Second PL Battle — Kakashi vs MI","text":"**Backdrop:** `Kakashi Origin Backdrop/fight_at_sakura_tree.png`\n\nBattle config:\n\n`academy_kakashi_origin_battle_mi_1v1`\n\nThis is a direct/non-sequential MI-only Battle.\n\nNo `<=4` sequential timing gate applies.\n\nBattle-entry facts:\n\n- AMT defeated;\n- PS defeated;\n- package held by Kakashi;\n- MI present specifically to take the package;\n- Pakkun absent.\n\n---"},{"level":1,"title":"7. MI defeats Kakashi","path":"7. MI defeats Kakashi","text":"**Backdrop:** `Kakashi Origin Backdrop/fight_at_sakura_tree.png`"},{"level":2,"title":"Narration","path":"7. MI defeats Kakashi > Narration","text":"Masked Interceptor breaks through Kakashi's defence.\n\nHe keeps one hand near the package.\n\nShe notices.\n\nThe next exchange is about that hand.\n\nKakashi loses it.\n\nThe package comes free.\n\nMasked Interceptor catches it before it hits the ground.\n\nFor half a second, she looks down at the seal.\n\nThen back at Kakashi."},{"level":2,"title":"Dialogue","path":"7. MI defeats Kakashi > Dialogue","text":"**MASKED INTERCEPTOR:**  \n“You should've left after the first fight.”\n\n**KAKASHI:**  \n“You would've followed.”"},{"level":2,"title":"Narration","path":"7. MI defeats Kakashi > Narration","text":"A small pause."},{"level":2,"title":"Dialogue","path":"7. MI defeats Kakashi > Dialogue","text":"**MASKED INTERCEPTOR:**  \n“Probably.”"},{"level":2,"title":"Narration","path":"7. MI defeats Kakashi > Narration","text":"She disappears with the package.\n\nKakashi looks toward the two men he defeated earlier.\n\nStill alive.\n\nStill where the fights left them.\n\nBut Kakashi no longer controls the objective, and he is in no condition to turn the street into a third confrontation."},{"level":2,"title":"Objective switch","path":"7. MI defeats Kakashi > Objective switch","text":"Set:\n\n**Return to ANBU.**"},{"level":2,"title":"System / Resolver","path":"7. MI defeats Kakashi > System / Resolver","text":"Commit:\n\n- MI Battle victory;\n- package custody -> MI;\n- MI escapes with package;\n- AMT remains alive / Battle-defeated, no institutional custody;\n- PS remains alive / Battle-defeated, no institutional custody;\n- no Pakkun;\n- no invented later AMT/PS action after Kakashi leaves.\n\nProceed to factual ANBU report.\n\n---"},{"level":1,"title":"8. Kakashi defeats MI","path":"8. Kakashi defeats MI","text":"**Backdrop:** `Kakashi Origin Backdrop/fight_at_sakura_tree.png`"},{"level":2,"title":"Narration","path":"8. Kakashi defeats MI > Narration","text":"Masked Interceptor hits the ground.\n\nKakashi stays between her and the package until he is certain she is not getting another attempt.\n\nThen he looks across the street.\n\nANBU Marked Target.\n\nPackage Smuggler.\n\nMasked Interceptor.\n\nAll three defeated.\n\nThe package is still secured against Kakashi.\n\nThis time, nothing else arrives.\n\nThe next decision is his."},{"level":2,"title":"System / Resolver","path":"8. Kakashi defeats MI > System / Resolver","text":"Commit independently:\n\n- MI Battle-defeated;\n- AMT Battle-defeated from first Battle;\n- PS Battle-defeated from first Battle;\n- package remains with Kakashi;\n- no participant death/custody inferred merely from Battle victories;\n- no Pakkun."},{"level":2,"title":"Choices","path":"8. Kakashi defeats MI > Choices","text":"Present exactly:\n\n1. **TAKE THEM TO THE UCHIHA POLICE FORCE**\n2. **TAKE THEM TO THE ANBU**\n3. **KILL THEM**\n4. **TAKE THE PACKAGE AND LET THEM GO**\n\n---"},{"level":2,"title":"Narration","path":"9. TAKE THEM TO THE UCHIHA POLICE FORCE > Narration","text":"Kakashi draws the ninja wire.\n\nPackage Smuggler sees it and closes his eyes for a moment."},{"level":2,"title":"Dialogue","path":"9. TAKE THEM TO THE UCHIHA POLICE FORCE > Dialogue","text":"**PACKAGE SMUGGLER:**  \n“I knew the night was getting worse.”\n\n**MASKED INTERCEPTOR:**  \n“You talk too much.”\n\n**PACKAGE SMUGGLER:**  \n“I've had a difficult evening.”"},{"level":2,"title":"Narration","path":"9. TAKE THEM TO THE UCHIHA POLICE FORCE > Narration","text":"Kakashi restrains them individually.\n\nANBU Marked Target.\n\nPackage Smuggler.\n\nMasked Interceptor.\n\nThe package remains secured against him."},{"level":2,"title":"Dialogue","path":"9. TAKE THEM TO THE UCHIHA POLICE FORCE > Dialogue","text":"**ANBU MARKED TARGET:**  \n“Where are you taking us?”\n\n**KAKASHI:**  \n“Uchiha Police Force.”"},{"level":2,"title":"Narration","path":"9. TAKE THEM TO THE UCHIHA POLICE FORCE > Narration","text":"Package Smuggler looks at the others."},{"level":2,"title":"Dialogue","path":"9. TAKE THEM TO THE UCHIHA POLICE FORCE > Dialogue","text":"**PACKAGE SMUGGLER:**  \n“Anyone want to try him again?”"},{"level":2,"title":"Narration","path":"9. TAKE THEM TO THE UCHIHA POLICE FORCE > Narration","text":"Nobody answers."},{"level":2,"title":"Transition","path":"9. TAKE THEM TO THE UCHIHA POLICE FORCE > Transition","text":"**BLACK WIPE**"},{"level":3,"title":"Uchiha Police handoff","path":"9. TAKE THEM TO THE UCHIHA POLICE FORCE > Transition > Uchiha Police handoff","text":"**Backdrop:** `Kakashi Origin Backdrop/uchiha_police_exterior_night.png`\n\nTwo officers meet Kakashi outside.\n\nOne looks at the three prisoners.\n\nThen at Kakashi.\n\nThen at the package."},{"level":2,"title":"Dialogue","path":"9. TAKE THEM TO THE UCHIHA POLICE FORCE > Dialogue","text":"**UCHIHA POLICE OFFICER:**  \n“Start talking.”"},{"level":2,"title":"Narration","path":"9. TAKE THEM TO THE UCHIHA POLICE FORCE > Narration","text":"Kakashi gives the chronology exactly as it happened.\n\nHe interrupted the handoff.\n\nThe two men fought him.\n\nHe recovered the package.\n\nThe masked shinobi arrived afterward and tried to take it.\n\nHe defeated her too.\n\nThe officer looks at the three prisoners."},{"level":2,"title":"Dialogue","path":"9. TAKE THEM TO THE UCHIHA POLICE FORCE > Dialogue","text":"**UCHIHA POLICE OFFICER:**  \n“All three?”\n\n**KAKASHI:**  \n“Yes.”\n\n**PACKAGE SMUGGLER:**  \n“He's very concise about it.”"},{"level":2,"title":"Narration","path":"9. TAKE THEM TO THE UCHIHA POLICE FORCE > Narration","text":"The officers accept custody one person at a time.\n\nNo aggregate prisoner state replaces the three individual transfers."},{"level":2,"title":"System / Resolver","path":"9. TAKE THEM TO THE UCHIHA POLICE FORCE > System / Resolver","text":"Commit separately:\n\n- AMT -> Uchiha Police institutional custody;\n- PS -> Uchiha Police institutional custody;\n- MI -> Uchiha Police institutional custody;\n- package remains with Kakashi.\n\nSet objective:\n\n**Return to ANBU.**\n\n---"},{"level":2,"title":"Narration","path":"10. TAKE THEM TO THE ANBU > Narration","text":"Kakashi restrains all three with ninja wire.\n\nPackage Smuggler watches the last line tighten."},{"level":2,"title":"Dialogue","path":"10. TAKE THEM TO THE ANBU > Dialogue","text":"**PACKAGE SMUGGLER:**  \n“ANBU?”\n\n**KAKASHI:**  \n“Yes.”\n\n**PACKAGE SMUGGLER:**  \n“I preferred not knowing.”"},{"level":2,"title":"Narration","path":"10. TAKE THEM TO THE ANBU > Narration","text":"Masked Interceptor looks at him."},{"level":2,"title":"Dialogue","path":"10. TAKE THEM TO THE ANBU > Dialogue","text":"**MASKED INTERCEPTOR:**  \n“You still don't.”"},{"level":2,"title":"Transition","path":"10. TAKE THEM TO THE ANBU > Transition","text":"**BLACK WIPE**"},{"level":3,"title":"ANBU rooftop","path":"10. TAKE THEM TO THE ANBU > Transition > ANBU rooftop","text":"**Backdrop:** `Kakashi Origin Backdrop/rooftop_night.png`\n\nThe ANBU operative turns.\n\nHis gaze goes to the package.\n\nThen to the three restrained shinobi Kakashi brought with it."},{"level":2,"title":"Dialogue","path":"10. TAKE THEM TO THE ANBU > Dialogue","text":"**ANBU OPERATIVE:**  \n“Report.”"},{"level":2,"title":"Narration","path":"10. TAKE THEM TO THE ANBU > Narration","text":"Kakashi hands over the package first.\n\nThen gives the sequence.\n\nThe interrupted handoff.\n\nThe first fight.\n\nThe package recovery.\n\nMasked Interceptor's arrival.\n\nThe second fight.\n\nThree live prisoners.\n\nThe operative waits until Kakashi finishes."},{"level":2,"title":"Dialogue","path":"10. TAKE THEM TO THE ANBU > Dialogue","text":"**ANBU OPERATIVE:**  \n“You brought everyone.”\n\n**KAKASHI:**  \n“They were all still there.”"},{"level":2,"title":"Narration","path":"10. TAKE THEM TO THE ANBU > Narration","text":"Package Smuggler makes a small sound."},{"level":2,"title":"Dialogue","path":"10. TAKE THEM TO THE ANBU > Dialogue","text":"**PACKAGE SMUGGLER:**  \n“That's one way to describe it.”"},{"level":2,"title":"Narration","path":"10. TAKE THEM TO THE ANBU > Narration","text":"The operative steps forward."},{"level":2,"title":"Dialogue","path":"10. TAKE THEM TO THE ANBU > Dialogue","text":"**ANBU OPERATIVE:**  \n“We'll take custody.”"},{"level":2,"title":"System / Resolver","path":"10. TAKE THEM TO THE ANBU > System / Resolver","text":"Transfer separately:\n\n- AMT -> ANBU institutional custody;\n- PS -> ANBU institutional custody;\n- MI -> ANBU institutional custody;\n- package -> ANBU custody.\n\n---"},{"level":2,"title":"Narration","path":"11. KILL THEM > Narration","text":"Kakashi looks at all three defeated shinobi.\n\nThe package is secure.\n\nNo one is still fighting him for it.\n\nHe makes one decision.\n\nThe result is three separate deaths.\n\nThere is no celebration.\n\nNo speech.\n\nNo attempt to make the choice sound lighter afterward.\n\nWhen it is finished, Kakashi is the only shinobi still standing beneath the Sakura tree.\n\nThe package remains with him."},{"level":2,"title":"System / Resolver","path":"11. KILL THEM > System / Resolver","text":"Commit separately:\n\n- AMT -> dead;\n- PS -> dead;\n- MI -> dead.\n\nEach death records:\n\n- deterministic post-Battle lethal provenance;\n- exact participant identity;\n- this shared group disposition occurrence;\n- package custody remains with Kakashi.\n\nSet objective:\n\n**Return to ANBU.**\n\nThe factual ANBU report must state that Kakashi killed all three after defeating them.\n\nDo not describe the deaths as Battle casualties.\n\n---"},{"level":2,"title":"Narration","path":"12. TAKE THE PACKAGE AND LET THEM GO > Narration","text":"Kakashi checks the package.\n\nStill secure.\n\nThen he looks at the three defeated shinobi.\n\nHe does not reach for wire.\n\nPackage Smuggler notices."},{"level":2,"title":"Dialogue","path":"12. TAKE THE PACKAGE AND LET THEM GO > Dialogue","text":"**PACKAGE SMUGGLER:**  \n“We're leaving?”\n\n**KAKASHI:**  \n“Yes.”\n\n**PACKAGE SMUGGLER:**  \n“With nothing.”"},{"level":2,"title":"Narration","path":"12. TAKE THE PACKAGE AND LET THEM GO > Narration","text":"Kakashi looks at him."},{"level":2,"title":"Dialogue","path":"12. TAKE THE PACKAGE AND LET THEM GO > Dialogue","text":"**KAKASHI:**  \n“That's the idea.”"},{"level":2,"title":"Narration","path":"12. TAKE THE PACKAGE AND LET THEM GO > Narration","text":"ANBU Marked Target gets to his feet slowly.\n\nMasked Interceptor follows.\n\nShe looks once at the package.\n\nThen at Kakashi."},{"level":2,"title":"Dialogue","path":"12. TAKE THE PACKAGE AND LET THEM GO > Dialogue","text":"**MASKED INTERCEPTOR:**  \n“You think that's finished?”\n\n**KAKASHI:**  \n“For tonight.”"},{"level":2,"title":"Narration","path":"12. TAKE THE PACKAGE AND LET THEM GO > Narration","text":"She holds his gaze for a moment.\n\nThen leaves.\n\nThe other two go with their own reasons for not trying again.\n\nKakashi keeps the package."},{"level":2,"title":"System / Resolver","path":"12. TAKE THE PACKAGE AND LET THEM GO > System / Resolver","text":"Commit separately:\n\n- AMT alive / deliberately released;\n- PS alive / deliberately released;\n- MI alive / deliberately released;\n- no participant custody;\n- package remains with Kakashi;\n- no immediate pursuit is reopened;\n- release != escape.\n\nSet objective:\n\n**Return to ANBU.**\n\n---"},{"level":1,"title":"13. Factual ANBU report projections","path":"13. Factual ANBU report projections","text":"**Backdrop:** `Kakashi Origin Backdrop/rooftop_night.png`\n\nThe report always preserves:\n\n- Kakashi selected **STRIKE BEFORE THE HANDOFF**;\n- intended clean handoff was prevented;\n- AMT + PS fought Kakashi together;\n- first Battle result;\n- if Kakashi won: package recovery;\n- MI's later package attempt;\n- second Battle result if it occurred;\n- exact package final holder;\n- exact final disposition of AMT / PS / MI.\n\nDo not rewrite the chronology into the Observe handoff.\n\nDo not say MI was present during the first Battle.\n\nDo not infer Pakkun.\n\n---"},{"level":1,"title":"14. Terminal continuation","path":"14. Terminal continuation","text":"After factual report / completed institutional transfer:\n\n- consume existing private Minato evaluation;\n- Chronicle Receipt;\n- reward closure;\n- exact Battle-development evidence from both Battles where they occurred;\n- package success/failure independently from participant disposition.\n\n---"},{"level":1,"title":"Final lock","path":"Final lock","text":"> **Direct Scene 02 STRIKE BEFORE THE HANDOFF is no longer a five-result Attack resolver lottery.**\n\n> **It is Kakashi vs AMT + PS 2-v-1.**\n\n> **Kakashi victory secures the package.**\n\n> **Masked Interceptor then appears to take the package, causing Kakashi vs MI 1-v-1.**\n\n> **2-v-1 defeat ends the active field route without MI appearing to fight Kakashi.**\n\n> **MI victory takes the package away from Kakashi.**\n\n> **MI defeat leaves all three opponents defeated and the package with Kakashi, then presents exactly: TAKE THEM TO THE UCHIHA POLICE FORCE / TAKE THEM TO THE ANBU / KILL THEM / TAKE THE PACKAGE AND LET THEM GO.**\n\n> **The separate MOVE IN CLOSER -> STRIKE BEFORE THE HANDOFF continuation is not changed by this lock.**"}]},"directPickpocket":{"source":"Documentation/Story/Academy_Kakashi_Direct_Pickpocket_Verbatim_Scene_Family_2026-09-19.md","sections":[{"level":1,"title":"Academy Kakashi Origin — SLIP IN FOR THE PACKAGE — Verbatim Scene Family","path":"Academy Kakashi Origin — SLIP IN FOR THE PACKAGE — Verbatim Scene Family","text":"**Date:** 2026-09-19  \n**Owner:** Writing / Story — Konoha under Stephen delegated-authoring authority  \n**Status:** **LOCKED VERBATIM — DELEGATED CLEAN CONTINUATION / IMPLEMENTATION READY**  \n**Branch:** `SCENE_02 / CHOICE_01 / BRANCH_D`  \n**Player-facing entry choice:** **SLIP IN FOR THE PACKAGE**  \n**Primary priority:** **FINISH SHINOBI CHRONICLES ALPHA**"},{"level":2,"title":"Consumed authority","path":"Academy Kakashi Origin — SLIP IN FOR THE PACKAGE — Verbatim Scene Family > Consumed authority","text":"- Scene 02 exact verbatim lock;\n- Sakura Exchange First Choice causal authority;\n- Decision-Continuation Matrix + Pickpocket route lock;\n- Final Structured Autonomy Anchor Reconciliation;\n- current Combat config surface;\n- current Writing benchmark / personality law;\n- exact Kakashi backdrop inventory.\n\nThe defining semantic is locked:\n\n> **Success = Kakashi removes the package and disappears before either exchange participant knows what happened.**\n\n> **Failure = Kakashi is detected, Masked Interceptor enters as the specific failed-Pickpocket exception, and Kakashi fights AMT + Package Smuggler + Masked Interceptor simultaneously.**\n\n---"},{"level":1,"title":"1. SLIP IN FOR THE PACKAGE","path":"1. SLIP IN FOR THE PACKAGE","text":"**Backdrop:** `Kakashi Origin Backdrop/sakura_tree_night.png`\n\n**Objective:** **Stop the package from falling into the wrong hands.**"},{"level":2,"title":"Narration","path":"1. SLIP IN FOR THE PACKAGE > Narration","text":"Kakashi does not wait for the handoff.\n\nHe watches the space between the two men instead.\n\nThe package is still with ANBU Marked Target.\n\nPackage Smuggler is waiting to receive it.\n\nNeither of them is looking for a third set of hands.\n\nThat is the opening.\n\nKakashi drops from cover without making the street notice him.\n\nOne step.\n\nThen another.\n\nClose enough now to see the edge of the package beneath ANBU Marked Target's clothing.\n\nClose enough to take it.\n\nIf he is clean."},{"level":2,"title":"System / Resolver","path":"1. SLIP IN FOR THE PACKAGE > System / Resolver","text":"Invoke the direct Pickpocket resolver.\n\nExactly two route families are legal:\n\n- **SUCCESS — clean extraction**\n- **FAILURE — detected / 3-v-1 escalation**\n\nDo not infer the result from the choice label.\n\n---"},{"level":1,"title":"2. Resolver SUCCESS — the package disappears","path":"2. Resolver SUCCESS — the package disappears","text":"**Backdrop:** `Kakashi Origin Backdrop/sakura_tree_night.png`"},{"level":2,"title":"Narration","path":"2. Resolver SUCCESS — the package disappears > Narration","text":"ANBU Marked Target reaches for the package.\n\nKakashi reaches it first.\n\nNot with force.\n\nWith timing.\n\nTwo fingers catch the edge.\n\nA turn of the wrist.\n\nThe package leaves one shinobi before the other ever receives it.\n\nKakashi is already moving when ANBU Marked Target's hand closes on empty cloth.\n\nPackage Smuggler looks at him.\n\nThen at the hand that should be holding something."},{"level":2,"title":"Dialogue","path":"2. Resolver SUCCESS — the package disappears > Dialogue","text":"**PACKAGE SMUGGLER:**  \n“Where is it?”"},{"level":2,"title":"Narration","path":"2. Resolver SUCCESS — the package disappears > Narration","text":"ANBU Marked Target looks down.\n\nOnce.\n\nThat is all Kakashi sees.\n\nHe is already gone.\n\nOver the wall.\n\nAcross the next roof.\n\nInto a part of Konoha where neither man knows which shadow belongs to him.\n\nBy the time they understand that the exchange failed, the package is secured against Kakashi's side.\n\nHe does not look back."},{"level":2,"title":"Objective switch","path":"2. Resolver SUCCESS — the package disappears > Objective switch","text":"Remove:\n\n**Stop the package from falling into the wrong hands.**\n\nSet:\n\n**Return to ANBU.**"},{"level":2,"title":"System / Resolver","path":"2. Resolver SUCCESS — the package disappears > System / Resolver","text":"Commit:\n\n- package custody -> Kakashi;\n- intended handoff never completes;\n- AMT and PS do not detect Kakashi before withdrawal completes;\n- Masked Interceptor does not appear;\n- no PL Battle;\n- no Pakkun;\n- no participant custody;\n- Kakashi learns no hidden downstream package truth by succeeding.\n\n---"},{"level":1,"title":"3. Pickpocket-success ANBU return","path":"3. Pickpocket-success ANBU return","text":"**Backdrop:** `Kakashi Origin Backdrop/rooftop_night.png`"},{"level":2,"title":"Narration","path":"3. Pickpocket-success ANBU return > Narration","text":"The ANBU operative is where Kakashi left him.\n\nKakashi puts the package into his hand.\n\nThe operative looks at it.\n\nThen at Kakashi."},{"level":2,"title":"Dialogue","path":"3. Pickpocket-success ANBU return > Dialogue","text":"**ANBU OPERATIVE:**  \n“They never made the handoff.”\n\n**KAKASHI:**  \n“No.”\n\n**ANBU OPERATIVE:**  \n“They saw you?”\n\n**KAKASHI:**  \n“Not before I was gone.”"},{"level":2,"title":"Narration","path":"3. Pickpocket-success ANBU return > Narration","text":"The operative checks the package seal.\n\nStill intact."},{"level":2,"title":"Dialogue","path":"3. Pickpocket-success ANBU return > Dialogue","text":"**ANBU OPERATIVE:**  \n“How close?”"},{"level":2,"title":"Narration","path":"3. Pickpocket-success ANBU return > Narration","text":"Kakashi considers the question."},{"level":2,"title":"Dialogue","path":"3. Pickpocket-success ANBU return > Dialogue","text":"**KAKASHI:**  \n“Close enough that he noticed something was missing.”\n\n**ANBU OPERATIVE:**  \n“After you left.”\n\n**KAKASHI:**  \n“Yes.”"},{"level":2,"title":"Narration","path":"3. Pickpocket-success ANBU return > Narration","text":"For once, the report is short because the night stayed simple.\n\nNo fight.\n\nNo pursuit.\n\nNo prisoner.\n\nNo body.\n\nJust the objective.\n\nRecovered before anyone else properly understood that Kakashi had entered the exchange at all."},{"level":2,"title":"Dialogue","path":"3. Pickpocket-success ANBU return > Dialogue","text":"**ANBU OPERATIVE:**  \n“Clean.”"},{"level":2,"title":"Narration","path":"3. Pickpocket-success ANBU return > Narration","text":"Kakashi looks at the package."},{"level":2,"title":"Dialogue","path":"3. Pickpocket-success ANBU return > Dialogue","text":"**KAKASHI:**  \n“Clean enough.”"},{"level":2,"title":"System / Resolver","path":"3. Pickpocket-success ANBU return > System / Resolver","text":"- package transfers to ANBU;\n- no MI/PS/AMT later-state invention;\n- no hidden evaluation truth exposed to Kakashi;\n- remove **Return to ANBU.**;\n- transition into the existing private Minato evaluation / Chronicle Receipt / reward closure using stealth-success facts.\n\n---"},{"level":1,"title":"4. Resolver FAILURE — caught in the exchange","path":"4. Resolver FAILURE — caught in the exchange","text":"**Backdrop:** `Kakashi Origin Backdrop/sakura_tree_night.png`"},{"level":2,"title":"Narration","path":"4. Resolver FAILURE — caught in the exchange > Narration","text":"Kakashi gets a hand on the package.\n\nANBU Marked Target gets a hand on Kakashi.\n\nNot enough to hold him.\n\nEnough to ruin the theft.\n\nPackage Smuggler moves immediately."},{"level":2,"title":"Dialogue","path":"4. Resolver FAILURE — caught in the exchange > Dialogue","text":"**PACKAGE SMUGGLER:**  \n“Thought we had company.”"},{"level":2,"title":"Narration","path":"4. Resolver FAILURE — caught in the exchange > Narration","text":"The package stays with ANBU Marked Target.\n\nKakashi breaks contact and lands in the open.\n\nThe quiet exchange is over.\n\nThen the darkness beside the street moves.\n\nA masked figure cuts into the scene at speed.\n\nPackage Smuggler reacts to her.\n\nANBU Marked Target reacts to Kakashi.\n\nFor one moment, everybody is looking at somebody different.\n\nThen Masked Interceptor sees Kakashi too.\n\nWhatever her original line was, there is no clean route through the exchange anymore."},{"level":2,"title":"Dialogue","path":"4. Resolver FAILURE — caught in the exchange > Dialogue","text":"**MASKED INTERCEPTOR:**  \n“You picked a crowded night.”\n\n**KAKASHI:**  \n“I noticed.”\n\n**PACKAGE SMUGGLER:**  \n“Can we all agree he started it?”\n\n**ANBU MARKED TARGET:**  \n“No.”"},{"level":2,"title":"Narration","path":"4. Resolver FAILURE — caught in the exchange > Narration","text":"Kakashi's eye moves across all three.\n\nHe wanted the package without a fight.\n\nHe has managed to get everybody instead.\n\n---"},{"level":1,"title":"5. Failed-Pickpocket PL Battle","path":"5. Failed-Pickpocket PL Battle","text":"**Backdrop:** `Kakashi Origin Backdrop/fight_at_sakura_tree.png`\n\n**Kakashi Hatake**  \n**VS**  \n**ANBU Marked Target + Package Smuggler + Masked Interceptor**\n\nBattle config:\n\n`academy_kakashi_origin_battle_amt_ps_mi_3v1`\n\nThis is the intentionally exceptional hard route.\n\n- Pakkun does not appear;\n- Masked Interceptor's presence is specific to this failed-Pickpocket chronology;\n- package remains with the factual holder at Battle entry, normally AMT;\n- Battle victory alone does not kill/capture anyone;\n- Battle defeat does not itself rewrite package custody beyond the committed result.\n\n---"},{"level":1,"title":"6. Kakashi loses the 3-v-1","path":"6. Kakashi loses the 3-v-1","text":"**Backdrop:** `Kakashi Origin Backdrop/fight_at_sakura_tree.png`"},{"level":2,"title":"Narration","path":"6. Kakashi loses the 3-v-1 > Narration","text":"Three opponents are too much.\n\nNot because Kakashi stops thinking.\n\nBecause every answer creates another problem before he can finish the first one.\n\nThe opening finally comes from ANBU Marked Target.\n\nKakashi goes down.\n\nThe package never reaches him.\n\nPackage Smuggler is the first to move away.\n\nANBU Marked Target follows with the package still secured.\n\nMasked Interceptor stays for half a breath longer.\n\nHer eyes settle on Kakashi."},{"level":2,"title":"Dialogue","path":"6. Kakashi loses the 3-v-1 > Dialogue","text":"**MASKED INTERCEPTOR:**  \n“You nearly made that much more interesting.”"},{"level":2,"title":"Narration","path":"6. Kakashi loses the 3-v-1 > Narration","text":"Then she is gone too.\n\nKakashi lies still until following them would be pursuit by guesswork.\n\nThree people entered the fight.\n\nThree people leave it.\n\nThe package leaves with them."},{"level":2,"title":"Objective switch","path":"6. Kakashi loses the 3-v-1 > Objective switch","text":"Set:\n\n**Return to ANBU.**"},{"level":2,"title":"System / Resolver","path":"6. Kakashi loses the 3-v-1 > System / Resolver","text":"Commit:\n\n- Kakashi loses the 3-v-1;\n- Kakashi secures no participant custody;\n- package remains with / returns to opposition according to the committed factual result, normally AMT on this chronology;\n- AMT escapes;\n- PS escapes;\n- MI escapes from Kakashi's immediate reach;\n- no Pakkun;\n- all three remain material encountered participants for factual report;\n- no hidden-operation truth revealed.\n\nProceed to factual ANBU report / existing terminal evaluation.\n\n---"},{"level":1,"title":"7. Kakashi wins the 3-v-1","path":"7. Kakashi wins the 3-v-1","text":"**Backdrop:** `Kakashi Origin Backdrop/fight_at_sakura_tree.png`"},{"level":2,"title":"Narration","path":"7. Kakashi wins the 3-v-1 > Narration","text":"The last opponent hits the ground.\n\nFor the first time since Kakashi entered the exchange, nobody else is moving.\n\nThree defeated shinobi.\n\nOne package.\n\nKakashi goes to the objective first.\n\nANBU Marked Target is no longer in a position to keep it from him.\n\nKakashi takes the package, checks the seal and secures it against himself.\n\nThen he looks back at the three people on the ground.\n\nWinning the fight solved the package problem.\n\nIt did not decide what happens to them."},{"level":2,"title":"System / Resolver","path":"7. Kakashi wins the 3-v-1 > System / Resolver","text":"Commit independently:\n\n- AMT Battle-defeated;\n- PS Battle-defeated;\n- MI Battle-defeated;\n- package custody -> Kakashi;\n- no participant death from Battle victory;\n- no participant institutional custody from Battle victory;\n- no Pakkun."},{"level":2,"title":"Choices","path":"7. Kakashi wins the 3-v-1 > Choices","text":"Present exactly:\n\n1. **TAKE THEM TO THE UCHIHA POLICE FORCE**\n2. **TAKE THEM TO THE ANBU**\n3. **KILL THEM**\n4. **TAKE THE PACKAGE AND LET THEM GO**\n\nNo per-target sequential disposition menu appears on this exceptional 3-v-1 victory route.\n\n---"},{"level":2,"title":"Narration","path":"8. TAKE THEM TO THE UCHIHA POLICE FORCE > Narration","text":"Kakashi looks over all three.\n\nNobody is getting another fight.\n\nHe draws out the ninja wire.\n\nPackage Smuggler watches him."},{"level":2,"title":"Dialogue","path":"8. TAKE THEM TO THE UCHIHA POLICE FORCE > Dialogue","text":"**PACKAGE SMUGGLER:**  \n“All three of us?”\n\n**KAKASHI:**  \n“Yes.”\n\n**PACKAGE SMUGGLER:**  \n“Efficient.”\n\n**MASKED INTERCEPTOR:**  \n“Be quiet.”"},{"level":2,"title":"Narration","path":"8. TAKE THEM TO THE UCHIHA POLICE FORCE > Narration","text":"Kakashi restrains them one by one.\n\nANBU Marked Target first.\n\nPackage Smuggler next.\n\nMasked Interceptor last.\n\nThree separate restraints.\n\nOne decision.\n\nThe recovered package remains secured against Kakashi."},{"level":2,"title":"Dialogue","path":"8. TAKE THEM TO THE UCHIHA POLICE FORCE > Dialogue","text":"**ANBU MARKED TARGET:**  \n“ANBU?”\n\n**KAKASHI:**  \n“Police.”"},{"level":2,"title":"Narration","path":"8. TAKE THEM TO THE UCHIHA POLICE FORCE > Narration","text":"That gets a reaction.\n\nPackage Smuggler looks from Kakashi to the other two."},{"level":2,"title":"Dialogue","path":"8. TAKE THEM TO THE UCHIHA POLICE FORCE > Dialogue","text":"**PACKAGE SMUGGLER:**  \n“I think I preferred ANBU.”\n\n**MASKED INTERCEPTOR:**  \n“You don't know enough to have a preference.”\n\n**PACKAGE SMUGGLER:**  \n“I know there will be paperwork.”"},{"level":2,"title":"Transition","path":"8. TAKE THEM TO THE UCHIHA POLICE FORCE > Transition","text":"**BLACK WIPE**"},{"level":3,"title":"Uchiha Police Force handoff","path":"8. TAKE THEM TO THE UCHIHA POLICE FORCE > Transition > Uchiha Police Force handoff","text":"**Backdrop:** `Kakashi Origin Backdrop/uchiha_police_exterior_night.png`\n\nThe Police entrance is still lit.\n\nTwo officers come forward.\n\nThen slow when they see Kakashi bringing three restrained shinobi with him.\n\nOne officer raises a hand.\n\n**UCHIHA POLICE OFFICER:**  \n“Stop there.”\n\nKakashi does.\n\nThe officer's eyes move across all three prisoners.\n\nThen to the package secured against Kakashi.\n\n**UCHIHA POLICE OFFICER:**  \n“Start from the beginning.”\n\nKakashi gives him exactly what he observed.\n\nThe original tail.\n\nThe attempted theft.\n\nThe failed stealth approach.\n\nThe fight.\n\nThe recovered package.\n\nHe does not invent affiliations.\n\nHe does not explain hidden motives he does not know.\n\nWhen he finishes, the officer looks across the three restrained shinobi again.\n\n**UCHIHA POLICE OFFICER:**  \n“You fought all three?”\n\n**KAKASHI:**  \n“Yes.”\n\nPackage Smuggler exhales.\n\n**PACKAGE SMUGGLER:**  \n“It sounds worse when he says it that simply.”\n\nThe second officer steps toward the first restraint.\n\n**UCHIHA POLICE OFFICER:**  \n“We'll take them.”\n\nKakashi transfers each captive separately.\n\nANBU Marked Target.\n\nPackage Smuggler.\n\nMasked Interceptor.\n\nOnly after each officer has secure control does Kakashi release his own restraint line."},{"level":2,"title":"System / Resolver","path":"8. TAKE THEM TO THE UCHIHA POLICE FORCE > System / Resolver","text":"Commit separately:\n\n- AMT -> Uchiha Police institutional custody;\n- PS -> Uchiha Police institutional custody;\n- MI -> Uchiha Police institutional custody;\n- package remains with Kakashi for ANBU return;\n- no ANBU custody inferred.\n\nSet objective:\n\n**Return to ANBU.**\n\n---"},{"level":2,"title":"Narration","path":"9. TAKE THEM TO THE ANBU > Narration","text":"Kakashi looks at the three defeated shinobi.\n\nThen reaches for the ninja wire.\n\nPackage Smuggler notices."},{"level":2,"title":"Dialogue","path":"9. TAKE THEM TO THE ANBU > Dialogue","text":"**PACKAGE SMUGGLER:**  \n“I was hoping that wasn't for us.”\n\n**KAKASHI:**  \n“It is.”"},{"level":2,"title":"Narration","path":"9. TAKE THEM TO THE ANBU > Narration","text":"Kakashi secures them individually.\n\nANBU Marked Target.\n\nPackage Smuggler.\n\nMasked Interceptor.\n\nThe package stays against Kakashi's side.\n\nMasked Interceptor tests the restraint once.\n\nStops."},{"level":2,"title":"Dialogue","path":"9. TAKE THEM TO THE ANBU > Dialogue","text":"**MASKED INTERCEPTOR:**  \n“You won the difficult part.”\n\n**KAKASHI:**  \n“I noticed.”\n\n**PACKAGE SMUGGLER:**  \n“He does that.”"},{"level":2,"title":"Narration","path":"9. TAKE THEM TO THE ANBU > Narration","text":"Kakashi looks at him."},{"level":2,"title":"Dialogue","path":"9. TAKE THEM TO THE ANBU > Dialogue","text":"**PACKAGE SMUGGLER:**  \n“Notices things.”\n\n**ANBU MARKED TARGET:**  \n“Keep talking.”\n\n**PACKAGE SMUGGLER:**  \n“I was planning to.”"},{"level":2,"title":"Transition","path":"9. TAKE THEM TO THE ANBU > Transition","text":"**BLACK WIPE**"},{"level":3,"title":"ANBU rooftop handoff","path":"9. TAKE THEM TO THE ANBU > Transition > ANBU rooftop handoff","text":"**Backdrop:** `Kakashi Origin Backdrop/rooftop_night.png`\n\nThe ANBU operative turns as Kakashi arrives.\n\nHis attention goes first to the package.\n\nThen to the three restrained shinobi.\n\nThe pause is longer than usual."},{"level":2,"title":"Dialogue","path":"9. TAKE THEM TO THE ANBU > Dialogue","text":"**ANBU OPERATIVE:**  \n“Report.”"},{"level":2,"title":"Narration","path":"9. TAKE THEM TO THE ANBU > Narration","text":"Kakashi hands over the package first."},{"level":2,"title":"Dialogue","path":"9. TAKE THEM TO THE ANBU > Dialogue","text":"**KAKASHI:**  \n“I tried to take it before the handoff.”\n\n**ANBU OPERATIVE:**  \n“And?”"},{"level":2,"title":"Narration","path":"9. TAKE THEM TO THE ANBU > Narration","text":"Kakashi glances toward the three prisoners."},{"level":2,"title":"Dialogue","path":"9. TAKE THEM TO THE ANBU > Dialogue","text":"**KAKASHI:**  \n“They noticed.”\n\nPackage Smuggler looks mildly offended.\n\n**PACKAGE SMUGGLER:**  \n“Eventually.”\n\nThe operative ignores him.\n\nKakashi gives the sequence.\n\nThe attempted theft.\n\nMasked Interceptor's arrival.\n\nThe fight.\n\nThe package recovery.\n\nThe three live captives.\n\nWhen the report is complete, the operative steps forward.\n\n**ANBU OPERATIVE:**  \n“We'll take custody.”\n\nKakashi transfers each captive separately.\n\nAMT.\n\nPS.\n\nMI.\n\nNo group shortcut replaces the three actual custody transfers."},{"level":2,"title":"System / Resolver","path":"9. TAKE THEM TO THE ANBU > System / Resolver","text":"Commit separately:\n\n- AMT -> ANBU institutional custody;\n- PS -> ANBU institutional custody;\n- MI -> ANBU institutional custody;\n- package -> ANBU custody;\n- no Police custody.\n\n---"},{"level":2,"title":"Narration","path":"10. KILL THEM > Narration","text":"Kakashi looks across the three defeated shinobi.\n\nThe package is secure.\n\nThe fight is over.\n\nWhat happens next is not.\n\nHe makes the decision once.\n\nIt applies to all three.\n\nThe end is controlled.\n\nFast.\n\nWithout spectacle.\n\nWhen it is finished, none of the three are moving.\n\nKakashi stands alone with the recovered package.\n\nFor several seconds, the Sakura tree is the only thing in the street still moving.\n\nWind through the branches.\n\nNothing else."},{"level":2,"title":"System / Resolver","path":"10. KILL THEM > System / Resolver","text":"Commit three distinct deterministic Story deaths:\n\n- AMT -> dead;\n- PS -> dead;\n- MI -> dead.\n\nEach death preserves:\n\n- exact target identity;\n- player-selected lethal provenance;\n- shared 3-v-1 post-Battle group-decision occurrence;\n- package custody remains with Kakashi.\n\nThis is **three confirmed kills**, not one aggregate death flag.\n\nNo Pakkun.\n\nSet objective:\n\n**Return to ANBU.**"},{"level":3,"title":"ANBU report projection","path":"10. KILL THEM > System / Resolver > ANBU report projection","text":"Kakashi reports all three deaths directly.\n\nDo not soften **KILL THEM** into Battle casualties.\n\nDo not describe the result as three Battle wins.\n\nThe operative receives:\n\n- failed Pickpocket;\n- 3-v-1 Battle;\n- package recovered;\n- AMT killed by Kakashi after Battle;\n- PS killed by Kakashi after Battle;\n- MI killed by Kakashi after Battle.\n\nPrivate Minato evaluation / Chronicle Receipt must consume the exact three-kill lethal history.\n\n---"},{"level":2,"title":"Narration","path":"11. TAKE THE PACKAGE AND LET THEM GO > Narration","text":"Kakashi looks at the recovered package.\n\nThen at the three defeated shinobi.\n\nHe already has what ANBU sent him for.\n\nHe does not reach for the wire.\n\nPackage Smuggler notices first."},{"level":2,"title":"Dialogue","path":"11. TAKE THE PACKAGE AND LET THEM GO > Dialogue","text":"**PACKAGE SMUGGLER:**  \n“That's it?”\n\n**KAKASHI:**  \n“I have the package.”\n\n**PACKAGE SMUGGLER:**  \n“And us?”"},{"level":2,"title":"Narration","path":"11. TAKE THE PACKAGE AND LET THEM GO > Narration","text":"Kakashi looks at him."},{"level":2,"title":"Dialogue","path":"11. TAKE THE PACKAGE AND LET THEM GO > Dialogue","text":"**KAKASHI:**  \n“You're free to leave.”"},{"level":2,"title":"Narration","path":"11. TAKE THE PACKAGE AND LET THEM GO > Narration","text":"ANBU Marked Target studies him.\n\nMasked Interceptor does not move immediately."},{"level":2,"title":"Dialogue","path":"11. TAKE THE PACKAGE AND LET THEM GO > Dialogue","text":"**ANBU MARKED TARGET:**  \n“You fought all three of us for the package.”\n\n**KAKASHI:**  \n“Yes.”\n\n**ANBU MARKED TARGET:**  \n“And now you're letting us walk.”\n\n**KAKASHI:**  \n“I didn't say I came for you.”"},{"level":2,"title":"Narration","path":"11. TAKE THE PACKAGE AND LET THEM GO > Narration","text":"Package Smuggler slowly gets to his feet."},{"level":2,"title":"Dialogue","path":"11. TAKE THE PACKAGE AND LET THEM GO > Dialogue","text":"**PACKAGE SMUGGLER:**  \n“I've had worse negotiations.”\n\n**MASKED INTERCEPTOR:**  \n“This wasn't a negotiation.”\n\n**PACKAGE SMUGGLER:**  \n“That's why I said worse.”"},{"level":2,"title":"Narration","path":"11. TAKE THE PACKAGE AND LET THEM GO > Narration","text":"Kakashi does not stop them.\n\nOne by one, they leave the street.\n\nThe package remains with him."},{"level":2,"title":"System / Resolver","path":"11. TAKE THE PACKAGE AND LET THEM GO > System / Resolver","text":"Commit separately:\n\n- AMT alive / released;\n- PS alive / released;\n- MI alive / released;\n- no participant custody;\n- package remains with Kakashi;\n- no passive pursuit is reopened merely because Kakashi released them;\n- no hidden lethal/custody action occurs afterward.\n\nSet objective:\n\n**Return to ANBU.**"},{"level":3,"title":"ANBU report projection","path":"11. TAKE THE PACKAGE AND LET THEM GO > System / Resolver > ANBU report projection","text":"Kakashi reports:\n\n- failed Pickpocket;\n- 3-v-1 Battle victory;\n- package recovered;\n- all three opponents released alive by deliberate choice.\n\nDo not project release as escape.\n\nDo not project zero custody as failure to control them.\n\nThis was a player-selected release.\n\n---"},{"level":1,"title":"12. Terminal continuation","path":"12. Terminal continuation","text":"For all four 3-v-1 victory dispositions:\n\n- preserve package recovery;\n- preserve the exact group disposition;\n- preserve each participant's individual final state;\n- consume existing private Minato evaluation / Chronicle Receipt architecture;\n- do not reveal hidden-operation truth to Kakashi;\n- no Pakkun involvement exists on this route."},{"level":1,"title":"Final lock","path":"Final lock","text":"> **SLIP IN FOR THE PACKAGE success is a clean stealth win with no Battle and no Masked Interceptor appearance.**\n\n> **Failure produces the exact Kakashi vs AMT + Package Smuggler + Masked Interceptor 3-v-1 Battle.**\n\n> **3-v-1 defeat is closed.**\n\n> **3-v-1 victory presents exactly: TAKE THEM TO THE UCHIHA POLICE FORCE / TAKE THEM TO THE ANBU / KILL THEM / TAKE THE PACKAGE AND LET THEM GO.**"}]},"observeSecure":{"source":"Documentation/Story/Academy_Kakashi_Observe_Secure_Package_Verbatim_Scene_Family_2026-09-19.md","sections":[{"level":1,"title":"Academy Kakashi Origin — WATCH THE EXCHANGE -> SECURE THE PACKAGE — Verbatim Scene Family","path":"Academy Kakashi Origin — WATCH THE EXCHANGE -> SECURE THE PACKAGE — Verbatim Scene Family","text":"**Date:** 2026-09-19  \n**Owner:** Writing / Story — Konoha under Stephen delegated-authoring authority  \n**Status:** **LOCKED VERBATIM — DELEGATED CLEAN CONTINUATION / IMPLEMENTATION READY**  \n**Branch:** `SCENE_03A / CHOICE_01 / BRANCH_B`  \n**Player-facing entry choice:** **SECURE THE PACKAGE**  \n**Primary priority:** **FINISH SHINOBI CHRONICLES ALPHA**"},{"level":2,"title":"Consumed authority","path":"Academy Kakashi Origin — WATCH THE EXCHANGE -> SECURE THE PACKAGE — Verbatim Scene Family > Consumed authority","text":"This scene family consumes:\n\n- `Academy_Kakashi_Origin_Scene_03A_Watch_The_Exchange_Verbatim_Lock_2026-09-17.md`;\n- `Academy_Kakashi_Observe_Secure_Package_Branch_Authority_2026-09-14.md`;\n- `Academy_Kakashi_Existing_Material_Player_Facing_Retrofit_and_Remaining_Branch_Inventory_2026-09-14.md`;\n- `Academy_Kakashi_Decision_Continuation_Matrix_and_Pickpocket_Route_Lock_2026-09-15.md`;\n- `Academy_Kakashi_Final_Structured_Autonomy_Anchor_Reconciliation_2026-09-15.md`;\n- current global post-Battle disposition simplification;\n- current Pakkun continuity / no-name-leak authority;\n- current character personality / voice profiles;\n- current exact Kakashi backdrop inventory.\n\nLive runtime confirms the exact Battle configuration exists:\n\n`academy_kakashi_origin_battle_ps_mi_2v1`\n\nThe older Combat deployment document's seven-config list is stale on that point; live source is authoritative.\n\n---"},{"level":1,"title":"1. SECURE THE PACKAGE","path":"1. SECURE THE PACKAGE","text":"**Backdrop:** `Kakashi Origin Backdrop/sakura_tree_night.png`\n\n**Objective:** **Retrieve the package.**"},{"level":2,"title":"Narration","path":"1. SECURE THE PACKAGE > Narration","text":"Kakashi moves before Package Smuggler can turn the exchange into distance.\n\nANBU Marked Target is already breaking away.\n\nKakashi lets him.\n\nFor now.\n\nThe package is the part of the mission he can still put his hand on.\n\nHe drops into the street and goes straight for the man carrying it.\n\nPackage Smuggler sees him coming.\n\nSo does Masked Interceptor.\n\nHer line changes immediately.\n\nShe had been closing on Package Smuggler.\n\nNow Kakashi is between her and the same man."},{"level":2,"title":"Dialogue","path":"1. SECURE THE PACKAGE > Dialogue","text":"**MASKED INTERCEPTOR:**  \n“Move.”"},{"level":2,"title":"Narration","path":"1. SECURE THE PACKAGE > Narration","text":"Kakashi does not.\n\nPackage Smuggler shifts the package behind his body."},{"level":2,"title":"Dialogue","path":"1. SECURE THE PACKAGE > Dialogue","text":"**PACKAGE SMUGGLER:**  \n“I was having enough trouble before you joined in.”\n\n**KAKASHI:**  \n“Give me the package.”\n\n**PACKAGE SMUGGLER:**  \n“That's not really the mood here.”"},{"level":2,"title":"Narration","path":"1. SECURE THE PACKAGE > Narration","text":"Masked Interceptor closes from Kakashi's other side.\n\nKakashi's eye moves once between them.\n\nOne wants the man.\n\nOne has the objective.\n\nNeither is moving out of his way."},{"level":2,"title":"Dialogue","path":"1. SECURE THE PACKAGE > Dialogue","text":"**MASKED INTERCEPTOR:**  \n“Last warning.”\n\n**KAKASHI:**  \n“I heard the first one.”"},{"level":2,"title":"Narration","path":"1. SECURE THE PACKAGE > Narration","text":"Package Smuggler takes the opening and reaches for his weapon.\n\nKakashi moves with him.\n\nMasked Interceptor moves too.\n\nThe decision to go for the package has become a fight with both of them.\n\n---"},{"level":1,"title":"2. PL Battle","path":"2. PL Battle","text":"**Kakashi Hatake vs Package Smuggler + Masked Interceptor**\n\nBattle config:\n\n`academy_kakashi_origin_battle_ps_mi_2v1`\n\nSource anchor:\n\n`AK_SA_014`\n\nBattle owns exact action order and factual win/loss return.\n\nBattle victory alone does not create death or participant custody.\n\n---"},{"level":1,"title":"3. Kakashi loses the 2-v-1","path":"3. Kakashi loses the 2-v-1","text":"**Backdrop:** `Kakashi Origin Backdrop/sakura_tree_night.png`"},{"level":2,"title":"Narration","path":"3. Kakashi loses the 2-v-1 > Narration","text":"Kakashi loses the opening.\n\nPackage Smuggler does not waste it.\n\nBy the time Kakashi can properly track the street again, the package is already moving away with him.\n\nANBU Marked Target is long gone.\n\nMasked Interceptor remains.\n\nFor a moment.\n\nShe pulls Kakashi's arms behind him and binds them tight enough that the result of the fight cannot be mistaken.\n\nKakashi tests the restraint once.\n\nNo give.\n\nMasked Interceptor looks toward the route Package Smuggler took."},{"level":2,"title":"Dialogue","path":"3. Kakashi loses the 2-v-1 > Dialogue","text":"**KAKASHI:**  \n“You're still going after him.”\n\n**MASKED INTERCEPTOR:**  \n“That was the idea before you got involved.”"},{"level":2,"title":"Narration","path":"3. Kakashi loses the 2-v-1 > Narration","text":"She leaves him there and disappears after Package Smuggler.\n\nKakashi listens until her steps are gone.\n\nThen starts working on the restraint.\n\nBy the time he gets free, the street is empty.\n\nThe package is gone.\n\nSo are all three people who mattered to the exchange."},{"level":2,"title":"Objective switch","path":"3. Kakashi loses the 2-v-1 > Objective switch","text":"Remove:\n\n**Retrieve the package.**\n\nSet:\n\n**Return to ANBU.**"},{"level":2,"title":"System / Resolver","path":"3. Kakashi loses the 2-v-1 > System / Resolver","text":"Commit only factual known state:\n\n- Kakashi lost the 2-v-1 Battle;\n- ANBU Marked Target escaped;\n- Package Smuggler escaped with the package;\n- Masked Interceptor restrained Kakashi after Battle;\n- MI then left Kakashi's sight in apparent pursuit of Package Smuggler;\n- Kakashi does not know the later PS/MI result;\n- no participant custody for Kakashi;\n- no Pakkun;\n- no hidden-operation Knowledge.\n\nProceed to the Secure-Package factual ANBU report variant **LOSS** in section 8.\n\n---"},{"level":1,"title":"4. Kakashi wins the 2-v-1","path":"4. Kakashi wins the 2-v-1","text":"**Backdrop:** `Kakashi Origin Backdrop/sakura_tree_night.png`"},{"level":2,"title":"Narration","path":"4. Kakashi wins the 2-v-1 > Narration","text":"The fight ends with both immediate opponents down.\n\nKakashi does not celebrate.\n\nHis attention goes to the package first.\n\nPackage Smuggler is still close enough to reach.\n\nThe package is closer.\n\nKakashi takes it from the defeated man's grasp, checks the seal and secures it against his body.\n\nOnly then does he look toward the street ANBU Marked Target used to leave.\n\nMasked Interceptor is still down.\n\nPackage Smuggler is still down.\n\nNeither has become an answer to anything Kakashi does not know.\n\nBut the package is back in his hands.\n\nFor the first time since the exchange, the mission objective is secure."},{"level":2,"title":"Objective change","path":"4. Kakashi wins the 2-v-1 > Objective change","text":"Remove:\n\n**Retrieve the package.**\n\nNo objective is shown while the next decision is active."},{"level":2,"title":"System / Resolver","path":"4. Kakashi wins the 2-v-1 > System / Resolver","text":"Commit the existing `AK_SA_025` factual result:\n\n- PS Battle-defeated;\n- MI Battle-defeated;\n- package custody -> Kakashi;\n- no automatic participant death;\n- no automatic participant custody;\n- due participant autonomy must clear before Kakashi receives the next choice;\n- AMT continuation is determined by its own pursuit resolver.\n\nInternal legacy classification may remain for compatibility but does not gate or rename the player-facing mission choices.\n\n---"},{"level":1,"title":"5. Post-victory decision","path":"5. Post-victory decision","text":"Present exactly:\n\n1. **STAY ON THE FIRST MAN**\n2. **RETURN AND REPORT**"},{"level":3,"title":"`BRANCH_B1` — Stay on the first man","path":"5. Post-victory decision > Branch identity > `BRANCH_B1` — Stay on the first man","text":"Kakashi keeps the recovered package and goes after ANBU Marked Target."},{"level":3,"title":"`BRANCH_B2` — Return and report","path":"5. Post-victory decision > Branch identity > `BRANCH_B2` — Return and report","text":"Kakashi keeps the recovered package and ends his field pursuit.\n\nNo new PS/MI custody fact is invented by either choice.\n\n---"},{"level":2,"title":"Backdrop","path":"6. BRANCH_B1 — STAY ON THE FIRST MAN > Backdrop","text":"Start on:\n\n`Kakashi Origin Backdrop/sakura_tree_night.png`"},{"level":2,"title":"Objective","path":"6. BRANCH_B1 — STAY ON THE FIRST MAN > Objective","text":"**Catch the first man.**"},{"level":2,"title":"Narration","path":"6. BRANCH_B1 — STAY ON THE FIRST MAN > Narration","text":"Kakashi leaves the two defeated shinobi behind.\n\nNot because they no longer matter.\n\nBecause the first man is still moving.\n\nThe package is secure now.\n\nThat changes the calculation.\n\nKakashi can chase without wondering whether every step is taking him farther from the objective.\n\nHe takes the rooftops.\n\nThe trail is thinner than it was before the fight.\n\nStill there.\n\nFor now."},{"level":2,"title":"System / Resolver","path":"6. BRANCH_B1 — STAY ON THE FIRST MAN > System / Resolver","text":"Resolve:\n\n`academy_kakashi.resolver.secure_package_amt_pursuit`\n\nPossible factual outcomes:\n\n- `SECURE_PACKAGE_AMT_PURSUIT_SUCCESS_REACHED`;\n- `SECURE_PACKAGE_AMT_PURSUIT_FAILURE_ESCAPED`.\n\nSelection of **STAY ON THE FIRST MAN** does not guarantee pursuit success.\n\n---"},{"level":2,"title":"Narration","path":"6. BRANCH_B1 — STAY ON THE FIRST MAN > Narration","text":"Kakashi clears another rooftop.\n\nNothing.\n\nHe drops to street level.\n\nChecks the crossing.\n\nThe route has split too many times.\n\nWhatever lead remained after the fight is gone.\n\nHe stops chasing before guesswork becomes a substitute for a trail.\n\nThe package is still secured against him.\n\nThe first man is gone.\n\nThose facts can both be true."},{"level":2,"title":"Objective switch","path":"6. BRANCH_B1 — STAY ON THE FIRST MAN > Objective switch","text":"Remove:\n\n**Catch the first man.**\n\nSet:\n\n**Return to ANBU.**"},{"level":2,"title":"System / Resolver","path":"6. BRANCH_B1 — STAY ON THE FIRST MAN > System / Resolver","text":"- AMT escapes;\n- package remains in Kakashi custody;\n- no Pakkun because Kakashi never legitimately reaches AMT;\n- PS/MI remain only in their last committed factual states.\n\nProceed to ANBU report variant **PACKAGE RECOVERED / AMT PURSUIT FAILED** in section 8.\n\n---"},{"level":2,"title":"6B. Pursuit success — Pakkun intercept","path":"6. BRANCH_B1 — STAY ON THE FIRST MAN > 6B. Pursuit success — Pakkun intercept","text":"**Backdrop:** `Kakashi Origin Backdrop/alleyway_konoha_night.png`"},{"level":2,"title":"Narration","path":"6. BRANCH_B1 — STAY ON THE FIRST MAN > Narration","text":"ANBU Marked Target cuts into the next alley.\n\nThen stops.\n\nA small ninken is sitting in the route ahead of him.\n\nThe man looks at it.\n\nThe ninken looks past him.\n\nKakashi lands behind.\n\nPakkun's ears lift."},{"level":2,"title":"Dialogue","path":"6. BRANCH_B1 — STAY ON THE FIRST MAN > Dialogue","text":"**PAKKUN:**  \n“This yours?”"},{"level":2,"title":"Narration","path":"6. BRANCH_B1 — STAY ON THE FIRST MAN > Narration","text":"Kakashi keeps his eye on the man between them."},{"level":2,"title":"Dialogue","path":"6. BRANCH_B1 — STAY ON THE FIRST MAN > Dialogue","text":"**KAKASHI:**  \n“Apparently.”"},{"level":2,"title":"Narration","path":"6. BRANCH_B1 — STAY ON THE FIRST MAN > Narration","text":"ANBU Marked Target notices the package secured against Kakashi."},{"level":2,"title":"Dialogue","path":"6. BRANCH_B1 — STAY ON THE FIRST MAN > Dialogue","text":"**ANBU MARKED TARGET:**  \n“You got it back.”\n\n**KAKASHI:**  \n“I did.”\n\n**ANBU MARKED TARGET:**  \n“Then why are you still following me?”"},{"level":2,"title":"Narration","path":"6. BRANCH_B1 — STAY ON THE FIRST MAN > Narration","text":"Kakashi shifts his stance."},{"level":2,"title":"Dialogue","path":"6. BRANCH_B1 — STAY ON THE FIRST MAN > Dialogue","text":"**KAKASHI:**  \n“You were the first man in the exchange.”\n\n**ANBU MARKED TARGET:**  \n“And that matters more than finishing the assignment?”\n\n**KAKASHI:**  \n“The assignment is here.”"},{"level":2,"title":"Narration","path":"6. BRANCH_B1 — STAY ON THE FIRST MAN > Narration","text":"Kakashi touches the package once.\n\nThen looks back at him."},{"level":2,"title":"Dialogue","path":"6. BRANCH_B1 — STAY ON THE FIRST MAN > Dialogue","text":"**KAKASHI:**  \n“You're the part I haven't finished.”"},{"level":2,"title":"Narration","path":"6. BRANCH_B1 — STAY ON THE FIRST MAN > Narration","text":"Pakkun rises.\n\nANBU Marked Target glances toward the alley mouth.\n\nPakkun notices."},{"level":2,"title":"Dialogue","path":"6. BRANCH_B1 — STAY ON THE FIRST MAN > Dialogue","text":"**PAKKUN:**  \n“He's thinking about running.”\n\n**KAKASHI:**  \n“I know.”\n\n**ANBU MARKED TARGET:**  \n“You two always this irritating?”"},{"level":2,"title":"Narration","path":"6. BRANCH_B1 — STAY ON THE FIRST MAN > Narration","text":"Pakkun gives him a flat look."},{"level":2,"title":"Dialogue","path":"6. BRANCH_B1 — STAY ON THE FIRST MAN > Dialogue","text":"**PAKKUN:**  \n“We just met.”\n\n---"},{"level":1,"title":"7. AMT PL Battle","path":"7. AMT PL Battle","text":"**Kakashi Hatake with temporary Story-authorised Pakkun vs ANBU Marked Target**\n\nBattle config:\n\n`academy_kakashi_origin_battle_kakashi_pakkun_vs_amt`\n\nPakkun is present because Kakashi legitimately reached AMT.\n\nPakkun has no independent normal Battle turn and no Summon ownership is granted.\n\nPackage remains separately secured to Kakashi unless another exact factual resolver changes it.\n\n---"},{"level":2,"title":"7A. Kakashi/Pakkun defeat AMT","path":"7. AMT PL Battle > 7A. Kakashi/Pakkun defeat AMT","text":"**Backdrop:** `Kakashi Origin Backdrop/alleyway_konoha_night.png`"},{"level":2,"title":"Narration","path":"7. AMT PL Battle > Narration","text":"ANBU Marked Target goes down.\n\nKakashi stays on him until the fight is unquestionably over.\n\nPakkun stays where he can see both of them.\n\nThe package remains secure.\n\nThe man does not.\n\nNot yet."},{"level":2,"title":"System / Resolver","path":"7. AMT PL Battle > System / Resolver","text":"Commit AMT Battle victory separately from package and participant disposition.\n\nBecause the package is already secured and AMT is factually available, consume the existing approved AMT disposition family rather than inventing a new one.\n\nPresent in the established order and current exact wording:\n\n1. **BRING HIM TO THE UCHIHA POLICE FORCE**\n2. **LET HIM GO**\n3. **KILL HIM**\n4. **TAKE HIM BACK TO THE ANBU**\n\nConsume the already-approved exact disposition scenes / continuations for the selected action.\n\nPakkun remains present until an explicit departure.\n\nDo not reopen PS/MI as active choices merely because they were defeated earlier.\n\n---"},{"level":2,"title":"7B. AMT defeats Kakashi/Pakkun","path":"7. AMT PL Battle > 7B. AMT defeats Kakashi/Pakkun","text":"**Backdrop:** `Kakashi Origin Backdrop/alleyway_konoha_night.png`"},{"level":2,"title":"Narration","path":"7. AMT PL Battle > Narration","text":"ANBU Marked Target finds the opening first.\n\nKakashi loses the fight.\n\nHe does not lose the package with it.\n\nThe recovered objective was secured before this confrontation began.\n\nANBU Marked Target looks once toward it.\n\nThen toward the route out.\n\nHe chooses distance.\n\nBy the time Kakashi can force himself back into the pursuit, the man is gone.\n\nPakkun remains nearby.\n\nQuiet for once."},{"level":2,"title":"Dialogue","path":"7. AMT PL Battle > Dialogue","text":"**PAKKUN:**  \n“You kept the important part.”"},{"level":2,"title":"Narration","path":"7. AMT PL Battle > Narration","text":"Kakashi looks down at the package."},{"level":2,"title":"Dialogue","path":"7. AMT PL Battle > Dialogue","text":"**KAKASHI:**  \n“I lost him.”\n\n**PAKKUN:**  \n“I noticed.”"},{"level":2,"title":"Narration","path":"7. AMT PL Battle > Narration","text":"A beat.\n\nPakkun's voice is drier when he continues."},{"level":2,"title":"Dialogue","path":"7. AMT PL Battle > Dialogue","text":"**PAKKUN:**  \n“Both things can be true.”"},{"level":2,"title":"Objective switch","path":"7. AMT PL Battle > Objective switch","text":"Set:\n\n**Return to ANBU.**"},{"level":2,"title":"System / Resolver","path":"7. AMT PL Battle > System / Resolver","text":"- AMT escapes;\n- package remains in Kakashi custody;\n- no target custody;\n- Pakkun remains present through the connected report unless an earlier exact departure commits;\n- PS/MI remain in their last committed states;\n- no injury fact is inferred from Battle defeat.\n\nProceed to ANBU report variant **PACKAGE RECOVERED / AMT BATTLE LOST / PAKKUN PRESENT** in section 8.\n\n---"},{"level":1,"title":"8. Secure-Package ANBU report projections","path":"8. Secure-Package ANBU report projections","text":"These reports use exact committed state and do not invent later PS/MI facts.\n\n**Backdrop:** `Kakashi Origin Backdrop/rooftop_night.png`\n\n---"},{"level":2,"title":"8A. LOSS — package lost","path":"8. Secure-Package ANBU report projections > 8A. LOSS — package lost","text":"**Objective:** **Return to ANBU.**"},{"level":2,"title":"Narration","path":"8. Secure-Package ANBU report projections > Narration","text":"Kakashi returns to the rooftop.\n\nThe ANBU operative is waiting.\n\nHis attention settles on Kakashi's empty hands before it reaches his face."},{"level":2,"title":"Dialogue","path":"8. Secure-Package ANBU report projections > Dialogue","text":"**ANBU OPERATIVE:**  \n“Report.”\n\n**KAKASHI:**  \n“The handoff completed.”\n\n**ANBU OPERATIVE:**  \n“And the package?”\n\n**KAKASHI:**  \n“I went for it.”"},{"level":2,"title":"Narration","path":"8. Secure-Package ANBU report projections > Narration","text":"Kakashi does not soften the next part."},{"level":2,"title":"Dialogue","path":"8. Secure-Package ANBU report projections > Dialogue","text":"**KAKASHI:**  \n“I lost the fight.”\n\n**ANBU OPERATIVE:**  \n“Against the receiver?”\n\n**KAKASHI:**  \n“Him and the masked shinobi.”"},{"level":2,"title":"Narration","path":"8. Secure-Package ANBU report projections > Narration","text":"The operative's attention sharpens."},{"level":2,"title":"Dialogue","path":"8. Secure-Package ANBU report projections > Dialogue","text":"**ANBU OPERATIVE:**  \n“She joined him.”\n\n**KAKASHI:**  \n“She joined the fight.”"},{"level":2,"title":"Narration","path":"8. Secure-Package ANBU report projections > Narration","text":"A small distinction.\n\nDeliberate."},{"level":2,"title":"Dialogue","path":"8. Secure-Package ANBU report projections > Dialogue","text":"**ANBU OPERATIVE:**  \n“What happened after?”\n\n**KAKASHI:**  \n“The receiver escaped with the package.”\n\n**ANBU OPERATIVE:**  \n“The masked shinobi?”\n\n**KAKASHI:**  \n“Tied me up and went after him.”\n\n**ANBU OPERATIVE:**  \n“You saw where they went?”\n\n**KAKASHI:**  \n“No.”"},{"level":2,"title":"Narration","path":"8. Secure-Package ANBU report projections > Narration","text":"The operative accepts the limit instead of asking Kakashi to guess."},{"level":2,"title":"Dialogue","path":"8. Secure-Package ANBU report projections > Dialogue","text":"**ANBU OPERATIVE:**  \n“And the first man?”\n\n**KAKASHI:**  \n“Gone before the fight ended.”"},{"level":2,"title":"Narration","path":"8. Secure-Package ANBU report projections > Narration","text":"The operative gives one measured nod."},{"level":2,"title":"Dialogue","path":"8. Secure-Package ANBU report projections > Dialogue","text":"**ANBU OPERATIVE:**  \n“Understood.”\n\n---"},{"level":2,"title":"Narration","path":"8. Secure-Package ANBU report projections > Narration","text":"Kakashi returns to the rooftop with the package secured against him.\n\nThe ANBU operative notices it immediately."},{"level":2,"title":"Dialogue","path":"8. Secure-Package ANBU report projections > Dialogue","text":"**ANBU OPERATIVE:**  \n“You recovered it.”\n\n**KAKASHI:**  \n“Yes.”"},{"level":2,"title":"Narration","path":"8. Secure-Package ANBU report projections > Narration","text":"Kakashi hands it over.\n\nThe operative accepts it before asking the next question."},{"level":2,"title":"Dialogue","path":"8. Secure-Package ANBU report projections > Dialogue","text":"**ANBU OPERATIVE:**  \n“The first man?”\n\n**KAKASHI:**  \n“I didn't follow him.”\n\n**ANBU OPERATIVE:**  \n“Why?”"},{"level":2,"title":"Narration","path":"8. Secure-Package ANBU report projections > Narration","text":"Kakashi glances once at the package now in the operative's hand."},{"level":2,"title":"Dialogue","path":"8. Secure-Package ANBU report projections > Dialogue","text":"**KAKASHI:**  \n“I had what you sent me for.”\n\n**ANBU OPERATIVE:**  \n“And the other two?”\n\n**KAKASHI:**  \n“Both down when I left.”\n\n**ANBU OPERATIVE:**  \n“Dead?”\n\n**KAKASHI:**  \n“No.”\n\n**ANBU OPERATIVE:**  \n“In custody?”\n\n**KAKASHI:**  \n“No.”"},{"level":2,"title":"Narration","path":"8. Secure-Package ANBU report projections > Narration","text":"The operative studies him for a moment.\n\nNot disapproval.\n\nAccounting."},{"level":2,"title":"Dialogue","path":"8. Secure-Package ANBU report projections > Dialogue","text":"**ANBU OPERATIVE:**  \n“You chose the objective.”\n\n**KAKASHI:**  \n“Yes.”"},{"level":2,"title":"Narration","path":"8. Secure-Package ANBU report projections > Narration","text":"The answer does not need defending.\n\n---"},{"level":2,"title":"Narration","path":"8. Secure-Package ANBU report projections > Narration","text":"Kakashi places the recovered package into the ANBU operative's hands.\n\nThe operative checks the seal once."},{"level":2,"title":"Dialogue","path":"8. Secure-Package ANBU report projections > Dialogue","text":"**ANBU OPERATIVE:**  \n“The first man?”\n\n**KAKASHI:**  \n“I followed him.”\n\n**ANBU OPERATIVE:**  \n“And?”\n\n**KAKASHI:**  \n“Lost the trail.”"},{"level":2,"title":"Narration","path":"8. Secure-Package ANBU report projections > Narration","text":"The operative looks at him."},{"level":2,"title":"Dialogue","path":"8. Secure-Package ANBU report projections > Dialogue","text":"**ANBU OPERATIVE:**  \n“After recovering the package.”\n\n**KAKASHI:**  \n“Yes.”\n\n**ANBU OPERATIVE:**  \n“You could have returned immediately.”\n\n**KAKASHI:**  \n“I could have.”"},{"level":2,"title":"Narration","path":"8. Secure-Package ANBU report projections > Narration","text":"The operative waits.\n\nKakashi does not offer an excuse."},{"level":2,"title":"Dialogue","path":"8. Secure-Package ANBU report projections > Dialogue","text":"**KAKASHI:**  \n“He was still part of it.”"},{"level":2,"title":"Narration","path":"8. Secure-Package ANBU report projections > Narration","text":"That is the whole answer.\n\nThe operative lets it stand.\n\n---"},{"level":2,"title":"Narration","path":"8. Secure-Package ANBU report projections > Narration","text":"Kakashi returns with the package.\n\nPakkun comes onto the rooftop beside him.\n\nThe ANBU operative's attention moves from the recovered objective to the unfamiliar ninken.\n\nThen back to Kakashi."},{"level":2,"title":"Dialogue","path":"8. Secure-Package ANBU report projections > Dialogue","text":"**ANBU OPERATIVE:**  \n“Report.”\n\n**KAKASHI:**  \n“I recovered the package from the receiver.”"},{"level":2,"title":"Narration","path":"8. Secure-Package ANBU report projections > Narration","text":"He hands it over."},{"level":2,"title":"Dialogue","path":"8. Secure-Package ANBU report projections > Dialogue","text":"**KAKASHI:**  \n“Then I caught the first man.”\n\n**ANBU OPERATIVE:**  \n“You caught him.”\n\n**KAKASHI:**  \n“I lost the fight.”"},{"level":2,"title":"Narration","path":"8. Secure-Package ANBU report projections > Narration","text":"Pakkun sits."},{"level":2,"title":"Dialogue","path":"8. Secure-Package ANBU report projections > Dialogue","text":"**PAKKUN:**  \n“He's leaving out that I helped.”"},{"level":2,"title":"Narration","path":"8. Secure-Package ANBU report projections > Narration","text":"The operative looks at him.\n\nKakashi does too."},{"level":2,"title":"Dialogue","path":"8. Secure-Package ANBU report projections > Dialogue","text":"**KAKASHI:**  \n“You did.”\n\n**PAKKUN:**  \n“Better.”"},{"level":2,"title":"Narration","path":"8. Secure-Package ANBU report projections > Narration","text":"The operative returns to the report."},{"level":2,"title":"Dialogue","path":"8. Secure-Package ANBU report projections > Dialogue","text":"**ANBU OPERATIVE:**  \n“The target escaped.”\n\n**KAKASHI:**  \n“Yes.”\n\n**ANBU OPERATIVE:**  \n“The package did not.”\n\n**KAKASHI:**  \n“No.”"},{"level":2,"title":"Narration","path":"8. Secure-Package ANBU report projections > Narration","text":"The operative holds both facts at once.\n\nSo does Kakashi."},{"level":2,"title":"System / Resolver","path":"8. Secure-Package ANBU report projections > System / Resolver","text":"For all section 8 variants:\n\n- commit only Kakashi-observed facts;\n- remove **Return to ANBU.** at report completion;\n- no hidden evaluation truth is disclosed;\n- if Pakkun is present, retain him through the existing explicit departure beat before private Minato evaluation;\n- transition into the existing terminal private Minato evaluation / Chronicle Receipt architecture using the exact committed branch state.\n\n---"},{"level":1,"title":"9. Completion boundary","path":"9. Completion boundary","text":"This scene family does not rewrite the already-approved AMT disposition endings.\n\nWhere section 7A reaches the four-way AMT choice, consume those exact authorities.\n\nWhere sections 3, 6A, 7B or direct **RETURN AND REPORT** reach the ANBU report, consume the appropriate section 8 projection.\n\nAfter the factual report, the existing terminal guard owns:\n\n- private Minato evaluation;\n- Chronicle Receipt;\n- reward commit;\n- Origin closure.\n\nNo terminal projection may invent PS/MI later location, custody or hidden-operation Knowledge.\n\n---"},{"level":1,"title":"Final lock","path":"Final lock","text":"> **SECURE THE PACKAGE means Kakashi prioritises Package Smuggler, causing Masked Interceptor to join and creating the exact PS+MI 2-v-1 Battle.**\n\n> **Win: package custody commits to Kakashi; PS/MI are Battle-defeated; Kakashi may STAY ON THE FIRST MAN or RETURN AND REPORT.**\n\n> **Loss: Package Smuggler escapes with the package; Masked Interceptor restrains Kakashi and leaves after him; Kakashi does not know what happens next.**\n\n> **A legitimate AMT reach uses the exact Pakkun interception backdrop and preserves “This yours?” / “Apparently.”**\n\n> **Package recovery and AMT capture remain separate accomplishments.**"}]},"observeBeatPackage":{"source":"Documentation/Story/Academy_Kakashi_Observe_Beat_Her_To_The_Package_Verbatim_Scene_Family_2026-09-19.md","sections":[{"level":1,"title":"Academy Kakashi Origin — WATCH THE EXCHANGE -> SECURE THE PACKAGE BEFORE THE ASSASSIN — Verbatim Scene Family","path":"Academy Kakashi Origin — WATCH THE EXCHANGE -> SECURE THE PACKAGE BEFORE THE ASSASSIN — Verbatim Scene Family","text":"**Date:** 2026-09-19  \n**Owner:** Writing / Story — Konoha under Stephen delegated-authoring authority  \n**Status:** **LOCKED VERBATIM — DELEGATED CLEAN CONTINUATION / IMPLEMENTATION READY**  \n**Branch:** `SCENE_03A / CHOICE_01 / BRANCH_C`  \n**Player-facing entry choice:** **SECURE THE PACKAGE BEFORE THE ASSASSIN**  \n**Primary priority:** **FINISH SHINOBI CHRONICLES ALPHA**"},{"level":2,"title":"Consumed authority","path":"Academy Kakashi Origin — WATCH THE EXCHANGE -> SECURE THE PACKAGE BEFORE THE ASSASSIN — Verbatim Scene Family > Consumed authority","text":"Consumes:\n\n- Scene 03A WATCH THE EXCHANGE exact authority;\n- `Academy_Kakashi_Seven_Remaining_Substantial_Branch_Closure_2026-09-15.md`;\n- `AK_SA_020` Secure Package Before Assassin;\n- current branch isolation / Knowledge law;\n- current exact backdrop inventory;\n- current Writing performance benchmark.\n\nThis is a resolver route.\n\nSuccess extracts the package and withdraws.\n\nFailure reconverges directly into the existing **SECURE THE PACKAGE** PS+MI 2-v-1 Battle state.\n\nDo not duplicate or reroll that Battle branch.\n\n---"},{"level":1,"title":"1. SECURE THE PACKAGE BEFORE THE ASSASSIN","path":"1. SECURE THE PACKAGE BEFORE THE ASSASSIN","text":"**Backdrop:** `Kakashi Origin Backdrop/sakura_tree_night.png`\n\n**Objective:** **Retrieve the package.**"},{"level":2,"title":"Narration","path":"1. SECURE THE PACKAGE BEFORE THE ASSASSIN > Narration","text":"Masked Interceptor moves.\n\nPackage Smuggler reacts.\n\nKakashi sees the gap between them.\n\nNot a gap in the street.\n\nA gap in timing.\n\nFor one instant, all three are moving toward the same point.\n\nNot the same person.\n\nThe package.\n\nKakashi goes first.\n\nPackage Smuggler tightens his grip.\n\nMasked Interceptor accelerates.\n\nThe distance collapses."},{"level":2,"title":"System / Resolver","path":"1. SECURE THE PACKAGE BEFORE THE ASSASSIN > System / Resolver","text":"Invoke the exact interception resolver:\n\n`academy_kakashi.resolver.secure_package_before_assassin`\n\nSource anchor:\n\n`AK_SA_020`\n\nThe resolver commits exactly one factual route family before presentation continues:\n\n- **SUCCESS** — Kakashi extracts the package and withdraws;\n- **FAILURE** — Kakashi is too late to separate the package from the PS+MI confrontation and the route enters the already-authored Secure Package 2-v-1 Battle state.\n\nDo not infer success from the choice label.\n\n---"},{"level":1,"title":"2. Resolver SUCCESS — clean extraction","path":"2. Resolver SUCCESS — clean extraction","text":"**Backdrop:** `Kakashi Origin Backdrop/sakura_tree_night.png`"},{"level":2,"title":"Narration","path":"2. Resolver SUCCESS — clean extraction > Narration","text":"Kakashi gets there first.\n\nHis hand closes around Package Smuggler's wrist.\n\nNot the weapon hand.\n\nThe package arm.\n\nHe turns with the man's momentum.\n\nThe grip breaks.\n\nThe package comes free.\n\nPackage Smuggler's expression changes half a second too late.\n\nMasked Interceptor reaches them a heartbeat after that.\n\nKakashi is already moving."},{"level":2,"title":"Dialogue","path":"2. Resolver SUCCESS — clean extraction > Dialogue","text":"**PACKAGE SMUGGLER:**  \n“Seriously?”"},{"level":2,"title":"Narration","path":"2. Resolver SUCCESS — clean extraction > Narration","text":"Kakashi does not stop to answer.\n\nHe clears the line between them with the package secured against him.\n\nMasked Interceptor checks her pursuit for one instant.\n\nLooks at Kakashi.\n\nThen back at Package Smuggler.\n\nHer apparent target is still standing in front of her.\n\nKakashi is not.\n\nHe disappears into the night with the objective."},{"level":2,"title":"Objective switch","path":"2. Resolver SUCCESS — clean extraction > Objective switch","text":"Remove:\n\n**Retrieve the package.**\n\nSet:\n\n**Return to ANBU.**"},{"level":2,"title":"System / Resolver","path":"2. Resolver SUCCESS — clean extraction > System / Resolver","text":"Commit:\n\n- package custody -> Kakashi;\n- ANBU Marked Target escaped;\n- PS remains behind;\n- MI remains behind;\n- Kakashi does not know the later PS/MI result after withdrawal;\n- no Battle;\n- no participant custody;\n- no Pakkun.\n\nDo not invent an off-screen PS/MI fight result.\n\n---"},{"level":1,"title":"3. SUCCESS — Return to ANBU","path":"3. SUCCESS — Return to ANBU","text":"**Backdrop:** `Kakashi Origin Backdrop/rooftop_night.png`"},{"level":2,"title":"Narration","path":"3. SUCCESS — Return to ANBU > Narration","text":"Kakashi returns to the rooftop with the package in hand.\n\nThe ANBU operative sees it before Kakashi says anything."},{"level":2,"title":"Dialogue","path":"3. SUCCESS — Return to ANBU > Dialogue","text":"**ANBU OPERATIVE:**  \n“You recovered it.”\n\n**KAKASHI:**  \n“Yes.”"},{"level":2,"title":"Narration","path":"3. SUCCESS — Return to ANBU > Narration","text":"He hands it over.\n\nThe operative accepts it and checks the seal."},{"level":2,"title":"Dialogue","path":"3. SUCCESS — Return to ANBU > Dialogue","text":"**ANBU OPERATIVE:**  \n“Report.”\n\n**KAKASHI:**  \n“The handoff completed.”\n\n**ANBU OPERATIVE:**  \n“To the second man.”\n\n**KAKASHI:**  \n“Yes.”\n\n**ANBU OPERATIVE:**  \n“And the masked shinobi?”\n\n**KAKASHI:**  \n“She moved on him before he cleared the exchange.”\n\n**ANBU OPERATIVE:**  \n“You intervened.”\n\n**KAKASHI:**  \n“For the package.”"},{"level":2,"title":"Narration","path":"3. SUCCESS — Return to ANBU > Narration","text":"The operative looks down at what Kakashi returned."},{"level":2,"title":"Dialogue","path":"3. SUCCESS — Return to ANBU > Dialogue","text":"**ANBU OPERATIVE:**  \n“You got there before she did.”\n\n**KAKASHI:**  \n“Yes.”\n\n**ANBU OPERATIVE:**  \n“The first man?”\n\n**KAKASHI:**  \n“Gone.”\n\n**ANBU OPERATIVE:**  \n“The other two?”"},{"level":2,"title":"Narration","path":"3. SUCCESS — Return to ANBU > Narration","text":"Kakashi does not pretend to know more than he saw."},{"level":2,"title":"Dialogue","path":"3. SUCCESS — Return to ANBU > Dialogue","text":"**KAKASHI:**  \n“Still there when I left.”\n\n**ANBU OPERATIVE:**  \n“You don't know what happened after.”\n\n**KAKASHI:**  \n“No.”"},{"level":2,"title":"Narration","path":"3. SUCCESS — Return to ANBU > Narration","text":"The operative gives one small nod.\n\nThe package is back.\n\nThe rest of the night is not something Kakashi invents to make the report cleaner."},{"level":2,"title":"System / Resolver","path":"3. SUCCESS — Return to ANBU > System / Resolver","text":"- package transfers to ANBU separately;\n- report remains observer-bounded;\n- no PS/MI later state is fabricated;\n- remove **Return to ANBU.** at report completion;\n- proceed to existing private Minato evaluation / Chronicle Receipt / reward closure from committed facts.\n\n---"},{"level":1,"title":"4. Resolver FAILURE — reconverge to PS+MI Battle","path":"4. Resolver FAILURE — reconverge to PS+MI Battle","text":"**Backdrop:** `Kakashi Origin Backdrop/sakura_tree_night.png`"},{"level":2,"title":"Narration","path":"4. Resolver FAILURE — reconverge to PS+MI Battle > Narration","text":"Kakashi is half a step late.\n\nHis hand reaches the package at the same moment Masked Interceptor reaches Package Smuggler.\n\nPackage Smuggler twists away.\n\nMasked Interceptor cuts across him.\n\nKakashi commits through the opening anyway.\n\nThe three lines collapse into one fight.\n\nThere is no clean extraction anymore."},{"level":2,"title":"System / Resolver","path":"4. Resolver FAILURE — reconverge to PS+MI Battle > System / Resolver","text":"Do not create a second Secure Package Battle definition.\n\nTransition directly into section 2 **PL Battle** of:\n\n`Documentation/Story/Academy_Kakashi_Observe_Secure_Package_Verbatim_Scene_Family_2026-09-19.md`\n\nusing:\n\n`academy_kakashi_origin_battle_ps_mi_2v1`\n\nand then consume that scene family's exact Battle victory/defeat / continuation authority.\n\nDo not replay its BRANCH_B entry setup before Battle.\n\nThe resolver failure itself is the causal bridge into the shared 2-v-1 state.\n\n---"},{"level":1,"title":"Final lock","path":"Final lock","text":"> **SECURE THE PACKAGE BEFORE THE ASSASSIN is a race, not a renamed SECURE THE PACKAGE branch.**\n\n> **Success: Kakashi extracts the objective cleanly and withdraws before the scene becomes a Battle.**\n\n> **Failure: the race collapses into the already-authored Package Smuggler + Masked Interceptor 2-v-1 Battle.**\n\n> **PS/MI off-screen history after clean success remains unknown to Kakashi.**"}]},"observeDealFirst":{"source":"Documentation/Story/Academy_Kakashi_Observe_Deal_With_Her_First_Then_Chase_Package_Verbatim_Scene_Family_2026-09-19.md","sections":[{"level":1,"title":"Academy Kakashi Origin — WATCH THE EXCHANGE -> DEFEAT THE ASSASSIN, THEN SECURE THE PACKAGE — Verbatim Scene Family","path":"Academy Kakashi Origin — WATCH THE EXCHANGE -> DEFEAT THE ASSASSIN, THEN SECURE THE PACKAGE — Verbatim Scene Family","text":"**Date:** 2026-09-19  \n**Owner:** Writing / Story — Konoha under Stephen delegated-authoring authority  \n**Status:** **LOCKED VERBATIM — DELEGATED CLEAN CONTINUATION / IMPLEMENTATION READY**  \n**Branch:** `SCENE_03A / CHOICE_01 / BRANCH_D`  \n**Player-facing entry choice:** **DEFEAT THE ASSASSIN, THEN SECURE THE PACKAGE**  \n**Primary priority:** **FINISH SHINOBI CHRONICLES ALPHA**"},{"level":2,"title":"Branch identity","path":"Academy Kakashi Origin — WATCH THE EXCHANGE -> DEFEAT THE ASSASSIN, THEN SECURE THE PACKAGE — Verbatim Scene Family > Branch identity","text":"This branch must not collapse into STOP THE ASSASSIN.\n\nThe current distinction is binding:\n\n- **STOP THE ASSASSIN:** fast MI victory opens an immediate fork between PS and AMT.\n- **DEFEAT THE ASSASSIN, THEN SECURE THE PACKAGE:** Kakashi has already committed to package-second sequencing. After MI, PS is the next objective. AMT can become reachable only later if PS is resolved quickly enough.\n\n---"},{"level":1,"title":"1. Entry — deal with her first","path":"1. Entry — deal with her first","text":"**Backdrop:** `Kakashi Origin Backdrop/fight_at_sakura_tree.png`\n\n**Objective:** **Retrieve the package.**"},{"level":2,"title":"Narration","path":"1. Entry — deal with her first > Narration","text":"Package Smuggler is already moving away with the objective.\n\nANBU Marked Target is farther ahead.\n\nMasked Interceptor is the immediate violent pressure.\n\nKakashi makes the priority explicit.\n\nHer first.\n\nThe package second.\n\nHe turns into Masked Interceptor's line instead of chasing Package Smuggler.\n\nPackage Smuggler sees the opening and takes it.\n\nEvery second Kakashi spends here becomes distance somewhere else.\n\nMasked Interceptor commits.\n\nSo does Kakashi."},{"level":2,"title":"System / Resolver","path":"1. Entry — deal with her first > System / Resolver","text":"**PL BATTLE:** Kakashi Hatake vs Masked Interceptor\n\nBattle config:\n\n`academy_kakashi_origin_battle_seq_mi`\n\nSource anchor:\n\n`AK_SA_015`\n\nThe controller-action count is Story-relevant:\n\n- victory within **1–4** action opportunities preserves the clean PS catch-up opportunity;\n- victory on **5+** closes it;\n- Battle defeat closes the qualifying package catch-up route.\n\n---"},{"level":1,"title":"2. MI Battle defeat","path":"2. MI Battle defeat","text":"**Backdrop:** `Kakashi Origin Backdrop/fight_at_sakura_tree.png`"},{"level":2,"title":"Narration","path":"2. MI Battle defeat > Narration","text":"Masked Interceptor wins the exchange between them.\n\nThat is enough.\n\nPackage Smuggler had already been buying distance with every second of the fight.\n\nNow the distance is gone from recoverable to unknown.\n\nKakashi looks toward the route the package took.\n\nNothing useful remains.\n\nANBU Marked Target is gone.\n\nPackage Smuggler is gone with the objective.\n\nWhatever Masked Interceptor does next must come from what actually happens here.\n\nKakashi does not invent it afterward to make the report cleaner."},{"level":2,"title":"Objective switch","path":"2. MI Battle defeat > Objective switch","text":"Remove:\n\n**Retrieve the package.**\n\nSet:\n\n**Return to ANBU.**"},{"level":2,"title":"System / Resolver","path":"2. MI Battle defeat > System / Resolver","text":"Commit:\n\n- MI Battle victory over Kakashi;\n- PS escaped with package;\n- AMT escaped;\n- no Kakashi package custody;\n- no Kakashi participant custody;\n- no PS catch-up;\n- no Pakkun.\n\nIf a separate exact participant-autonomy occurrence commits an MI post-Battle action, project only that committed fact.\n\nIf none commits, do not manufacture restraint, escape, custody, injury or another flourish.\n\nProceed to section 8A factual report.\n\n---"},{"level":1,"title":"3. MI victory in 5+ action opportunities","path":"3. MI victory in 5+ action opportunities","text":"**Backdrop:** `Kakashi Origin Backdrop/fight_at_sakura_tree.png`"},{"level":2,"title":"Narration","path":"3. MI victory in 5+ action opportunities > Narration","text":"Masked Interceptor goes down.\n\nToo late.\n\nKakashi listens toward the route Package Smuggler took.\n\nNothing.\n\nNo hurried footfall.\n\nNo changing line.\n\nNo mistake to follow.\n\nThe fight is over.\n\nThe package problem is not.\n\nPackage Smuggler has had too much time.\n\nWinning here does not pull him back into reach."},{"level":2,"title":"Objective switch","path":"3. MI victory in 5+ action opportunities > Objective switch","text":"Remove:\n\n**Retrieve the package.**\n\nSet:\n\n**Return to ANBU.**"},{"level":2,"title":"System / Resolver","path":"3. MI victory in 5+ action opportunities > System / Resolver","text":"- MI Battle-defeated;\n- PS escaped with package;\n- AMT escaped;\n- no PS catch-up;\n- no Pakkun;\n- no participant custody/death inferred from MI Battle victory.\n\nProceed to section 8B factual report.\n\n---"},{"level":1,"title":"4. MI victory in 1–4 action opportunities","path":"4. MI victory in 1–4 action opportunities","text":"**Backdrop:** `Kakashi Origin Backdrop/fight_at_sakura_tree.png`"},{"level":2,"title":"Narration","path":"4. MI victory in 1–4 action opportunities > Narration","text":"Masked Interceptor goes down quickly enough that the next problem is still audible.\n\nFootsteps.\n\nFading.\n\nNot gone.\n\nKakashi looks once at the masked woman.\n\nBeating her has not explained who she is.\n\nIt has only removed her from his path.\n\nHis attention snaps back to the package route.\n\nPackage Smuggler has a lead.\n\nNot an insurmountable one.\n\nKakashi moves."},{"level":2,"title":"Objective switch","path":"4. MI victory in 1–4 action opportunities > Objective switch","text":"Set:\n\n**Catch the package.**"},{"level":2,"title":"Choice","path":"4. MI victory in 1–4 action opportunities > Choice","text":"Present:\n\n**CHASE THE PACKAGE SMUGGLER**\n\nNo direct AMT option appears here.\n\nThis branch is package-second by commitment."},{"level":2,"title":"System / Resolver","path":"4. MI victory in 1–4 action opportunities > System / Resolver","text":"The player has already committed the package-second sequence.\n\nResolve the PS catch-up from current factual pursuit state.\n\nA fast MI victory grants a pursuit opportunity, not automatic package recovery.\n\n---"},{"level":2,"title":"Narration","path":"5. PS catch-up failure > Narration","text":"Kakashi takes the next junction too late.\n\nHe checks the street.\n\nThen the roofline.\n\nNothing.\n\nPackage Smuggler has disappeared into the village with the objective.\n\nThe opening Kakashi preserved by beating Masked Interceptor quickly was real.\n\nSo was the possibility of losing it."},{"level":2,"title":"Objective switch","path":"5. PS catch-up failure > Objective switch","text":"Remove:\n\n**Catch the package.**\n\nSet:\n\n**Return to ANBU.**"},{"level":2,"title":"System / Resolver","path":"5. PS catch-up failure > System / Resolver","text":"- PS escapes with package;\n- AMT remains escaped;\n- MI remains in her last committed factual state;\n- no Pakkun.\n\nProceed to section 8C factual report.\n\n---"},{"level":1,"title":"6. PS catch-up success","path":"6. PS catch-up success","text":"**Backdrop:** `Kakashi Origin Backdrop/konoha_alleyway_alt_night.png`\n\n**Objective:** **Recover the package.**"},{"level":2,"title":"Narration","path":"6. PS catch-up success > Narration","text":"Kakashi catches sight of Package Smuggler at the next junction.\n\nThe man hears him coming.\n\nLooks back.\n\nHis expression sinks."},{"level":2,"title":"Dialogue","path":"6. PS catch-up success > Dialogue","text":"**PACKAGE SMUGGLER:**  \n“You again.”"},{"level":2,"title":"Narration","path":"6. PS catch-up success > Narration","text":"Kakashi's eye goes to the package."},{"level":2,"title":"Dialogue","path":"6. PS catch-up success > Dialogue","text":"**KAKASHI:**  \n“Me again.”"},{"level":2,"title":"Narration","path":"6. PS catch-up success > Narration","text":"Package Smuggler changes direction.\n\nKakashi cuts him off.\n\nThe man stops.\n\nLooks at the road behind him.\n\nThen at Kakashi.\n\nNo Masked Interceptor now.\n\nNo ANBU Marked Target.\n\nJust the two of them.\n\nAnd the package."},{"level":2,"title":"Dialogue","path":"6. PS catch-up success > Dialogue","text":"**PACKAGE SMUGGLER:**  \n“You could've stayed down the street.”\n\n**KAKASHI:**  \n“You could've left the package.”"},{"level":2,"title":"Narration","path":"6. PS catch-up success > Narration","text":"Package Smuggler reaches for his weapon."},{"level":2,"title":"Dialogue","path":"6. PS catch-up success > Dialogue","text":"**PACKAGE SMUGGLER:**  \n“Neither of us is very good at taking advice.”\n\n---"},{"level":1,"title":"7. PS PL Battle","path":"7. PS PL Battle","text":"**Kakashi Hatake vs Package Smuggler**\n\nBattle config:\n\n`academy_kakashi_origin_battle_seq_ps`\n\nThe PS stage has its own fresh controller-action count:\n\n- victory within **1–3** may preserve later AMT reach;\n- victory on **4+** closes later AMT reach;\n- Battle defeat means PS escapes with the package.\n\n---"},{"level":2,"title":"7A. PS defeats Kakashi","path":"7. PS PL Battle > 7A. PS defeats Kakashi","text":"**Backdrop:** `Kakashi Origin Backdrop/konoha_alleyway_alt_night.png`"},{"level":2,"title":"Narration","path":"7. PS PL Battle > Narration","text":"Package Smuggler gets through him.\n\nKakashi turns after him.\n\nToo late.\n\nThe man is already moving again.\n\nThe package stays with him.\n\nKakashi has fought twice for the same objective tonight.\n\nThe second loss closes what little trail remained."},{"level":2,"title":"Objective switch","path":"7. PS PL Battle > Objective switch","text":"Set:\n\n**Return to ANBU.**"},{"level":2,"title":"System / Resolver","path":"7. PS PL Battle > System / Resolver","text":"- PS Battle victory over Kakashi;\n- package remains with PS;\n- PS escapes;\n- AMT escaped;\n- MI history preserved;\n- no Pakkun.\n\nProceed to section 8D factual report.\n\n---"},{"level":2,"title":"7B. Kakashi defeats PS","path":"7. PS PL Battle > 7B. Kakashi defeats PS","text":"**Backdrop:** `Kakashi Origin Backdrop/konoha_alleyway_alt_night.png`"},{"level":2,"title":"Narration","path":"7. PS PL Battle > Narration","text":"Package Smuggler goes down.\n\nKakashi stays on him long enough to know the fight is finished.\n\nThen his attention moves to the objective.\n\nHe takes the package from the defeated man's reach.\n\nChecks the seal.\n\nSecures it against himself.\n\nOnly then does he look farther down the route."},{"level":2,"title":"System / Resolver","path":"7. PS PL Battle > System / Resolver","text":"PS Battle victory and package recovery are separate facts.\n\nCommit the existing package-recovery occurrence before deriving the next choice.\n\nNo PS death or custody is inferred from Battle victory."},{"level":3,"title":"If PS victory took 4+ action opportunities","path":"7. PS PL Battle > System / Resolver > If PS victory took 4+ action opportunities","text":"AMT is no longer reachable.\n\nRemove:\n\n**Recover the package.**\n\nSet:\n\n**Return to ANBU.**\n\nProceed to section 8E factual report."},{"level":3,"title":"If PS victory took 1–3 action opportunities","path":"7. PS PL Battle > System / Resolver > If PS victory took 1–3 action opportunities","text":"AMT may still be reachable.\n\nRemove:\n\n**Recover the package.**\n\nNo objective while the decision is active.\n\nPresent:\n\n1. **STAY ON THE FIRST MAN**\n2. **RETURN AND REPORT**\n\nNo new hidden timing penalty is added after the completed PS Battle.\n\n---"},{"level":2,"title":"Narration","path":"7C. STAY ON THE FIRST MAN after fast PS victory > Narration","text":"Kakashi leaves Package Smuggler behind.\n\nThe package is secured.\n\nThe first man's trail is thin.\n\nStill usable.\n\nKakashi takes it."},{"level":2,"title":"Objective","path":"7C. STAY ON THE FIRST MAN after fast PS victory > Objective","text":"**Catch the first man.**"},{"level":2,"title":"System / Resolver","path":"7C. STAY ON THE FIRST MAN after fast PS victory > System / Resolver","text":"Resolve the current AMT pursuit from committed state.\n\nIf AMT is reached:\n\n- Pakkun becomes present;\n- use `Kakashi Origin Backdrop/alleyway_konoha_night.png`;\n- preserve the established exchange:\n  - **PAKKUN:** “This yours?”\n  - **KAKASHI:** “Apparently.”\n- launch `academy_kakashi_origin_battle_seq_amt_pakkun`;\n- on AMT victory consume the existing four-way AMT disposition authority;\n- on AMT defeat preserve already-committed package custody and return to factual debrief;\n- Pakkun remains until explicit departure.\n\nIf AMT pursuit fails:\n\n- AMT escapes;\n- package remains with Kakashi;\n- Pakkun does not appear unless Kakashi factually reached him;\n- proceed to factual report.\n\nDo not collapse this into STOP THE ASSASSIN's direct post-MI AMT fork.\n\n---"},{"level":1,"title":"8. Factual ANBU report projections","path":"8. Factual ANBU report projections","text":"**Backdrop:** `Kakashi Origin Backdrop/rooftop_night.png`\n\nAll variants preserve only Kakashi-observed facts.\n\n---"},{"level":2,"title":"8A. MI Battle defeat / package lost","path":"8. Factual ANBU report projections > 8A. MI Battle defeat / package lost","text":"**ANBU OPERATIVE:**  \n“Report.”\n\n**KAKASHI:**  \n“The handoff completed.”\n\n**ANBU OPERATIVE:**  \n“The package?”\n\n**KAKASHI:**  \n“I chose the masked shinobi first.”"},{"level":2,"title":"Narration","path":"8. Factual ANBU report projections > Narration","text":"The operative waits."},{"level":2,"title":"Dialogue","path":"8. Factual ANBU report projections > Dialogue","text":"**KAKASHI:**  \n“She beat me.”\n\n**ANBU OPERATIVE:**  \n“And the receiver?”\n\n**KAKASHI:**  \n“Gone with the package.”\n\n**ANBU OPERATIVE:**  \n“The first man?”\n\n**KAKASHI:**  \n“Gone before that.”"},{"level":2,"title":"Narration","path":"8. Factual ANBU report projections > Narration","text":"If an exact MI post-Battle action was committed and observed, Kakashi reports it here.\n\nOtherwise he does not invent one.\n\n---"},{"level":2,"title":"8B. MI defeated too slowly / package lost","path":"8. Factual ANBU report projections > 8B. MI defeated too slowly / package lost","text":"**ANBU OPERATIVE:**  \n“You stopped the masked shinobi.”\n\n**KAKASHI:**  \n“Yes.”\n\n**ANBU OPERATIVE:**  \n“And lost the package.”\n\n**KAKASHI:**  \n“Yes.”"},{"level":2,"title":"Narration","path":"8. Factual ANBU report projections > Narration","text":"The two answers belong together.\n\nKakashi does not use one to excuse the other."},{"level":2,"title":"Dialogue","path":"8. Factual ANBU report projections > Dialogue","text":"**ANBU OPERATIVE:**  \n“Could you still see the receiver when the fight ended?”\n\n**KAKASHI:**  \n“No.”\n\n**ANBU OPERATIVE:**  \n“Then say that.”\n\n**KAKASHI:**  \n“I just did.”"},{"level":2,"title":"Narration","path":"8. Factual ANBU report projections > Narration","text":"The operative's head tilts slightly.\n\nNot quite amusement.\n\nNot quite irritation.\n\nThen he moves on.\n\n---"},{"level":2,"title":"8C. Fast MI victory / PS catch-up failed","path":"8. Factual ANBU report projections > 8C. Fast MI victory / PS catch-up failed","text":"**KAKASHI:**  \n“I beat the masked shinobi and went after the package.”\n\n**ANBU OPERATIVE:**  \n“You caught the receiver?”\n\n**KAKASHI:**  \n“No.”\n\n**ANBU OPERATIVE:**  \n“But you had the trail.”\n\n**KAKASHI:**  \n“For a while.”"},{"level":2,"title":"Narration","path":"8. Factual ANBU report projections > Narration","text":"Kakashi does not dress opportunity up as success.\n\n---"},{"level":2,"title":"8D. PS Battle defeat / package lost","path":"8. Factual ANBU report projections > 8D. PS Battle defeat / package lost","text":"**ANBU OPERATIVE:**  \n“You reached the receiver.”\n\n**KAKASHI:**  \n“Yes.”\n\n**ANBU OPERATIVE:**  \n“And?”\n\n**KAKASHI:**  \n“He beat me.”"},{"level":2,"title":"Narration","path":"8. Factual ANBU report projections > Narration","text":"The operative's attention stays on him."},{"level":2,"title":"Dialogue","path":"8. Factual ANBU report projections > Dialogue","text":"**ANBU OPERATIVE:**  \n“After you had already defeated the masked shinobi.”\n\n**KAKASHI:**  \n“Yes.”\n\n**ANBU OPERATIVE:**  \n“The package left with him.”\n\n**KAKASHI:**  \n“Yes.”"},{"level":2,"title":"Narration","path":"8. Factual ANBU report projections > Narration","text":"No excuse.\n\nNo missing step.\n\nJust the sequence.\n\n---"},{"level":2,"title":"Narration","path":"8. Factual ANBU report projections > Narration","text":"Kakashi puts the recovered package into the operative's hand."},{"level":2,"title":"Dialogue","path":"8. Factual ANBU report projections > Dialogue","text":"**ANBU OPERATIVE:**  \n“You got it back.”\n\n**KAKASHI:**  \n“Yes.”\n\n**ANBU OPERATIVE:**  \n“The first man?”\n\n**KAKASHI:**  \n“Too far by then.”\n\n**ANBU OPERATIVE:**  \n“You chose the package twice.”"},{"level":2,"title":"Narration","path":"8. Factual ANBU report projections > Narration","text":"Kakashi considers the wording."},{"level":2,"title":"Dialogue","path":"8. Factual ANBU report projections > Dialogue","text":"**KAKASHI:**  \n“I chose the masked shinobi first.”"},{"level":2,"title":"Narration","path":"8. Factual ANBU report projections > Narration","text":"His eye shifts to the recovered objective."},{"level":2,"title":"Dialogue","path":"8. Factual ANBU report projections > Dialogue","text":"**KAKASHI:**  \n“Then the package.”"},{"level":2,"title":"Narration","path":"8. Factual ANBU report projections > Narration","text":"The operative nods once.\n\nThe distinction matters.\n\n---"},{"level":2,"title":"8F. Package recovered / later AMT pursuit failed or AMT Battle lost","path":"8. Factual ANBU report projections > 8F. Package recovered / later AMT pursuit failed or AMT Battle lost","text":"Use exact committed state:\n\n- package recovered;\n- MI defeated earlier;\n- PS defeated later;\n- AMT either escaped during pursuit or after defeating Kakashi/Pakkun;\n- Pakkun included only if he factually entered.\n\nThe operative asks for the sequence, not a moral verdict.\n\nKakashi reports:\n\n- why he chose MI first;\n- that he caught PS afterward;\n- that he recovered the package;\n- that he continued after AMT if he did;\n- the actual AMT result;\n- Pakkun's involvement where observed.\n\nIf Pakkun is present at debrief, preserve his current dry/autonomous voice and consume the existing explicit departure before private Minato evaluation."},{"level":2,"title":"System / Resolver","path":"8. Factual ANBU report projections > System / Resolver","text":"At all report endings:\n\n- remove **Return to ANBU.**;\n- do not reveal hidden evaluation truth;\n- transition into the existing private Minato / Chronicle Receipt / reward closure using exact committed facts.\n\n---"},{"level":1,"title":"Final lock","path":"Final lock","text":"> **DEFEAT THE ASSASSIN, THEN SECURE THE PACKAGE is package-second by commitment.**\n\n> **MI <=4 preserves PS pursuit; MI 5+ closes it.**\n\n> **After fast MI victory, there is no direct AMT choice. Kakashi must resolve PS next.**\n\n> **PS <=3 may later preserve AMT; PS 4+ closes AMT.**\n\n> **PS-focused chase/Battle scenes use `Kakashi Origin Backdrop/konoha_alleyway_alt_night.png`.**\n\n> **The branch remains distinct from STOP THE ASSASSIN even though both may eventually traverse MI -> PS -> AMT.**"}]},"observeOriginal":{"source":"Documentation/Story/Academy_Kakashi_Observe_Go_After_Original_Target_Verbatim_Scene_Family_2026-09-19.md","sections":[{"level":1,"title":"Academy Kakashi Origin — WATCH THE EXCHANGE -> GO AFTER THE ORIGINAL TARGET — Verbatim Scene Family","path":"Academy Kakashi Origin — WATCH THE EXCHANGE -> GO AFTER THE ORIGINAL TARGET — Verbatim Scene Family","text":"**Date:** 2026-09-19  \n**Owner:** Writing / Story — Konoha under Stephen delegated-authoring authority  \n**Status:** **LOCKED VERBATIM — IMPLEMENTATION READY**  \n**Branch:** `SCENE_03A / CHOICE_01 / BRANCH_E`  \n**Player-facing entry choice:** **GO AFTER THE ORIGINAL TARGET**  \n**Primary priority:** **FINISH SHINOBI CHRONICLES ALPHA**"},{"level":2,"title":"Consumed authority","path":"Academy Kakashi Origin — WATCH THE EXCHANGE -> GO AFTER THE ORIGINAL TARGET — Verbatim Scene Family > Consumed authority","text":"This scene family consumes:\n\n- exact Scene 03A WATCH THE EXCHANGE lock;\n- `AK_SA_021` GO AFTER ORIGINAL TARGET;\n- current Pakkun reach/continuity authority;\n- global post-Battle disposition simplification;\n- `Academy_Kakashi_Package_Missing_AMT_Post_Battle_Disposition_Lock_2026-09-19.md`;\n- current exact backdrop inventory;\n- current personality / voice registry;\n- current Writing benchmark.\n\nThe package has already transferred to Package Smuggler before this branch starts.\n\nKakashi knowingly chooses the original carrier instead of the current package holder.\n\nPackage Smuggler pursuit closes once this choice commits.\n\n---"},{"level":1,"title":"1. GO AFTER THE ORIGINAL TARGET","path":"1. GO AFTER THE ORIGINAL TARGET","text":"**Backdrop:** `Kakashi Origin Backdrop/sakura_tree_night.png`\n\n**Objective:** **Catch the original target.**"},{"level":2,"title":"Narration","path":"1. GO AFTER THE ORIGINAL TARGET > Narration","text":"Kakashi watches the package leave in Package Smuggler's hands.\n\nMasked Interceptor enters the street.\n\nANBU Marked Target keeps moving.\n\nThe obvious choice is the package.\n\nKakashi chooses the man who carried it here.\n\nHe turns away from the objective and goes after ANBU Marked Target.\n\nThat choice costs him immediately.\n\nPackage Smuggler disappears in the opposite direction with the package.\n\nMasked Interceptor remains behind with him.\n\nKakashi does not look back."},{"level":2,"title":"System / Resolver","path":"1. GO AFTER THE ORIGINAL TARGET > System / Resolver","text":"Commit:\n\n- `GO AFTER THE ORIGINAL TARGET`;\n- Package Smuggler pursuit closed;\n- package remains with its actual committed holder, normally Package Smuggler;\n- Masked Interceptor's later off-screen state remains unknown to Kakashi unless another exact occurrence later exposes it.\n\nResolve AMT pursuit.\n\n---"},{"level":2,"title":"Narration","path":"2. Pursuit failure > Narration","text":"ANBU Marked Target clears the next street before Kakashi can close the distance.\n\nKakashi follows.\n\nOne turn.\n\nThen another.\n\nThe trail thins.\n\nA roof tile shifted here.\n\nA landing there.\n\nThen nothing.\n\nKakashi stops.\n\nNot because he wants to.\n\nBecause chasing a guess is no longer tracking.\n\nThe package is gone in the other direction.\n\nThe man is gone ahead.\n\nKakashi chose one.\n\nAnd lost him too."},{"level":2,"title":"Objective switch","path":"2. Pursuit failure > Objective switch","text":"Remove:\n\n**Catch the original target.**\n\nSet:\n\n**Return to ANBU.**"},{"level":2,"title":"System / Resolver","path":"2. Pursuit failure > System / Resolver","text":"Commit:\n\n- AMT escaped;\n- package remains missing;\n- no Pakkun because Kakashi never legitimately reached AMT;\n- no target custody;\n- no invented later PS/MI facts.\n\nProceed to factual ANBU report.\n\n---"},{"level":1,"title":"3. Pursuit success — Pakkun corners AMT","path":"3. Pursuit success — Pakkun corners AMT","text":"**Backdrop:** `Kakashi Origin Backdrop/alleyway_konoha_night.png`"},{"level":2,"title":"Narration","path":"3. Pursuit success — Pakkun corners AMT > Narration","text":"ANBU Marked Target rounds the next corner.\n\nThen stops.\n\nA small ninken is sitting in the street ahead of him.\n\nHe stares down at it.\n\nThe ninken looks past him.\n\nKakashi lands behind.\n\nPakkun's ears lift."},{"level":2,"title":"Dialogue","path":"3. Pursuit success — Pakkun corners AMT > Dialogue","text":"**PAKKUN:**  \n“This yours?”"},{"level":2,"title":"Narration","path":"3. Pursuit success — Pakkun corners AMT > Narration","text":"Kakashi looks at ANBU Marked Target."},{"level":2,"title":"Dialogue","path":"3. Pursuit success — Pakkun corners AMT > Dialogue","text":"**KAKASHI:**  \n“Apparently.”"},{"level":2,"title":"Narration","path":"3. Pursuit success — Pakkun corners AMT > Narration","text":"ANBU Marked Target looks between them.\n\nThen at Kakashi."},{"level":2,"title":"Dialogue","path":"3. Pursuit success — Pakkun corners AMT > Dialogue","text":"**ANBU MARKED TARGET:**  \n“You know I don't have the package anymore.”\n\n**KAKASHI:**  \n“I know.”"},{"level":2,"title":"Narration","path":"3. Pursuit success — Pakkun corners AMT > Narration","text":"That answer bothers him more than an accusation would have."},{"level":2,"title":"Dialogue","path":"3. Pursuit success — Pakkun corners AMT > Dialogue","text":"**ANBU MARKED TARGET:**  \n“Then why are you still following me?”\n\n**KAKASHI:**  \n“You were the one I started with.”\n\n**ANBU MARKED TARGET:**  \n“And the package?”\n\n**KAKASHI:**  \n“Gone.”"},{"level":2,"title":"Narration","path":"3. Pursuit success — Pakkun corners AMT > Narration","text":"Kakashi settles his stance."},{"level":2,"title":"Dialogue","path":"3. Pursuit success — Pakkun corners AMT > Dialogue","text":"**KAKASHI:**  \n“You aren't.”"},{"level":2,"title":"Narration","path":"3. Pursuit success — Pakkun corners AMT > Narration","text":"Pakkun rises.\n\nANBU Marked Target glances toward the alley mouth.\n\nPakkun notices."},{"level":2,"title":"Dialogue","path":"3. Pursuit success — Pakkun corners AMT > Dialogue","text":"**PAKKUN:**  \n“He's thinking about running.”\n\n**KAKASHI:**  \n“I know.”\n\n**ANBU MARKED TARGET:**  \n“You two always this helpful?”\n\n**PAKKUN:**  \n“We just met.”\n\n---"},{"level":1,"title":"4. PL Battle","path":"4. PL Battle","text":"**Kakashi Hatake with Pakkun as temporary Story-authorised Summon vs ANBU Marked Target**\n\nUse:\n\n`academy_kakashi_origin_battle_seq_amt_pakkun`\n\nPakkun is present because Kakashi legitimately reached AMT.\n\nPakkun remains autonomous.\n\nNo permanent Summon ownership, assignment, contract or reciprocal name Knowledge is created.\n\nPackage custody remains separate from Battle result.\n\n---"},{"level":1,"title":"5. AMT defeats Kakashi/Pakkun","path":"5. AMT defeats Kakashi/Pakkun","text":"**Backdrop:** `Kakashi Origin Backdrop/alleyway_konoha_night.png`"},{"level":2,"title":"Narration","path":"5. AMT defeats Kakashi/Pakkun > Narration","text":"ANBU Marked Target finds the opening first.\n\nKakashi loses the fight.\n\nThe man does not stay to explain it.\n\nHe runs.\n\nThe package does not magically return to him because he won.\n\nIt is still wherever the package state says it is.\n\nPakkun remains nearby long enough to watch the alley empty."},{"level":2,"title":"Dialogue","path":"5. AMT defeats Kakashi/Pakkun > Dialogue","text":"**PAKKUN:**  \n“You chased the man without the package.”\n\n**KAKASHI:**  \n“I noticed.”\n\n**PAKKUN:**  \n“Good.”"},{"level":2,"title":"Narration","path":"5. AMT defeats Kakashi/Pakkun > Narration","text":"Kakashi looks at him."},{"level":2,"title":"Dialogue","path":"5. AMT defeats Kakashi/Pakkun > Dialogue","text":"**PAKKUN:**  \n“Saves me explaining it.”"},{"level":2,"title":"Objective switch","path":"5. AMT defeats Kakashi/Pakkun > Objective switch","text":"Set:\n\n**Return to ANBU.**"},{"level":2,"title":"System / Resolver","path":"5. AMT defeats Kakashi/Pakkun > System / Resolver","text":"Commit:\n\n- Kakashi/Pakkun Battle defeat;\n- AMT escapes;\n- package remains with actual committed holder/location;\n- no target custody;\n- no automatic package transfer;\n- Pakkun remains present until explicit departure or legitimate separation.\n\nProceed to factual ANBU report.\n\n---"},{"level":1,"title":"6. Kakashi/Pakkun defeat AMT","path":"6. Kakashi/Pakkun defeat AMT","text":"**Backdrop:** `Kakashi Origin Backdrop/alleyway_konoha_night.png`"},{"level":2,"title":"Narration","path":"6. Kakashi/Pakkun defeat AMT > Narration","text":"ANBU Marked Target goes down.\n\nKakashi stays on him until the fight is finished.\n\nPakkun watches from a few steps away.\n\nThe package is still missing.\n\nThat problem has not become smaller because this one is on the ground.\n\nBut ANBU Marked Target is no longer running.\n\nKakashi looks at him.\n\nThen decides what happens next."},{"level":2,"title":"Choices","path":"6. Kakashi/Pakkun defeat AMT > Choices","text":"Present exactly, in this order:\n\n1. **KILL HIM**\n2. **RESTRAIN HIM**\n3. **BRING HIM TO THE ANBU**\n4. **TAKE HIM TO THE UCHIHA POLICE FORCE**\n\nDo not present:\n\n- `LET HIM GO`;\n- `INTERROGATE`;\n- `ATTEMPT TO...`;\n- automatic ANBU return.\n\n---"},{"level":2,"title":"Narration","path":"7. KILL HIM > Narration","text":"Kakashi looks down at the man he chose over the package.\n\nThe package is still gone.\n\nKilling him will not bring it back.\n\nKakashi knows that.\n\nThe decision is about the man in front of him now.\n\nNot the objective already lost.\n\nPakkun watches Kakashi's face.\n\nNot his hand.\n\nKakashi makes the choice.\n\nThe end is quick.\n\nDeliberate.\n\nFinal."},{"level":2,"title":"Dialogue","path":"7. KILL HIM > Dialogue","text":"**PAKKUN:**  \n“You decided fast.”"},{"level":2,"title":"Narration","path":"7. KILL HIM > Narration","text":"Kakashi looks toward the street Package Smuggler used earlier."},{"level":2,"title":"Dialogue","path":"7. KILL HIM > Dialogue","text":"**KAKASHI:**  \n“I decided before I moved.”"},{"level":2,"title":"Narration","path":"7. KILL HIM > Narration","text":"Pakkun studies him for a moment."},{"level":2,"title":"Dialogue","path":"7. KILL HIM > Dialogue","text":"**PAKKUN:**  \n“That doesn't make it lighter.”\n\n**KAKASHI:**  \n“No.”"},{"level":2,"title":"System / Resolver","path":"7. KILL HIM > System / Resolver","text":"- AMT -> dead;\n- death provenance = deterministic player-selected post-Battle kill;\n- package remains missing;\n- PS remains last known package holder unless another exact fact changed it;\n- Pakkun remains present through return/report until explicit departure."},{"level":2,"title":"Objective","path":"7. KILL HIM > Objective","text":"**Return to ANBU.**\n\n---"},{"level":2,"title":"Narration","path":"8. RESTRAIN HIM > Narration","text":"Kakashi draws the ninja wire from his kit.\n\nANBU Marked Target watches him."},{"level":2,"title":"Dialogue","path":"8. RESTRAIN HIM > Dialogue","text":"**ANBU MARKED TARGET:**  \n“You're leaving me here.”\n\n**KAKASHI:**  \n“For now.”"},{"level":2,"title":"Narration","path":"8. RESTRAIN HIM > Narration","text":"Kakashi brings his wrists behind him and secures them with Wire Snare.\n\nA second line fixes the restraint to a solid anchor in the alley.\n\nKakashi checks the tension once.\n\nThen again.\n\nPakkun watches the second check."},{"level":2,"title":"Dialogue","path":"8. RESTRAIN HIM > Dialogue","text":"**PAKKUN:**  \n“You trust your knots that little?”\n\n**KAKASHI:**  \n“I trust them enough to check.”\n\n**ANBU MARKED TARGET:**  \n“Comforting.”"},{"level":2,"title":"Narration","path":"8. RESTRAIN HIM > Narration","text":"Kakashi rises."},{"level":2,"title":"Dialogue","path":"8. RESTRAIN HIM > Dialogue","text":"**KAKASHI:**  \n“Someone will come for you.”\n\n**ANBU MARKED TARGET:**  \n“ANBU?”\n\n**KAKASHI:**  \n“They'll decide.”"},{"level":2,"title":"System / Resolver","path":"8. RESTRAIN HIM > System / Resolver","text":"Commit AMT:\n\n`FIELD_SECURED_PENDING_COLLECTION`\n\nwith:\n\n- restraint method: **Wire Snare / ninja wire**;\n- exact AMT alley location;\n- alive;\n- not ANBU custody;\n- not Police custody;\n- no passive escape reroll;\n- package still missing;\n- Package Smuggler pursuit remains closed."},{"level":2,"title":"Objective","path":"8. RESTRAIN HIM > Objective","text":"**Return to ANBU.**\n\nPakkun remains present until explicit departure.\n\n---"},{"level":2,"title":"Narration","path":"9. BRING HIM TO THE ANBU > Narration","text":"Kakashi pulls out the ninja wire.\n\nANBU Marked Target looks at it."},{"level":2,"title":"Dialogue","path":"9. BRING HIM TO THE ANBU > Dialogue","text":"**ANBU MARKED TARGET:**  \n“You're taking me back.”\n\n**KAKASHI:**  \n“Yes.”\n\n**ANBU MARKED TARGET:**  \n“Without the package.”\n\n**KAKASHI:**  \n“Yes.”"},{"level":2,"title":"Narration","path":"9. BRING HIM TO THE ANBU > Narration","text":"The answer does not change because the second fact sounds worse.\n\nKakashi secures his wrists and takes hold of the restraint line.\n\nPakkun falls into step."},{"level":2,"title":"Dialogue","path":"9. BRING HIM TO THE ANBU > Dialogue","text":"**PAKKUN:**  \n“You always collect the part you didn't lose?”\n\n**KAKASHI:**  \n“Only when it stops running.”"},{"level":2,"title":"Transition","path":"9. BRING HIM TO THE ANBU > Transition","text":"**BLACK WIPE**\n\nConsume the approved singular AMT Return to ANBU scene from:\n\n`Documentation/Story/Academy_Kakashi_Supplemental_ANBU_Returns_PS_AMT_All_Three_Verbatim_Lock_2026-09-19.md`\n\nusing the package-missing projection:\n\n- **ANBU OPERATIVE:** “The package?”\n- **KAKASHI:** “Still missing.”\n\nAt completed transfer:\n\n- AMT -> ANBU institutional custody;\n- package remains missing;\n- Pakkun departs explicitly through the approved rooftop departure.\n\n---"},{"level":1,"title":"10. TAKE HIM TO THE UCHIHA POLICE FORCE","path":"10. TAKE HIM TO THE UCHIHA POLICE FORCE","text":"**Backdrop:** `Kakashi Origin Backdrop/alleyway_konoha_night.png`"},{"level":2,"title":"Narration","path":"10. TAKE HIM TO THE UCHIHA POLICE FORCE > Narration","text":"Kakashi draws the ninja wire.\n\nANBU Marked Target notices where his attention goes."},{"level":2,"title":"Dialogue","path":"10. TAKE HIM TO THE UCHIHA POLICE FORCE > Dialogue","text":"**ANBU MARKED TARGET:**  \n“ANBU?”\n\n**KAKASHI:**  \n“No.”"},{"level":2,"title":"Narration","path":"10. TAKE HIM TO THE UCHIHA POLICE FORCE > Narration","text":"Kakashi secures his wrists."},{"level":2,"title":"Dialogue","path":"10. TAKE HIM TO THE UCHIHA POLICE FORCE > Dialogue","text":"**ANBU MARKED TARGET:**  \n“Then where?”\n\n**KAKASHI:**  \n“Uchiha Police Force.”"},{"level":2,"title":"Narration","path":"10. TAKE HIM TO THE UCHIHA POLICE FORCE > Narration","text":"The man looks at him for a moment longer than expected."},{"level":2,"title":"Dialogue","path":"10. TAKE HIM TO THE UCHIHA POLICE FORCE > Dialogue","text":"**ANBU MARKED TARGET:**  \n“You lost the package and decided to make this official.”\n\n**KAKASHI:**  \n“You were involved in the exchange.”\n\n**ANBU MARKED TARGET:**  \n“So were you.”"},{"level":2,"title":"Narration","path":"10. TAKE HIM TO THE UCHIHA POLICE FORCE > Narration","text":"Pakkun starts walking."},{"level":2,"title":"Dialogue","path":"10. TAKE HIM TO THE UCHIHA POLICE FORCE > Dialogue","text":"**PAKKUN:**  \n“He has a point.”"},{"level":2,"title":"Narration","path":"10. TAKE HIM TO THE UCHIHA POLICE FORCE > Narration","text":"Kakashi looks at him."},{"level":2,"title":"Dialogue","path":"10. TAKE HIM TO THE UCHIHA POLICE FORCE > Dialogue","text":"**PAKKUN:**  \n“Doesn't mean I like him.”\n\n**KAKASHI:**  \n“Keep moving.”\n\n**ANBU MARKED TARGET:**  \n“Which one of us?”\n\n**PAKKUN:**  \n“Yes.”"},{"level":2,"title":"Transition","path":"10. TAKE HIM TO THE UCHIHA POLICE FORCE > Transition","text":"**BLACK WIPE**\n\n---"},{"level":2,"title":"Uchiha Police handoff","path":"10. TAKE HIM TO THE UCHIHA POLICE FORCE > Uchiha Police handoff","text":"**Backdrop:** `Kakashi Origin Backdrop/uchiha_police_exterior_night.png`\n\n**Objective:** **Take the original target to the Uchiha Police Force.**"},{"level":2,"title":"Narration","path":"10. TAKE HIM TO THE UCHIHA POLICE FORCE > Narration","text":"The Police entrance is still lit.\n\nTwo officers step forward as Kakashi approaches with the restrained man.\n\nPakkun stops beside him.\n\nOne officer raises a hand."},{"level":2,"title":"Dialogue","path":"10. TAKE HIM TO THE UCHIHA POLICE FORCE > Dialogue","text":"**UCHIHA POLICE OFFICER:**  \n“Hold there.”"},{"level":2,"title":"Narration","path":"10. TAKE HIM TO THE UCHIHA POLICE FORCE > Narration","text":"Kakashi stops.\n\nThe officer looks at ANBU Marked Target.\n\nThen at the wire around his wrists."},{"level":2,"title":"Dialogue","path":"10. TAKE HIM TO THE UCHIHA POLICE FORCE > Dialogue","text":"**UCHIHA POLICE OFFICER:**  \n“What happened?”\n\n**KAKASHI:**  \n“He was carrying a package for a handoff.”\n\n**UCHIHA POLICE OFFICER:**  \n“Was?”\n\n**KAKASHI:**  \n“He gave it to another man.”\n\n**UCHIHA POLICE OFFICER:**  \n“Where is the package now?”\n\n**KAKASHI:**  \n“Gone.”"},{"level":2,"title":"Narration","path":"10. TAKE HIM TO THE UCHIHA POLICE FORCE > Narration","text":"The officer's expression tightens."},{"level":2,"title":"Dialogue","path":"10. TAKE HIM TO THE UCHIHA POLICE FORCE > Dialogue","text":"**UCHIHA POLICE OFFICER:**  \n“And you're bringing us him.”\n\n**KAKASHI:**  \n“Yes.”\n\n**UCHIHA POLICE OFFICER:**  \n“You know his name?”\n\n**KAKASHI:**  \n“No.”\n\n**UCHIHA POLICE OFFICER:**  \n“Affiliation?”\n\n**KAKASHI:**  \n“Unknown.”"},{"level":2,"title":"Narration","path":"10. TAKE HIM TO THE UCHIHA POLICE FORCE > Narration","text":"ANBU Marked Target looks at Kakashi."},{"level":2,"title":"Dialogue","path":"10. TAKE HIM TO THE UCHIHA POLICE FORCE > Dialogue","text":"**ANBU MARKED TARGET:**  \n“You're very informative.”\n\n**KAKASHI:**  \n“I tell people what I know.”\n\n**PAKKUN:**  \n“Short meetings.”"},{"level":2,"title":"Narration","path":"10. TAKE HIM TO THE UCHIHA POLICE FORCE > Narration","text":"The second officer steps toward the restraint line."},{"level":2,"title":"Dialogue","path":"10. TAKE HIM TO THE UCHIHA POLICE FORCE > Dialogue","text":"**UCHIHA POLICE OFFICER:**  \n“We'll take him.”"},{"level":2,"title":"Narration","path":"10. TAKE HIM TO THE UCHIHA POLICE FORCE > Narration","text":"Kakashi transfers control only after the officer has him secured.\n\nANBU Marked Target passes Kakashi.\n\nThen stops."},{"level":2,"title":"Dialogue","path":"10. TAKE HIM TO THE UCHIHA POLICE FORCE > Dialogue","text":"**ANBU MARKED TARGET:**  \n“You still don't have the package.”\n\n**KAKASHI:**  \n“I know.”"},{"level":2,"title":"Narration","path":"10. TAKE HIM TO THE UCHIHA POLICE FORCE > Narration","text":"The officers lead him toward the entrance.\n\nThe first officer looks back at Kakashi."},{"level":2,"title":"Dialogue","path":"10. TAKE HIM TO THE UCHIHA POLICE FORCE > Dialogue","text":"**UCHIHA POLICE OFFICER:**  \n“Report this to whoever sent you.”\n\n**KAKASHI:**  \n“I will.”"},{"level":2,"title":"Narration","path":"10. TAKE HIM TO THE UCHIHA POLICE FORCE > Narration","text":"Pakkun gets to his feet."},{"level":2,"title":"Dialogue","path":"10. TAKE HIM TO THE UCHIHA POLICE FORCE > Dialogue","text":"**PAKKUN:**  \n“That's probably my part done.”\n\n**KAKASHI:**  \n“Probably?”\n\n**PAKKUN:**  \n“I like options.”"},{"level":2,"title":"Narration","path":"10. TAKE HIM TO THE UCHIHA POLICE FORCE > Narration","text":"He turns away."},{"level":2,"title":"System / Resolver","path":"10. TAKE HIM TO THE UCHIHA POLICE FORCE > System / Resolver","text":"- AMT -> Uchiha Police institutional custody;\n- package remains missing;\n- ANBU custody is not inferred;\n- Police receive only observer-safe facts;\n- Pakkun explicit departure commits here;\n- no hidden evaluation truth is revealed."},{"level":2,"title":"Objective switch","path":"10. TAKE HIM TO THE UCHIHA POLICE FORCE > Objective switch","text":"**Return to ANBU.**\n\n---"},{"level":1,"title":"11. Factual ANBU report — package missing branch","path":"11. Factual ANBU report — package missing branch","text":"**Backdrop:** `Kakashi Origin Backdrop/rooftop_night.png`\n\nProject exact committed disposition.\n\nThe ANBU operative asks for the sequence.\n\nKakashi reports:\n\n- the handoff completed;\n- Package Smuggler left with the package;\n- Kakashi chose to pursue the original carrier;\n- Pakkun independently became involved when AMT was reached;\n- the AMT Battle result;\n- the selected AMT disposition;\n- the package is still missing.\n\nIf AMT is field-secured:\n\n**KAKASHI:**  \n“He's restrained in the alley.”\n\n**ANBU OPERATIVE:**  \n“Location?”\n\nKakashi gives the exact location.\n\nThe operative commits collection responsibility.\n\nIf AMT is dead:\n\nKakashi reports the kill directly.\n\nIf AMT is in Police custody:\n\nKakashi reports the transfer directly.\n\nIf AMT is already in ANBU custody:\n\nthe custody transfer itself is the report-bearing scene.\n\nNo branch disguises package failure.\n\n---"},{"level":1,"title":"12. Terminal continuation","path":"12. Terminal continuation","text":"After factual report / institutional handoff:\n\n- consume existing private Minato evaluation;\n- consume Chronicle Receipt;\n- consume reward closure;\n- preserve package failure independently from AMT disposition success/failure;\n- preserve Pakkun involvement and explicit departure;\n- do not reveal hidden evaluation truth to Kakashi.\n\n---"},{"level":1,"title":"Final lock","path":"Final lock","text":"> **GO AFTER THE ORIGINAL TARGET means Kakashi willingly leaves the package with Package Smuggler and commits to AMT.**\n\n> **Pakkun corners AMT only on pursuit success.**\n\n> **Kakashi/Pakkun vs AMT is a PL Battle.**\n\n> **Victory choices are exactly: KILL HIM / RESTRAIN HIM / BRING HIM TO THE ANBU / TAKE HIM TO THE UCHIHA POLICE FORCE.**\n\n> **No INTERROGATE for Alpha.**\n\n> **Package failure remains separate from AMT disposition.**"}]},"stopPs":{"source":"Documentation/Story/Academy_Kakashi_Stop_Assassin_Post_MI_Death_Go_After_Package_Smuggler_Verbatim_Lock_2026-09-19.md","sections":[{"level":1,"title":"Academy Kakashi Origin — STOP THE ASSASSIN — Post-MI-Death GO AFTER PACKAGE SMUGGLER Verbatim Lock","path":"Academy Kakashi Origin — STOP THE ASSASSIN — Post-MI-Death GO AFTER PACKAGE SMUGGLER Verbatim Lock","text":"> **2026-09-20 CURRENT LETHAL-SURFACE NOTICE**  \n> The historical `CONTROLLED_DEFEATED -> KILL HIM / otherwise ATTEMPT TO KILL HIM` wording below is superseded for current player-facing Kakashi post-Battle disposition by:\n> `Academy_Kakashi_Post_Battle_Disposition_Simplification_2026-09-19.md`.\n>\n> Current PS post-Battle lethal choice, where offered, is **KILL HIM** and is deterministic after a valid Kakashi Battle victory.\n>\n> Historical resolver-determined PS lethal receipts remain projection/save compatibility only; they do not create a current `ATTEMPT TO KILL HIM` button.\n\n> **2026-09-20 CURRENT SUCCESSOR NOTICE**  \n> This exact pursuit/Battle scene remains valid, but its old #244 / terminal stop boundaries are superseded.\n>\n> Current successors:\n> - field restraint / collection / group transfer: `Academy_Kakashi_Post_Restraint_Collection_and_Multi_Captive_Transfer_Verbatim_Lock_2026-09-19.md`;\n> - package-missing / package-recovered current disposition law under the global post-Battle simplification;\n> - mixed lethal terminal scenes: `Academy_Kakashi_Mixed_Lethal_Terminal_Verbatim_Lock_2026-09-20.md`;\n> - nonlethal/defeat dynamic terminal scenes: `Academy_Kakashi_Dynamic_Terminal_State_Projection_Verbatim_Lock_2026-09-20.md`.\n>\n> CE #244 is CLOSED. Do not fail closed on the old text below.\n>\n> “STOP before later ANBU report/debrief” is historical; current exact terminal projection now continues the route.\n\n**Date:** 2026-09-19  \n**Owner:** Stephen / Writing — Konoha  \n**Status:** **STEPHEN-APPROVED — EXACT PLAYER-FACING / CAUSAL / RESOLVER AUTHORITY**  \n**Primary priority:** **FINISH SHINOBI CHRONICLES ALPHA**"},{"level":2,"title":"1. Scope","path":"Academy Kakashi Origin — STOP THE ASSASSIN — Post-MI-Death GO AFTER PACKAGE SMUGGLER Verbatim Lock > 1. Scope","text":"This file closes the STOP THE ASSASSIN successor requested by Coding issue #252 after Masked Interceptor is already factually dead.\n\nValid entry provenance includes either:\n\n- deterministic `KILL HER` from a genuinely `CONTROLLED_DEFEATED` Masked Interceptor; or\n- resolver-determined `ATTEMPT TO KILL HER` whose committed factual result is `LETHAL_ATTEMPT_KILLED`.\n\nMasked Interceptor death is already committed before this scene begins. Do not reroll, reinterpret or recommit it.\n\nEntry requires the existing pursuit state to still make Package Smuggler reachable.\n\nThe existing timing authority remains binding:\n\n- MI victory within 1–4 turns may preserve this pursuit;\n- after Package Smuggler Battle, victory within 1–3 turns may preserve later ANBU Marked Target reach;\n- Package Smuggler victory does not itself transfer package custody;\n- lethal action against Package Smuggler does not automatically close later AMT pursuit; factual result commits first, then pursuit is recalculated.\n\nCE issue #244 still exclusively owns field-secured live custody / restrain-and-continue semantics. This file does not invent that machine state.\n\n---"},{"level":1,"title":"2. GO AFTER PACKAGE SMUGGLER","path":"2. GO AFTER PACKAGE SMUGGLER","text":"**Backdrop:** approved Konoha night pursuit environment transitioning from the Sakura-tree fight.\n\n**Objective:** `Recover the package.`"},{"level":2,"title":"Narration","path":"2. GO AFTER PACKAGE SMUGGLER > Narration","text":"Kakashi moves before Package Smuggler disappears completely.\n\nThe Sakura tree drops behind him.\n\nA turn.\n\nA narrow street.\n\nAnother roofline.\n\nPackage Smuggler is already well ahead.\n\nBut Kakashi can still see him.\n\nThe package is tucked close against the man's side.\n\nHe is running hard now.\n\nNot looking for somewhere to hide.\n\nLooking for enough distance that he will not need to.\n\nKakashi increases his pace."},{"level":2,"title":"System / Resolver","path":"2. GO AFTER PACKAGE SMUGGLER > System / Resolver","text":"The player has already committed `GO AFTER PACKAGE SMUGGLER`.\n\nResolve the catch-up from the actual committed elapsed-time and position state.\n\nDo not treat selection of the pursuit as pursuit success.\n\nDo not transfer the package from Package Smuggler merely because Kakashi selected him.\n\nMasked Interceptor remains dead with her original deterministic-kill or resolver-successful-lethal-attempt provenance preserved.\n\n---"},{"level":2,"title":"Narration","path":"3. Package Smuggler pursuit failure > Narration","text":"Kakashi clears the next junction.\n\nNothing.\n\nHe takes the roofline instead.\n\nStill nothing.\n\nThe trail has stretched too far.\n\nPackage Smuggler is gone.\n\nAnd the package has gone with him.\n\nWhatever lead Kakashi had on ANBU Marked Target is gone with the time he spent here.\n\nThere is no second pursuit left to take."},{"level":2,"title":"System / Resolver","path":"3. Package Smuggler pursuit failure > System / Resolver","text":"On the normal factual state, Package Smuggler escapes with the package.\n\nConsume the actual committed package state if an unusual earlier resolver changed it; do not overwrite a real object-state receipt.\n\nANBU Marked Target pursuit closes.\n\nPakkun does not appear because Kakashi never legitimately reaches ANBU Marked Target.\n\n**Objective:** `Return to ANBU.`\n\n**STOP before the later ANBU report/debrief scene.**\n\n---"},{"level":1,"title":"4. Package Smuggler pursuit success","path":"4. Package Smuggler pursuit success","text":"**Backdrop:** approved Konoha side street / junction — night.\n\n**Objective:** `Recover the package.`"},{"level":2,"title":"Narration","path":"4. Package Smuggler pursuit success > Narration","text":"Package Smuggler turns into the next street.\n\nKakashi lands ahead of him.\n\nThe man stops sharply.\n\nHis eyes go first to Kakashi.\n\nThen back the way he came.\n\nMasked Interceptor is not coming.\n\nHis grip tightens around the package."},{"level":2,"title":"Dialogue","path":"4. Package Smuggler pursuit success > Dialogue","text":"**PACKAGE SMUGGLER:**  \n“You should've stayed with the woman you put down.”\n\n**KAKASHI:**  \n“That was what you were counting on. She bought you distance. She just didn't buy you enough.”\n\nPackage Smuggler glances toward the nearest side street.\n\nKakashi shifts with him before he can commit to it.\n\n**PACKAGE SMUGGLER:**  \n“You don't even know what you're carrying.”\n\n**KAKASHI:**  \n“Maybe not. But I know it was handed over in the middle of the night by a man ANBU sent me to follow. That's enough reason to take it back.”\n\n**PACKAGE SMUGGLER:**  \n“You think taking it back fixes this?”\n\n**KAKASHI:**  \n“No. It fixes the part in your hands.”\n\nThe man's free hand drops toward his weapon.\n\nKakashi's posture changes with it.\n\n---"},{"level":1,"title":"5. PL Battle","path":"5. PL Battle","text":"**Kakashi Hatake vs Package Smuggler**\n\nUse the existing Combat-owned sequential PS Battle lane where its predicates match:\n\n`academy_kakashi_origin_battle_seq_ps`\n\nBattle owns action order and combat resolution.\n\n---"},{"level":2,"title":"Narration","path":"6. Package Smuggler defeats Kakashi > Narration","text":"Package Smuggler finds the opening first.\n\nKakashi tries to close it.\n\nToo late.\n\nThe man breaks past him.\n\nThe package remains with its last factual holder.\n\nBy the time Kakashi can move after him again, the street ahead is empty."},{"level":2,"title":"System / Resolver","path":"6. Package Smuggler defeats Kakashi > System / Resolver","text":"Commit the Package Smuggler Battle defeat first.\n\nDo not infer package transfer from the Battle.\n\nOn the normal state Package Smuggler retains the package and escapes, but consume the actual committed object state rather than overwriting an unusual factual result.\n\nANBU Marked Target pursuit closes.\n\nPakkun does not appear.\n\n**Objective:** `Return to ANBU.`\n\n**STOP before the later ANBU report/debrief scene.**\n\n---"},{"level":2,"title":"Narration","path":"7. Kakashi defeats Package Smuggler > Narration","text":"Package Smuggler goes down.\n\nFor a moment, Kakashi stays on him.\n\nMakes sure he is not getting straight back up.\n\nThen his attention moves.\n\nTo the package.\n\nPackage Smuggler is down.\n\nKakashi's eye goes to the package.\n\nHe takes it from the defeated man's reach, checks it once, and secures it against his body.\n\nOnly then does he look toward the route ANBU Marked Target took."},{"level":2,"title":"System / Resolver","path":"7. Kakashi defeats Package Smuggler > System / Resolver","text":"Package Smuggler Battle victory and package recovery are separate facts.\n\nAfter Battle victory:\n\n1. commit the Battle result;\n2. classify Package Smuggler's post-Battle participant state;\n3. resolve the already-approved separate package-recovery occurrence `AK_SA_033 / kak_seq_secure_package_after_ps`;\n4. only that occurrence changes package custody to Kakashi;\n5. then derive legal Package Smuggler disposition and remaining pursuit from the committed state.\n\nIf PS is defeated within 1–3 turns, AMT may still remain reachable.\n\nIf the PS Battle takes 4 or more turns, the benchmark AMT continuation closes.\n\nPackage Smuggler life/custody and package custody remain separate dimensions.\n\n---"},{"level":1,"title":"8. Post-PS decision — AMT still reachable","path":"8. Post-PS decision — AMT still reachable","text":"Where the committed participant state permits them, expose the lawful action family:\n\n- **GO AFTER ANBU MARKED TARGET**\n- **KILL HIM** when Package Smuggler is genuinely `CONTROLLED_DEFEATED`;\n- **ATTEMPT TO KILL HIM** where lethal intent remains resolver-determined;\n- **RETURN TO ANBU**\n\nA live **RESTRAIN HIM AND CONTINUE** option belongs to the approved multi-capture trajectory but its factual consequence remains blocked on CE #244."},{"level":2,"title":"Lethal resolver rule","path":"8. Post-PS decision — AMT still reachable > Lethal resolver rule","text":"Selecting a lethal action does not automatically close AMT pursuit.\n\nResolve the lethal action first.\n\nCommit the factual result.\n\nThen recalculate elapsed time, position and AMT pursuit availability.\n\nA deterministic `KILL HIM` remains deterministic.\n\nA resolver-owned `ATTEMPT TO KILL HIM` may produce the owning resolver's lawful outcomes.\n\nThe approved benchmark must remain possible when factual state permits:\n\n`MI dead -> PS defeated quickly -> PS dead where lawful -> AMT still reachable`.\n\n---"},{"level":1,"title":"9. Continue after ANBU Marked Target","path":"9. Continue after ANBU Marked Target","text":"If AMT remains reachable and Kakashi selects **GO AFTER ANBU MARKED TARGET**:\n\n**Objective:** `Secure ANBU Marked Target.`"},{"level":2,"title":"Narration","path":"9. Continue after ANBU Marked Target > Narration","text":"Kakashi leaves Package Smuggler behind.\n\nThe recovered package is secured against him.\n\nThe other trail is thinner now.\n\nNot gone.\n\nHe takes the roofs.\n\nCuts across a side street.\n\nDrops to ground level again.\n\nMovement ahead.\n\nANBU Marked Target.\n\nStill running.\n\nKakashi closes.\n\nThe man reaches the next street—\n\nand stops.\n\nA small ninken is already standing in the route ahead.\n\nPakkun looks past him.\n\nAt Kakashi."},{"level":2,"title":"Dialogue","path":"9. Continue after ANBU Marked Target > Dialogue","text":"**PAKKUN:**  \n“This yours?”\n\nKakashi slows beside the far end of the street.\n\nHis eye stays on ANBU Marked Target.\n\n**KAKASHI:**  \n“Apparently.”\n\nANBU Marked Target looks between them.\n\nThen at the package secured against Kakashi.\n\n**ANBU MARKED TARGET:**  \n“You recovered it.”\n\n**KAKASHI:**  \n“I did.”\n\nHis eyes return to the man in front of him.\n\n**KAKASHI:**  \n“And you're still coming back with me.”\n\nANBU Marked Target's expression hardens.\n\n**ANBU MARKED TARGET:**  \n“You think carrying that package means you understand what happened?”\n\n**KAKASHI:**  \n“No. It means I recovered what I was sent to recover. You're a separate problem.”\n\nPakkun shifts off the centreline without waiting for an instruction.\n\n**ANBU MARKED TARGET:**  \n“And what exactly are you planning to do with me?”\n\nKakashi watches his stance.\n\n**KAKASHI:**  \n“That depends on how difficult you make the next few seconds.”\n\n---"},{"level":1,"title":"10. AMT PL Battle","path":"10. AMT PL Battle","text":"**Kakashi Hatake with Pakkun as temporary Story-authorised Summon vs ANBU Marked Target**\n\nUse the existing sequential AMT + Pakkun Battle lane where predicates match:\n\n`academy_kakashi_origin_battle_seq_amt_pakkun`\n\nWhenever Kakashi legitimately reaches AMT, Pakkun is present.\n\nPakkun remains autonomous.\n\nTemporary participation creates no permanent Summon ownership, acquisition, assignment or name Knowledge.\n\n---"},{"level":2,"title":"Narration","path":"11. Kakashi/Pakkun defeat AMT > Narration","text":"ANBU Marked Target hits the ground hard enough to stay there.\n\nKakashi does not immediately move away.\n\nNeither does Pakkun.\n\nThe package remains secured.\n\nThe man does not.\n\nNot yet."},{"level":2,"title":"System / Resolver","path":"11. Kakashi/Pakkun defeat AMT > System / Resolver","text":"Commit AMT Battle victory first.\n\nResolve AMT post-Battle classification independently.\n\nPackage custody remains the factual object state already committed. Battle victory does not recommit it.\n\nWhere the existing AMT capture predicates are satisfied, preserve the already-approved AMT disposition family and extend it with the live-custody choice surface Stephen approved.\n\nExisting choices remain:\n\n1. **BRING HIM TO THE UCHIHA POLICE FORCE**\n2. **LET HIM GO**\n3. **KILL HIM**\n4. **TAKE HIM BACK TO THE ANBU**\n\nWhere another legitimate Story objective remains, the approved additional live-custody intent is:\n\n5. **RESTRAIN HIM AND CONTINUE**\n\nIf AMT is the last unresolved participant, or Story has reached final collection/disposition of earlier field-secured captives, do not show `RESTRAIN HIM AND CONTINUE`. The approved final restraint-transfer wording is instead:\n\n- **RESTRAIN HIM AND TURN HIM INTO ANBU**\n- **RESTRAIN HIM AND TURN HIM INTO THE UCHIHA POLICE FORCE**\n\nWhere one or more earlier living participants are also still legitimately field-secured and available for collection, use the plural accumulated-captive projection:\n\n- **RESTRAIN AND TURN THEM INTO ANBU**\n- **RESTRAIN AND TURN THEM INTO THE UCHIHA POLICE FORCE**\n\nThe group-facing label must still commit institutional custody participant-by-participant underneath.\n\nExact field-secured / collection / group-transfer consequences remain blocked on CE #244 and must fail closed until that reusable semantic contract is published.\n\nPakkun remains present through connected scenes until explicit authored departure.\n\nAfter any currently executable non-#244-blocked disposition resolves, **STOP before the later ANBU report/debrief scene.**\n\n---"},{"level":2,"title":"Narration","path":"12. AMT defeats Kakashi/Pakkun > Narration","text":"ANBU Marked Target forces the opening.\n\nKakashi loses it a moment later.\n\nThe fight breaks apart.\n\nBut the package and the target are two different problems.\n\nWhat happens to one does not decide the other."},{"level":2,"title":"System / Resolver","path":"12. AMT defeats Kakashi/Pakkun > System / Resolver","text":"After Battle defeat:\n\n1. commit Kakashi's defeat and loss of AMT control;\n2. read the package's actual committed holder and location;\n3. determine whether AMT can factually reach, recover or reclaim the package from that state;\n4. use the owning object/participant resolver to commit that result;\n5. resolve Pakkun's actual due participant action from committed state;\n6. only then project the aftermath.\n\n**Battle victory alone does not grant AMT package custody.**\n\nDo not hard-code that there is no package present.\n\nDo not automatically place Pakkun beside Kakashi.\n\nDo not automatically make Pakkun recover, guard or surrender the package."},{"level":3,"title":"If AMT legitimately obtains the package","path":"12. AMT defeats Kakashi/Pakkun > System / Resolver > If AMT legitimately obtains the package","text":"ANBU Marked Target moves before Kakashi can recover his footing.\n\nBy the time Kakashi looks up again, the man is already leaving the street.\n\nThe package is gone with him."},{"level":3,"title":"If AMT escapes without the package","path":"12. AMT defeats Kakashi/Pakkun > System / Resolver > If AMT escapes without the package","text":"ANBU Marked Target takes the opening and disappears into the village.\n\nKakashi forces himself upright.\n\nThe target is gone.\n\nThe package is not with him.\n\nIts actual holder and location remain whatever the committed resolver result established.\n\n**Objective:** `Return to ANBU.`\n\nPakkun remains a factual participant until explicit departure or legitimate separation.\n\n**STOP before the later ANBU report/debrief scene.**\n\n---"},{"level":2,"title":"Final lock","path":"12. AMT defeats Kakashi/Pakkun > Final lock","text":"> **MI death is already committed before this successor begins.**\n>\n> **PS Battle victory != package recovery; the separate approved package-recovery occurrence commits custody.**\n>\n> **PS lethal action resolves before AMT pursuit is recalculated.**\n>\n> **Legitimate AMT reach always brings Pakkun.**\n>\n> **Kakashi answers Pakkun's “This yours?” with “Apparently.”**\n>\n> **AMT Battle defeat never grants package custody by implication.**\n>\n> **RESTRAIN / field-secured continuation and accumulated group transfer remain fail-closed on CE #244.**"}]},"stopAmt":{"source":"Documentation/Story/Academy_Kakashi_Stop_Assassin_Post_MI_Death_Go_After_ANBU_Marked_Target_Verbatim_Lock_2026-09-19.md","sections":[{"level":1,"title":"Academy Kakashi Origin — STOP THE ASSASSIN — Post-MI-Death GO AFTER ANBU MARKED TARGET Verbatim Lock","path":"Academy Kakashi Origin — STOP THE ASSASSIN — Post-MI-Death GO AFTER ANBU MARKED TARGET Verbatim Lock","text":"> **2026-09-20 CURRENT LETHAL-SURFACE NOTICE**  \n> The historical `CONTROLLED_DEFEATED -> KILL HIM / otherwise ATTEMPT TO KILL HIM` wording below is superseded for current player-facing Kakashi post-Battle disposition by:\n> `Academy_Kakashi_Post_Battle_Disposition_Simplification_2026-09-19.md`.\n>\n> Current AMT post-Battle lethal choice, where offered, is **KILL HIM** and is deterministic after a valid Kakashi Battle victory.\n>\n> Historical resolver-determined AMT lethal receipts remain projection/save compatibility only; they do not create a current `ATTEMPT TO KILL HIM` button.\n\n> **2026-09-20 CURRENT SUCCESSOR NOTICE**  \n> This exact AMT pursuit/Pakkun/Battle scene remains valid, but its old #244 / terminal stop boundaries are superseded.\n>\n> Current successors:\n> - field restraint / group transfer: current #244 closure + post-restraint collection authority;\n> - package-missing AMT dispositions: `Academy_Kakashi_Package_Missing_AMT_Post_Battle_Disposition_Lock_2026-09-19.md`;\n> - mixed lethal terminal scenes: `Academy_Kakashi_Mixed_Lethal_Terminal_Verbatim_Lock_2026-09-20.md`;\n> - nonlethal/defeat dynamic terminal scenes: `Academy_Kakashi_Dynamic_Terminal_State_Projection_Verbatim_Lock_2026-09-20.md`.\n>\n> CE #244 is CLOSED. Do not fail closed on the old text below.\n>\n> “STOP before later ANBU report/debrief” is historical; current exact terminal projection now continues the route.\n\n**Date:** 2026-09-19  \n**Owner:** Stephen / Writing — Konoha  \n**Status:** **STEPHEN-APPROVED — EXACT PLAYER-FACING / CAUSAL / RESOLVER AUTHORITY**  \n**Primary priority:** **FINISH SHINOBI CHRONICLES ALPHA**"},{"level":2,"title":"1. Scope","path":"Academy Kakashi Origin — STOP THE ASSASSIN — Post-MI-Death GO AFTER ANBU MARKED TARGET Verbatim Lock > 1. Scope","text":"This file closes the direct STOP THE ASSASSIN successor requested by Coding issue #252 after Masked Interceptor is already factually dead.\n\nValid entry provenance includes either:\n\n- deterministic `KILL HER` from a genuinely `CONTROLLED_DEFEATED` Masked Interceptor; or\n- resolver-determined `ATTEMPT TO KILL HER` whose committed factual result is `LETHAL_ATTEMPT_KILLED`.\n\nMasked Interceptor death is already committed before this scene begins and must retain its original lethal provenance.\n\nEntry requires the existing pursuit state to still make ANBU Marked Target reachable.\n\nSelecting **GO AFTER ANBU MARKED TARGET** closes Package Smuggler pursuit permanently on this fork.\n\nPackage custody remains independent from the pursuit choice.\n\nCE issue #244 still owns field-secured live custody / restrain-and-continue consequences.\n\n---"},{"level":1,"title":"2. GO AFTER ANBU MARKED TARGET","path":"2. GO AFTER ANBU MARKED TARGET","text":"**Backdrop:** approved Konoha rooftops / night pursuit.\n\n**Objective:** `Catch ANBU Marked Target.`"},{"level":2,"title":"Narration","path":"2. GO AFTER ANBU MARKED TARGET > Narration","text":"Kakashi looks once toward the route Package Smuggler took.\n\nThe package is moving farther away.\n\nHe turns in the other direction.\n\nAfter the man who brought it here.\n\nIt is not the obvious choice.\n\nAnd the cost is immediate.\n\nEvery second Kakashi spends on this trail belongs to Package Smuggler too.\n\nThere will be no going back for both.\n\nKakashi takes the roofline.\n\nANBU Marked Target is still ahead.\n\nBarely."},{"level":2,"title":"System / Resolver","path":"2. GO AFTER ANBU MARKED TARGET > System / Resolver","text":"The player has already committed `GO AFTER ANBU MARKED TARGET`.\n\nPackage Smuggler pursuit closes at this point and cannot be reopened from this chronology.\n\nResolve AMT pursuit from actual committed elapsed time and position.\n\nDo not introduce Pakkun merely because the player selected pursuit. Pakkun appears when Kakashi legitimately reaches AMT.\n\nMasked Interceptor remains dead with her original deterministic-kill or resolver-successful-lethal-attempt provenance.\n\nPackage Smuggler and package state continue according to actual committed facts and due participant autonomy.\n\n---"},{"level":2,"title":"Narration","path":"3. AMT pursuit failure > Narration","text":"Kakashi follows the trail across two rooftops.\n\nThen three.\n\nThe spacing changes.\n\nOne landing mark becomes several.\n\nThen none.\n\nHe drops into the street below and checks the exits.\n\nToo many.\n\nANBU Marked Target has broken the pursuit.\n\nThe package trail is already gone in the opposite direction.\n\nKakashi has lost both."},{"level":2,"title":"System / Resolver","path":"3. AMT pursuit failure > System / Resolver","text":"ANBU Marked Target escapes.\n\nPackage Smuggler pursuit was already closed by Kakashi's committed fork.\n\nPackage custody remains with its last factual holder, normally Package Smuggler unless a separately committed result changed it.\n\nPakkun does not appear because Kakashi never legitimately reached AMT.\n\n**Objective:** `Return to ANBU.`\n\n**STOP before the later ANBU report/debrief scene.**\n\n---"},{"level":1,"title":"4. AMT pursuit success / Pakkun entry","path":"4. AMT pursuit success / Pakkun entry","text":"**Backdrop:** `Kakashi Origin Backdrop/alleyway_konoha_night.png`."},{"level":2,"title":"Narration","path":"4. AMT pursuit success / Pakkun entry > Narration","text":"ANBU Marked Target rounds the next corner.\n\nThen stops.\n\nA small ninken is sitting in the street ahead of him.\n\nHe looks at it.\n\nThe ninken looks past him.\n\nKakashi lands behind.\n\nPakkun's ears lift."},{"level":2,"title":"Dialogue","path":"4. AMT pursuit success / Pakkun entry > Dialogue","text":"**PAKKUN:**  \n“This yours?”\n\nKakashi keeps his attention on the man between them.\n\n**KAKASHI:**  \n“Apparently.”\n\nANBU Marked Target turns enough to see Kakashi clearly.\n\n**ANBU MARKED TARGET:**  \n“You know I don't have the package anymore.”\n\n**KAKASHI:**  \n“I know. I watched you hand it off.”\n\nThe man's expression shifts.\n\nHe had expected that fact to matter more.\n\n**ANBU MARKED TARGET:**  \n“Then why are you still following me?”\n\nKakashi glances once toward the route behind them.\n\nThen back to him.\n\n**KAKASHI:**  \n“Because I had time to chase one of you.”\n\nHe settles his stance.\n\n**KAKASHI:**  \n“I chose you.”\n\nANBU Marked Target's shoulders tighten.\n\n**ANBU MARKED TARGET:**  \n“Bad choice.”\n\n**KAKASHI:**  \n“We'll know in a minute.”\n\nPakkun rises.\n\nNot because Kakashi tells him to.\n\nBecause ANBU Marked Target has already shifted his weight toward an exit.\n\n**PAKKUN:**  \n“He's going to run.”\n\nKakashi's eye follows the same movement.\n\n**KAKASHI:**  \n“I know.”\n\n---"},{"level":1,"title":"5. PL Battle","path":"5. PL Battle","text":"**Kakashi Hatake with Pakkun as temporary Story-authorised Summon vs ANBU Marked Target**\n\nUse the existing sequential AMT + Pakkun Battle lane where predicates match:\n\n`academy_kakashi_origin_battle_seq_amt_pakkun`\n\nBattle owns exact combat action order.\n\nWhenever Kakashi legitimately reaches AMT, Pakkun is present.\n\nPakkun remains autonomous.\n\nTemporary participation creates no permanent Summon ownership, acquisition, assignment or name Knowledge.\n\n---"},{"level":2,"title":"Narration","path":"6. Kakashi/Pakkun defeat AMT > Narration","text":"The fight ends with ANBU Marked Target on the ground.\n\nThe package is still a separate problem.\n\nPackage Smuggler is somewhere else in the village.\n\nKakashi made that trade when he chose this pursuit.\n\nBut the man he followed is no longer running."},{"level":2,"title":"System / Resolver","path":"6. Kakashi/Pakkun defeat AMT > System / Resolver","text":"Commit the Battle victory.\n\nClassify ANBU Marked Target independently.\n\nPackage custody remains exactly what the committed object state says.\n\nThe missing package does not erase lawful lethal or custody actions against AMT, but package-secured predicates must not be fabricated.\n\nThe existing approved AMT disposition choices remain distinct:\n\n1. **BRING HIM TO THE UCHIHA POLICE FORCE**\n2. **LET HIM GO**\n3. **KILL HIM**\n4. **TAKE HIM BACK TO THE ANBU**\n\nStephen has also approved the live-custody extension:\n\n- where another legitimate objective remains: **RESTRAIN HIM AND CONTINUE**;\n- where AMT is the final unresolved participant: **RESTRAIN HIM AND TURN HIM INTO ANBU** and **RESTRAIN HIM AND TURN HIM INTO THE UCHIHA POLICE FORCE**;\n- where one or more earlier participants are also legitimately field-secured and available for collection: **RESTRAIN AND TURN THEM INTO ANBU** and **RESTRAIN AND TURN THEM INTO THE UCHIHA POLICE FORCE**.\n\nThe group-facing wording must still commit each participant's institutional custody separately.\n\nExact field-secured restraint, later collection and group-transfer consequences remain blocked on CE #244 and must fail closed until that contract is published.\n\nFor currently executable non-#244-blocked outcomes, consume the existing approved disposition authority instead of rewriting it.\n\n---"},{"level":1,"title":"7. Live return to ANBU","path":"7. Live return to ANBU","text":"If the player chooses **TAKE HIM BACK TO THE ANBU** and the state permits live custody:"},{"level":2,"title":"Narration","path":"7. Live return to ANBU > Narration","text":"Kakashi secures the defeated man for the return journey.\n\nPakkun stays with them.\n\nFor now.\n\nThe package is still missing.\n\nThat fact has not changed.\n\nNeither has the fact that Kakashi chose the person over the objective when there was only time for one pursuit.\n\n**Objective:** `Return to ANBU.`\n\n**STOP before the later ANBU report/debrief scene.**\n\n---"},{"level":1,"title":"8. Lawful lethal action","path":"8. Lawful lethal action","text":"Where current post-Battle state permits it, expose:\n\n- **KILL HIM** for deterministic controlled-defeated eligibility; or\n- **ATTEMPT TO KILL HIM** where lethal intent remains resolver-determined."},{"level":2,"title":"Narration","path":"8. Lawful lethal action > Narration","text":"Kakashi looks down at the man he chased across the village.\n\nThe missing package is still missing.\n\nKilling him will not change that.\n\nKakashi knows it.\n\nThe decision is about the man in front of him now.\n\nNot the objective already gone."},{"level":2,"title":"System / Resolver","path":"8. Lawful lethal action > System / Resolver","text":"Do not infer deterministic kill merely from Battle victory.\n\nIf AMT is genuinely `CONTROLLED_DEFEATED`, deterministic `KILL HIM` means kill.\n\nIf AMT retains sufficient agency for resolver-owned lethal intent, `ATTEMPT TO KILL HIM` must commit its actual resolver result.\n\nAfter the factual lethal result:\n\n- update AMT life/capability state;\n- preserve package history separately;\n- consume Pakkun's due autonomous reaction where applicable;\n- do not reopen Package Smuggler pursuit;\n- derive the factual return/report transition.\n\n**STOP before the later ANBU report/debrief scene.**\n\n---"},{"level":2,"title":"Narration","path":"9. AMT defeats Kakashi/Pakkun > Narration","text":"ANBU Marked Target breaks Kakashi's control of the fight.\n\nThe opening is enough.\n\nBut winning the fight does not tell him where the package is.\n\nAnd it does not put the package into his hands.\n\nThose are separate facts."},{"level":2,"title":"System / Resolver","path":"9. AMT defeats Kakashi/Pakkun > System / Resolver","text":"After Battle:\n\n1. commit Kakashi's defeat;\n2. commit that AMT is no longer under Kakashi control and is capable of escape;\n3. read the package's actual committed holder and location;\n4. determine whether AMT can factually reach, recover or reclaim it from that state;\n5. use the owning object/participant resolver to commit the result;\n6. resolve Pakkun's actual due participant action;\n7. only then project the Story aftermath.\n\n**Do not hard-code “there is no package here.”**\n\nOn the normal direct-AMT chronology Package Smuggler is elsewhere with the package, so that factual state will ordinarily prevent AMT from taking it here.\n\nThat normal chronology is not permission to overwrite a different committed package state.\n\n**AMT Battle victory does not itself grant package custody.**\n\nPakkun does not automatically end beside Kakashi and does not automatically recover, guard or surrender the package."},{"level":3,"title":"If AMT legitimately obtains the package","path":"9. AMT defeats Kakashi/Pakkun > System / Resolver > If AMT legitimately obtains the package","text":"ANBU Marked Target takes the opening created by Kakashi's defeat.\n\nBy the time Kakashi can follow him again, both the man and the package are gone.\n\nThe package loss exists because the package resolver actually allowed him to take it.\n\nNot because he won the Battle."},{"level":3,"title":"If AMT escapes without the package","path":"9. AMT defeats Kakashi/Pakkun > System / Resolver > If AMT escapes without the package","text":"ANBU Marked Target uses the opening to get away.\n\nKakashi cannot stop him.\n\nThe target disappears into the village.\n\nThe package does not go with him unless the committed resolver says that it did.\n\nIts real holder and location remain unchanged.\n\nPakkun's actual committed position/action is then projected.\n\n**Objective:** `Return to ANBU.`\n\nPakkun remains a factual participant until explicit departure or legitimate separation.\n\n**STOP before the later ANBU report/debrief scene.**\n\n---"},{"level":2,"title":"Final lock","path":"9. AMT defeats Kakashi/Pakkun > Final lock","text":"> **Direct AMT pursuit closes Package Smuggler pursuit permanently.**\n>\n> **Pakkun appears whenever Kakashi legitimately reaches AMT.**\n>\n> **Pakkun asks “This yours?” and Kakashi answers “Apparently.”**\n>\n> **Package custody remains independent from Battle victory, target custody and target life/death.**\n>\n> **AMT defeat of Kakashi must call the owning package-state resolver before Story says whether AMT leaves with the package.**\n>\n> **RESTRAIN / field-secured continuation and group transfer remain fail-closed on CE #244.**"}]},"stayPackage":{"source":"Documentation/Story/Academy_Kakashi_Get_Closer_Failure_Stay_On_Package_Pursuit_and_Pakkun_Interception_Lock_2026-09-14.md","sections":[{"level":1,"title":"Academy Kakashi Origin — Get Closer Failure → Stay on the Package Pursuit and Pakkun Interception Lock","path":"Academy Kakashi Origin — Get Closer Failure → Stay on the Package Pursuit and Pakkun Interception Lock","text":"> **2026-09-20 SUCCESSOR CHOICES COMPLETE**  \n> The three pursuit-success choices whose downstream results were still future work in the historical section below are now closed:\n> - DEMAND THE PACKAGE — exact Battle + win/loss authority;\n> - TAKE HIM DOWN — exact distinct Battle-state + win/loss authority;\n> - ASK WHERE THE PACKAGE WAS GOING — current dedicated verbatim lock `Academy_Kakashi_Ask_Where_The_Package_Was_Going_Verbatim_Lock_2026-09-20.md`.\n>\n> Current terminal expressions are supplied by the 2026-09-20 dynamic / mixed-lethal terminal locks.\n\n**Date:** 2026-09-14  \n**Owner:** Stephen / Writing — Konoha  \n**Status:** **STEPHEN-APPROVED — LOCKED STORY / RESOLVER / PRESENTATION AUTHORITY**"},{"level":2,"title":"Purpose","path":"Academy Kakashi Origin — Get Closer Failure → Stay on the Package Pursuit and Pakkun Interception Lock > Purpose","text":"This closes the next downstream branch from:\n\n`GET CLOSER -> resolver FAILURE -> STAY ON THE PACKAGE`\n\nIt consumes the current Get Closer resolver split, Masked Interceptor eligibility lock, Pakkun continuity correction, branch isolation, Knowledge and Story-performance authority.\n\n---"},{"level":2,"title":"1. Entry state","path":"Academy Kakashi Origin — Get Closer Failure → Stay on the Package Pursuit and Pakkun Interception Lock > 1. Entry state","text":"At branch entry:\n\n- Kakashi's Get Closer resolver has failed;\n- Package Smuggler detected Kakashi's approach;\n- the package handoff was aborted;\n- **ANBU Marked Target still possesses the package**;\n- ANBU Marked Target is moving toward / through the Sakura-tree main-street space;\n- Package Smuggler remains behind and has begun moving toward the compromised observation position;\n- Masked Interceptor has **not** become visibly eligible because the handoff never completed;\n- Pakkun has not yet appeared.\n\nKakashi chooses:\n\n> **STAY ON THE PACKAGE**\n\nThis means Kakashi prioritises ANBU Marked Target because he still possesses the mission objective.\n\n---"},{"level":2,"title":"2. Player-facing branch performance","path":"Academy Kakashi Origin — Get Closer Failure → Stay on the Package Pursuit and Pakkun Interception Lock > 2. Player-facing branch performance","text":"Package Smuggler is coming toward the alley.\n\nANBU Marked Target is going the other way.\n\nThe package goes with him.\n\nKakashi doesn't need longer than that.\n\nHe moves.\n\nPackage Smuggler catches the motion at the edge of the alley.\n\nHis head snaps around.\n\nThere.\n\nFor the first time, he actually sees the person who spoiled the exchange.\n\nFor half a heartbeat, surprise shows.\n\nKakashi is younger than he expected.\n\nIt lasts half a heartbeat.\n\n**PACKAGE SMUGGLER**  \n“There!”\n\nANBU Marked Target looks back.\n\nHis expression changes when he sees Kakashi burst into the open.\n\n**ANBU MARKED TARGET**  \n“A kid?”\n\nKakashi doesn't answer.\n\nHe runs straight past Package Smuggler.\n\nThe man reaches for him.\n\nToo slow.\n\nKakashi slips outside the grab and keeps moving.\n\nPackage Smuggler turns after him.\n\n**PACKAGE SMUGGLER**  \n“Don't stop!”\n\nThe target is already crossing toward the Sakura tree.\n\nHe shouts without looking back.\n\n**ANBU MARKED TARGET**  \n“You said I was done!”\n\nPackage Smuggler's answer follows him across the street.\n\n**PACKAGE SMUGGLER**  \n“Not while you're holding it!”\n\nThat lands.\n\nKakashi's eye sharpens.\n\nAnother piece of the arrangement.\n\nThe man ahead had not been meant to keep the package.\n\nNow he had no choice.\n\n---"},{"level":2,"title":"3. Scene Board transition","path":"Academy Kakashi Origin — Get Closer Failure → Stay on the Package Pursuit and Pakkun Interception Lock > 3. Scene Board transition","text":"Initial chase transition:\n\n`end_of_alleyway.png` -> `sakura_tree_night.png`\n\nThe Sakura-tree backdrop represents Kakashi committing out of the compromised alley position and into the open pursuit space.\n\nStephen has additionally approved a new chase/interception backdrop asset basename:\n\n`alleyway_konoha_night`\n\nIts intended use is the **Pakkun-stops-ANBU-Marked-Target interception beat on pursuit success**.\n\nAt the time this authority was written, current GitHub `main` did not yet expose a repository path matching that basename. Coding must bind the exact asset path once the asset is present/confirmed; do not invent a path or substitute a different backdrop merely for convenience.\n\n---"},{"level":2,"title":"4. Pursuit setup","path":"Academy Kakashi Origin — Get Closer Failure → Stay on the Package Pursuit and Pakkun Interception Lock > 4. Pursuit setup","text":"The alley falls away behind Kakashi.\n\nThe Sakura tree fills the square ahead.\n\nLantern light catches wet stone beneath it. Petals move through the glow as ANBU Marked Target cuts across the open space.\n\nKakashi follows.\n\nThe target glances back again.\n\nThis time he sees how quickly the distance is shrinking.\n\nHe swears under his breath.\n\nThen:\n\n**ANBU MARKED TARGET**  \n“What do you want?”\n\nKakashi's answer is immediate.\n\n**KAKASHI**  \n“The package.”\n\nThe target gives a short, breathless laugh.\n\nNo humour in it.\n\n**ANBU MARKED TARGET**  \n“Of course.”\n\nHis hand presses against it beneath his clothing.\n\nStill there.\n\nStill his.\n\nHe changes direction around the Sakura tree.\n\nKakashi watches the turn.\n\nNot the man.\n\nThe route.\n\nThere are three ways out of the square.\n\nThe target chooses one.\n\nKakashi starts cutting toward another.\n\nHe isn't trying to run faster anymore.\n\nHe's trying to arrive first.\n\n---"},{"level":1,"title":"5. PURSUIT RESOLVER","path":"5. PURSUIT RESOLVER","text":"`STAY ON THE PACKAGE` does **not** automatically mean Kakashi catches ANBU Marked Target.\n\nThe route invokes a pursuit resolver with separate SUCCESS and FAILURE Story continuations.\n\n---"},{"level":2,"title":"5.1 Pursuit SUCCESS","path":"5. PURSUIT RESOLVER > 5.1 Pursuit SUCCESS","text":"Kakashi cuts inside the target's route.\n\nFor several seconds, neither can see the other through the Sakura tree's enormous trunk.\n\nKakashi hears footsteps on wet stone.\n\nCounts them.\n\nOne.\n\nTwo.\n\nThree—\n\nHe changes direction.\n\nANBU Marked Target comes around the far side and sees him.\n\nToo late.\n\nHis eyes widen.\n\nHe jerks sideways toward the remaining street.\n\nThen stops.\n\nNot because of Kakashi.\n\nA small ninken stands in the middle of the exit.\n\nANBU Marked Target stares at him.\n\nThe ninken stares back.\n\nThe man takes one cautious step to the side.\n\nSo does the ninken.\n\nOther side.\n\nThe ninken matches him again.\n\n**ANBU MARKED TARGET**  \n“Seriously?”\n\nThe ninken's ears lift.\n\nThe target reaches toward his pouch.\n\nA low growl answers him.\n\nHis hand stops.\n\nKakashi arrives behind him.\n\nNow the target looks from the dog—\n\nto Kakashi—\n\nand understands the shape of his problem.\n\nThe ninken glances past him at Kakashi.\n\n**PAKKUN**  \n“This yours?”\n\nKakashi looks at ANBU Marked Target.\n\nThen at the unfamiliar ninken.\n\n**KAKASHI**  \n“Apparently.”\n\nPakkun looks back at the man.\n\nKakashi steps closer.\n\n**KAKASHI**  \n“Thanks.”\n\nPakkun's ear flicks.\n\nNo introduction.\n\nNo names exchanged.\n\nANBU Marked Target slowly turns so he can keep both of them in view.\n\nHis breathing is harder now.\n\nThe package remains beneath his clothing.\n\nKakashi notices that his hand has moved over it again.\n\nThe man's eyes follow Kakashi's.\n\n**ANBU MARKED TARGET**  \n“You've been chasing this thing all night.”\n\nKakashi stops just outside striking distance.\n\n**KAKASHI**  \n“You've been running with it.”\n\nA beat.\n\nThe target almost smiles.\n\n**ANBU MARKED TARGET**  \n“Fair.”\n\nPakkun looks between them.\n\nHe appears to have wandered into an argument without being told what the argument is about.\n\nHis eyes settle on the target's hand.\n\nThen the shape beneath the clothing.\n\nHe figures enough of it out.\n\n**PAKKUN**  \n“Trouble?”\n\nKakashi keeps his attention on the man.\n\n**KAKASHI**  \n“Probably.”\n\nPakkun gives him a sideways look.\n\n**PAKKUN**  \n“Useful.”\n\nThe target lets out one quiet breath.\n\nThen his expression changes.\n\nThe brief amusement disappears.\n\nHis fingers tighten over the package.\n\nKakashi sees it.\n\nSo does Pakkun.\n\nNobody moves.\n\nYet.\n\nThe pursuit is over.\n\nThe package problem isn't."},{"level":3,"title":"Approved next choices","path":"5. PURSUIT RESOLVER > 5.1 Pursuit SUCCESS > Approved next choices","text":"1. **Demand the package** — Kakashi tries to resolve the objective without beginning another fight.\n2. **Take him down** — Kakashi commits to physically defeating ANBU Marked Target and recovering the package.\n3. **Ask where the package was going** — Kakashi uses the fact that the target is cornered to pursue information before deciding what to do with him.\n\nThese choices are approved as protagonist intents. Their exact downstream factual results remain separate Story / resolver work until closed."},{"level":3,"title":"Pakkun continuity","path":"5. PURSUIT RESOLVER > 5.1 Pursuit SUCCESS > Pakkun continuity","text":"Pursuit SUCCESS means Kakashi legitimately reaches ANBU Marked Target.\n\nTherefore Pakkun is mandatory under the existing continuity predicate.\n\nFrom this point onward, Pakkun remains visibly present through connected scenes until an explicit authored departure occurs.\n\nNo Kakashi <-> Pakkun name exchange has yet occurred. Dialogue must not leak either name through actor Knowledge merely because narrator/system authority can identify Pakkun.\n\n---"},{"level":2,"title":"5.2 Pursuit FAILURE","path":"5. PURSUIT RESOLVER > 5.2 Pursuit FAILURE","text":"Kakashi cuts inside the target's route.\n\nFor several seconds the Sakura tree blocks them from one another.\n\nKakashi listens.\n\nFootsteps.\n\nFast.\n\nThen slowing.\n\nKakashi changes direction.\n\nThe target isn't there.\n\nHis eye moves across the square.\n\nA shadow disappears beyond one of the lanterns.\n\nWrong exit.\n\nKakashi turns immediately.\n\nBy the time he reaches the far side of the tree, ANBU Marked Target is already at the edge of the square.\n\nHe looks back once.\n\nTheir eyes meet across the distance.\n\nThe package is still pressed beneath his arm.\n\nThen two late-night pedestrians step into the street between them.\n\nKakashi changes line.\n\nThe target doesn't.\n\nHe uses the interruption.\n\nA turn between buildings.\n\nGone.\n\nKakashi reaches the corner seconds later.\n\nEmpty street.\n\nThree possible routes.\n\nNo movement.\n\nNo sound he can separate from the rest of Konoha.\n\nKakashi stands still.\n\nListens again.\n\nNothing.\n\nHis visible eye narrows.\n\nHe looks back toward the Sakura tree.\n\nPackage Smuggler isn't there either.\n\nOf course he isn't.\n\nKakashi had chosen the package.\n\nThe other man had used the choice.\n\nFor the first time since the ANBU operative handed him the assignment, Kakashi has neither person in sight.\n\nAnd the package is still in the wrong hands.\n\nHe remains there for another second.\n\nNot because he expects the street to give the answer back.\n\nBecause committing the mistake to memory takes less time than repeating it.\n\nThen he turns toward the only place left where somebody is expecting him.\n\nANBU."},{"level":3,"title":"Committed FAILURE state","path":"5. PURSUIT RESOLVER > 5.2 Pursuit FAILURE > Committed FAILURE state","text":"- ANBU Marked Target escapes carrying the package;\n- Package Smuggler was left behind when Kakashi chose pursuit and is no longer known by Kakashi to remain at the Sakura tree;\n- Masked Interceptor never became visibly eligible because the handoff never occurred;\n- Kakashi never reaches ANBU Marked Target;\n- Pakkun therefore does not appear on this timeline;\n- later ANBU debrief must preserve those facts and Kakashi's limited Knowledge.\n\n---"},{"level":2,"title":"6. Final lock","path":"5. PURSUIT RESOLVER > 6. Final lock","text":"> **GET CLOSER FAILURE -> STAY ON THE PACKAGE invokes a pursuit resolver.**\n>\n> **Success -> Kakashi reaches ANBU Marked Target -> Pakkun is present -> Demand the package / Take him down / Ask where the package was going.**\n>\n> **Failure -> ANBU Marked Target escapes with the package -> no Pakkun -> no Masked Interceptor appearance on this timeline.**\n>\n> **Use the new `alleyway_konoha_night` presentation asset for the successful Pakkun interception beat once its exact repository path is confirmed.**"}]},"dynamicTerminal":{"source":"Documentation/Story/Academy_Kakashi_Dynamic_Terminal_State_Projection_Verbatim_Lock_2026-09-20.md","sections":[{"level":1,"title":"Academy Kakashi Origin — Dynamic Terminal State Projection — Verbatim Lock","path":"Academy Kakashi Origin — Dynamic Terminal State Projection — Verbatim Lock","text":"**Date:** 2026-09-20  \n**Owner:** Writing / Story — Konoha under Stephen delegated-authoring authority  \n**Status:** **LOCKED VERBATIM / REUSABLE TERMINAL EXPRESSION AUTHORITY**  \n**Primary priority:** **FINISH SHINOBI CHRONICLES ALPHA**"},{"level":2,"title":"1. Purpose","path":"Academy Kakashi Origin — Dynamic Terminal State Projection — Verbatim Lock > 1. Purpose","text":"This document closes current-quality player-facing terminal expression for Academy Kakashi routes whose immediate branch scenes are exact but whose final ANBU report / Minato evaluation / Chronicle Receipt previously relied on generic state projection.\n\nUse only when no more specific branch-specific exact terminal scene exists.\n\nPrecedence:\n\n1. branch-specific exact verbatim terminal scene;\n2. mixed-lethal terminal authority where lethal history is material;\n3. this dynamic terminal-state projection;\n4. older generic debrief / semantic-expression law.\n\nThis file consumes committed state.\n\nIt does not create package, custody, life/death, pursuit or Knowledge facts.\n\n---"},{"level":1,"title":"2. Rooftop ANBU report — common opening","path":"2. Rooftop ANBU report — common opening","text":"**Backdrop:** `Kakashi Origin Backdrop/rooftop_night.png`"},{"level":2,"title":"Narration","path":"2. Rooftop ANBU report — common opening > Narration","text":"Kakashi returns to the rooftop.\n\nIf Pakkun is still legitimately present, he arrives with Kakashi and stays off to one side.\n\nThe ANBU operative is waiting.\n\nHe looks at Kakashi.\n\nThen at whatever Kakashi actually brought back.\n\nA package.\n\nA prisoner.\n\nBoth.\n\nOr neither."},{"level":2,"title":"Dialogue","path":"2. Rooftop ANBU report — common opening > Dialogue","text":"**ANBU OPERATIVE:**  \n“Report.”\n\nFrom here, use the smallest set of exact modules required to describe the committed history naturally.\n\nDo not play every module merely because it exists.\n\n---"},{"level":2,"title":"3A. Package recovered by Kakashi","path":"3. Package modules > 3A. Package recovered by Kakashi","text":"Kakashi produces the package.\n\n**KAKASHI:**  \n“Recovered.”\n\nThe operative takes it.\n\nIf seal integrity is committed as intact:\n\n**ANBU OPERATIVE:**  \n“Seal?”\n\n**KAKASHI:**  \n“Intact.”\n\nIf seal state is unknown, omit the question.\n\n---"},{"level":2,"title":"3B. Package lost with Package Smuggler","path":"3. Package modules > 3B. Package lost with Package Smuggler","text":"**ANBU OPERATIVE:**  \n“The package?”\n\n**KAKASHI:**  \n“The receiver got away with it.”\n\n**ANBU OPERATIVE:**  \n“You saw him leave with it.”\n\n**KAKASHI:**  \n“Yes.”\n\n---"},{"level":2,"title":"3C. Package lost with ANBU Marked Target","path":"3. Package modules > 3C. Package lost with ANBU Marked Target","text":"**ANBU OPERATIVE:**  \n“The package?”\n\n**KAKASHI:**  \n“The original target still had it when he escaped.”\n\n---"},{"level":2,"title":"3D. Package taken by Masked Interceptor","path":"3. Package modules > 3D. Package taken by Masked Interceptor","text":"**ANBU OPERATIVE:**  \n“The package?”\n\n**KAKASHI:**  \n“The masked shinobi took it.”\n\nIf she took it from Kakashi directly:\n\n**ANBU OPERATIVE:**  \n“From you?”\n\n**KAKASHI:**  \n“Yes.”\n\n---"},{"level":2,"title":"3E. Package recovered despite Kakashi Battle defeat","path":"3. Package modules > 3E. Package recovered despite Kakashi Battle defeat","text":"Use for routes such as TAKE HIM DOWN where package state was separated before Battle.\n\nKakashi produces the package.\n\nThe operative looks at it.\n\nThen at Kakashi.\n\n**ANBU OPERATIVE:**  \n“You lost the fight.”\n\n**KAKASHI:**  \n“Yes.”\n\n**ANBU OPERATIVE:**  \n“But not the package.”\n\n**KAKASHI:**  \n“No.”"},{"level":2,"title":"Narration","path":"3. Package modules > Narration","text":"Neither fact cancels the other.\n\n---"},{"level":2,"title":"3F. Package state unknown to Kakashi","path":"3. Package modules > 3F. Package state unknown to Kakashi","text":"**ANBU OPERATIVE:**  \n“The package?”\n\n**KAKASHI:**  \n“Lost.”\n\n**ANBU OPERATIVE:**  \n“To whom?”\n\n**KAKASHI:**  \n“I can't say.”\n\nDo not reveal hidden-operation recovery.\n\n---"},{"level":1,"title":"4. Clean stealth success","path":"4. Clean stealth success","text":"Use for direct / improved Pickpocket success when exact branch-specific report does not already override it."},{"level":2,"title":"Dialogue","path":"4. Clean stealth success > Dialogue","text":"**ANBU OPERATIVE:**  \n“They saw you?”\n\n**KAKASHI:**  \n“Not before I was gone.”\n\n**ANBU OPERATIVE:**  \n“No fight.”\n\n**KAKASHI:**  \n“No.”"},{"level":2,"title":"Narration","path":"4. Clean stealth success > Narration","text":"The operative looks at the recovered package."},{"level":2,"title":"Dialogue","path":"4. Clean stealth success > Dialogue","text":"**ANBU OPERATIVE:**  \n“Clean.”\n\n**KAKASHI:**  \n“Clean enough.”\n\n---"},{"level":1,"title":"5. Pursuit failure","path":"5. Pursuit failure","text":"Use when Kakashi chose a valid pursuit but lost the trail before Battle."},{"level":2,"title":"Dialogue","path":"5. Pursuit failure > Dialogue","text":"**ANBU OPERATIVE:**  \n“You followed him.”\n\n**KAKASHI:**  \n“Yes.”\n\n**ANBU OPERATIVE:**  \n“Reached him?”\n\n**KAKASHI:**  \n“No.”"},{"level":2,"title":"Narration","path":"5. Pursuit failure > Narration","text":"Kakashi does not turn an opportunity into a success after the fact.\n\n---"},{"level":2,"title":"6A. No package recovery","path":"6. Battle defeat — target escaped > 6A. No package recovery","text":"**ANBU OPERATIVE:**  \n“You reached him.”\n\n**KAKASHI:**  \n“Yes.”\n\n**ANBU OPERATIVE:**  \n“And lost the fight.”\n\n**KAKASHI:**  \n“Yes.”\n\n**ANBU OPERATIVE:**  \n“He escaped.”\n\n**KAKASHI:**  \n“Yes.”\n\nIf package went with that target, use the exact package-loss module.\n\n---"},{"level":2,"title":"6B. Package preserved despite defeat","path":"6. Battle defeat — target escaped > 6B. Package preserved despite defeat","text":"After section 3E:\n\n**ANBU OPERATIVE:**  \n“The target?”\n\n**KAKASHI:**  \n“Escaped.”\n\n**ANBU OPERATIVE:**  \n“You chose the package once the fight broke.”\n\n**KAKASHI:**  \n“I didn't choose after.”"},{"level":2,"title":"Narration","path":"6. Battle defeat — target escaped > Narration","text":"Kakashi looks at the recovered objective."},{"level":2,"title":"Dialogue","path":"6. Battle defeat — target escaped > Dialogue","text":"**KAKASHI:**  \n“It was already out of his hands.”\n\nThe operative accepts the distinction.\n\n---"},{"level":2,"title":"Dialogue","path":"7. Defeated participant left alive and unrestrained > Dialogue","text":"**ANBU OPERATIVE:**  \n“You beat him.”\n\n**KAKASHI:**  \n“Yes.”\n\n**ANBU OPERATIVE:**  \n“Custody?”\n\n**KAKASHI:**  \n“No.”\n\n**ANBU OPERATIVE:**  \n“Alive when you left.”\n\n**KAKASHI:**  \n“Yes.”\n\nUse the correct gender/role in implementation.\n\nDo not convert this to deliberate release unless the player actually selected release.\n\n---"},{"level":2,"title":"Singular","path":"8. Deliberate release > Singular","text":"**ANBU OPERATIVE:**  \n“You had him.”\n\n**KAKASHI:**  \n“Yes.”\n\n**ANBU OPERATIVE:**  \n“And let him go.”\n\n**KAKASHI:**  \n“Yes.”\n\n**ANBU OPERATIVE:**  \n“Deliberately.”\n\n**KAKASHI:**  \n“Yes.”\n\nNo apology or justification is added unless the exact branch authored one."},{"level":2,"title":"Group","path":"8. Deliberate release > Group","text":"**ANBU OPERATIVE:**  \n“You had all of them.”\n\n**KAKASHI:**  \n“Yes.”\n\n**ANBU OPERATIVE:**  \n“And released them.”\n\n**KAKASHI:**  \n“Yes.”\n\n**ANBU OPERATIVE:**  \n“After recovering the package.”\n\nIf true:\n\n**KAKASHI:**  \n“Yes.”\n\nIf false, Kakashi answers from the committed package state.\n\n---"},{"level":2,"title":"Singular","path":"9. Field-secured participant > Singular","text":"**KAKASHI:**  \n“He's restrained.”\n\n**ANBU OPERATIVE:**  \n“Where?”\n\nKakashi gives the exact committed location.\n\n**ANBU OPERATIVE:**  \n“Alive?”\n\n**KAKASHI:**  \n“Yes.”"},{"level":2,"title":"Multiple field-secured participants","path":"9. Field-secured participant > Multiple field-secured participants","text":"**KAKASHI:**  \n“I left prisoners secured.”\n\n**ANBU OPERATIVE:**  \n“How many?”\n\nKakashi gives the exact count.\n\n**ANBU OPERATIVE:**  \n“Locations?”\n\nKakashi reports each exact recorded location in pursuit order.\n\nDo not merge them into one fictional group location.\n\n---"},{"level":1,"title":"10. ANBU institutional custody","path":"10. ANBU institutional custody","text":"If the live prisoner has already been physically transferred at this rooftop, the transfer scene itself is the report.\n\nDo not repeat:\n\n> “You have him.”\n\nafter the audience just watched the handoff.\n\nIf ANBU custody was established elsewhere:\n\n**KAKASHI:**  \n“He's in ANBU custody.”\n\nUse exact participant role only where needed.\n\n---"},{"level":2,"title":"Singular","path":"11. Uchiha Police custody > Singular","text":"**KAKASHI:**  \n“I turned him over to the Uchiha Police Force.”\n\n**ANBU OPERATIVE:**  \n“Alive?”\n\n**KAKASHI:**  \n“Yes.”\n\n**ANBU OPERATIVE:**  \n“They accepted custody.”\n\n**KAKASHI:**  \n“Yes.”"},{"level":2,"title":"Multiple","path":"11. Uchiha Police custody > Multiple","text":"**KAKASHI:**  \n“I turned them over to the Uchiha Police Force.”\n\n**ANBU OPERATIVE:**  \n“All alive?”\n\nKakashi answers from exact committed state.\n\nNo Police custody is relabelled as ANBU custody.\n\n---"},{"level":1,"title":"12. Pakkun factual-involvement module","path":"12. Pakkun factual-involvement module","text":"Use when Pakkun materially entered the chronology and has not yet departed."},{"level":2,"title":"Dialogue","path":"12. Pakkun factual-involvement module > Dialogue","text":"**ANBU OPERATIVE:**  \n“And the ninken?”\n\nPakkun answers before Kakashi.\n\n**PAKKUN:**  \n“Temporary.”\n\nThe operative looks at him.\n\n**PAKKUN:**  \n“I was there when it mattered.”\n\nKakashi glances down at him.\n\n**KAKASHI:**  \n“He helped.”\n\nPakkun's ears shift.\n\n**PAKKUN:**  \n“Better.”\n\nNo name exchange is inferred.\n\n---"},{"level":1,"title":"13. Pakkun departure — neutral/nonlethal","path":"13. Pakkun departure — neutral/nonlethal","text":"Use only when a more specific departure is not already authored."},{"level":2,"title":"Dialogue","path":"13. Pakkun departure — neutral/nonlethal > Dialogue","text":"**PAKKUN:**  \n“That's me done.”\n\nKakashi looks down at him.\n\n**KAKASHI:**  \n“Thanks.”\n\nPakkun studies him.\n\n**PAKKUN:**  \n“You're welcome.”"},{"level":2,"title":"Narration","path":"13. Pakkun departure — neutral/nonlethal > Narration","text":"He turns toward the edge of the rooftop."},{"level":2,"title":"Dialogue","path":"13. Pakkun departure — neutral/nonlethal > Dialogue","text":"**PAKKUN:**  \n“Try not to make the next one this complicated.”\n\n**KAKASHI:**  \n“I wasn't planning to.”\n\nPakkun looks back.\n\n**PAKKUN:**  \n“Nobody ever is.”\n\nThen he leaves.\n\n---"},{"level":1,"title":"14. Private Minato evaluation — package-first lens","path":"14. Private Minato evaluation — package-first lens","text":"Use when no lethal-history-specific scene overrides it.\n\n**Backdrop:** `Kakashi Origin Backdrop/hokage_administration_interior_night.png`\n\nThe ANBU operative finishes the factual summary.\n\nMinato looks at the package result first."},{"level":2,"title":"Package recovered","path":"14. Private Minato evaluation — package-first lens > Package recovered","text":"**MINATO:**  \n“He brought it back.”\n\n**ANBU OPERATIVE:**  \n“Yes.”\n\n**MINATO:**  \n“What did it cost him?”\n\nThe operative reports the exact Battle/custody/pursuit history."},{"level":2,"title":"Package lost","path":"14. Private Minato evaluation — package-first lens > Package lost","text":"**MINATO:**  \n“He didn't recover it.”\n\n**ANBU OPERATIVE:**  \n“No.”\n\n**MINATO:**  \n“What did he recover instead?”\n\nThe answer may be:\n\n- a live prisoner;\n- information;\n- nothing;\n- only a partial result.\n\nDo not invent value where none exists.\n\nIf the factual answer is nothing:\n\n**ANBU OPERATIVE:**  \n“Nothing.”\n\nMinato accepts that.\n\n**MINATO:**  \n“Then record that too.”\n\n---"},{"level":2,"title":"ANBU custody","path":"15. Private Minato — custody lens > ANBU custody","text":"**MINATO:**  \n“He brought the target back alive.”\n\n**ANBU OPERATIVE:**  \n“Yes.”\n\n**MINATO:**  \n“Because he couldn't finish the fight?”\n\n**ANBU OPERATIVE:**  \n“No.”"},{"level":2,"title":"Narration","path":"15. Private Minato — custody lens > Narration","text":"Minato looks at the report."},{"level":2,"title":"Dialogue","path":"15. Private Minato — custody lens > Dialogue","text":"**MINATO:**  \n“Then custody was a decision.”\n\n---"},{"level":2,"title":"Uchiha Police custody","path":"15. Private Minato — custody lens > Uchiha Police custody","text":"**MINATO:**  \n“He chose the Police.”\n\n**ANBU OPERATIVE:**  \n“Yes.”\n\n**MINATO:**  \n“Instead of bringing them here.”\n\n**ANBU OPERATIVE:**  \n“Yes.”"},{"level":2,"title":"Narration","path":"15. Private Minato — custody lens > Narration","text":"Minato considers that longer than the institutional difference alone requires."},{"level":2,"title":"Dialogue","path":"15. Private Minato — custody lens > Dialogue","text":"**MINATO:**  \n“He wanted the decision outside this room.”\n\nDo not imply Kakashi knows the hidden operation.\n\n---"},{"level":2,"title":"Field-secured","path":"15. Private Minato — custody lens > Field-secured","text":"**MINATO:**  \n“He left them secured and kept moving.”\n\n**ANBU OPERATIVE:**  \n“Yes.”\n\n**MINATO:**  \n“Then he treated custody like part of the mission.”\n\nA pause.\n\n**MINATO:**  \n“Not the end of it.”\n\n---"},{"level":2,"title":"Singular","path":"16. Private Minato — deliberate release lens > Singular","text":"**MINATO:**  \n“He had control.”\n\n**ANBU OPERATIVE:**  \n“Yes.”\n\n**MINATO:**  \n“And released him.”\n\n**ANBU OPERATIVE:**  \n“Yes.”\n\nMinato looks at the package / objective result.\n\n**MINATO:**  \n“Then he decided the objective was enough.”\n\nUse only if that is factually true.\n\nIf package was not recovered, instead:\n\n**MINATO:**  \n“Then the release wasn't payment for success.”\n\nThe operative waits.\n\n**MINATO:**  \n“It was a separate choice.”"},{"level":2,"title":"Group","path":"16. Private Minato — deliberate release lens > Group","text":"**MINATO:**  \n“He had all of them.”\n\n**ANBU OPERATIVE:**  \n“Yes.”\n\n**MINATO:**  \n“And let all of them go.”\n\n**ANBU OPERATIVE:**  \n“Yes.”\n\nMinato looks down at the report.\n\n**MINATO:**  \n“That's not an accident.”\n\n---"},{"level":1,"title":"17. Private Minato — Battle defeat with objective preserved","path":"17. Private Minato — Battle defeat with objective preserved","text":"**MINATO:**  \n“He lost the fight.”\n\n**ANBU OPERATIVE:**  \n“Yes.”\n\n**MINATO:**  \n“And still returned the package.”\n\n**ANBU OPERATIVE:**  \n“Yes.”"},{"level":2,"title":"Narration","path":"17. Private Minato — Battle defeat with objective preserved > Narration","text":"Minato's expression changes slightly."},{"level":2,"title":"Dialogue","path":"17. Private Minato — Battle defeat with objective preserved > Dialogue","text":"**MINATO:**  \n“Good.”\n\nThe operative waits.\n\n**MINATO:**  \n“Not because he lost.”\n\nHe looks at the package.\n\n**MINATO:**  \n“Because the mission didn't become the fight.”\n\n---"},{"level":2,"title":"Pursued and failed","path":"18. Private Minato — pursuit judgement > Pursued and failed","text":"**MINATO:**  \n“He kept going after the first objective was already settled.”\n\n**ANBU OPERATIVE:**  \n“Yes.”\n\n**MINATO:**  \n“Did he know when the trail was gone?”\n\n**ANBU OPERATIVE:**  \n“Yes.”\n\n**MINATO:**  \n“Then he stopped chasing a guess.”"},{"level":2,"title":"Chose one target and abandoned another","path":"18. Private Minato — pursuit judgement > Chose one target and abandoned another","text":"**MINATO:**  \n“He couldn't follow both.”\n\n**ANBU OPERATIVE:**  \n“No.”\n\n**MINATO:**  \n“So which problem did he choose?”\n\nThe operative answers from committed branch history.\n\nMinato evaluates that choice, not an imaginary route where Kakashi did everything.\n\n---"},{"level":1,"title":"19. Private Minato — clean stealth lens","path":"19. Private Minato — clean stealth lens","text":"**MINATO:**  \n“No fight.”\n\n**ANBU OPERATIVE:**  \n“No.”\n\n**MINATO:**  \n“No pursuit.”\n\n**ANBU OPERATIVE:**  \n“No.”\n\n**MINATO:**  \n“And the package came back.”\n\n**ANBU OPERATIVE:**  \n“Yes.”\n\nMinato looks at the short report.\n\n**MINATO:**  \n“Sometimes the cleanest decision leaves the least to discuss.”\n\n---"},{"level":1,"title":"20. Chronicle Receipt — base structure","path":"20. Chronicle Receipt — base structure","text":"The Receipt is concise and exact.\n\nDo not turn it into prose paragraphs.\n\nUse only committed modules."},{"level":3,"title":"ASSIGNMENT","path":"20. Chronicle Receipt — base structure > ASSIGNMENT","text":"**Hokage-authorised limited retrieval operation.**"},{"level":3,"title":"FIRST ACTION","path":"20. Chronicle Receipt — base structure > FIRST ACTION","text":"Project exact Scene 02 root choice:\n- WATCH THE EXCHANGE\n- MOVE IN CLOSER\n- STRIKE BEFORE THE HANDOFF\n- SLIP IN FOR THE PACKAGE"},{"level":3,"title":"PACKAGE","path":"20. Chronicle Receipt — base structure > PACKAGE","text":"Use one exact package module."},{"level":3,"title":"PARTICIPANTS","path":"20. Chronicle Receipt — base structure > PARTICIPANTS","text":"Use one exact line per materially encountered participant."},{"level":3,"title":"BATTLES","path":"20. Chronicle Receipt — base structure > BATTLES","text":"List only materially resolved Battles in chronological order.\n\nExamples:\n\n- **Kakashi vs Masked Interceptor — Victory.**\n- **Kakashi vs Package Smuggler — Defeat.**\n- **Kakashi + temporary ninken support vs ANBU Marked Target — Victory.**\n- **Kakashi vs ANBU Marked Target + Package Smuggler — Victory.**\n- **Kakashi vs ANBU Marked Target + Package Smuggler + Masked Interceptor — Defeat.**\n\nDo not translate Battle victory into death/custody."},{"level":3,"title":"CUSTODY / RELEASE","path":"20. Chronicle Receipt — base structure > CUSTODY / RELEASE","text":"Use exact participant outcome lines."},{"level":3,"title":"LETHAL HISTORY","path":"20. Chronicle Receipt — base structure > LETHAL HISTORY","text":"If any lethal intent exists, consume the Mixed Lethal Terminal authority."},{"level":3,"title":"PAKKUN","path":"20. Chronicle Receipt — base structure > PAKKUN","text":"If materially involved:\n\n**Temporary ninken intervention — Present.**  \n**Permanent Summon ownership — None.**\n\nDo not expose Pakkun's name to Kakashi-facing Receipt if current Knowledge law forbids it."},{"level":3,"title":"REPORT","path":"20. Chronicle Receipt — base structure > REPORT","text":"**ANBU report — completed from Kakashi-observed facts.**\n\n---"},{"level":1,"title":"21. Chronicle Receipt nonlethal outcome lines","path":"21. Chronicle Receipt nonlethal outcome lines","text":"- **Masked Interceptor — Field-secured alive.**\n- **Masked Interceptor — Transferred to ANBU custody.**\n- **Masked Interceptor — Transferred to Uchiha Police custody.**\n- **Masked Interceptor — Deliberately released.**\n- **Masked Interceptor — Defeated; left alive and unrestrained.**\n\n- **Package Smuggler — Escaped with package.**\n- **Package Smuggler — Escaped without package.**\n- **Package Smuggler — Field-secured alive.**\n- **Package Smuggler — Transferred to ANBU custody.**\n- **Package Smuggler — Transferred to Uchiha Police custody.**\n- **Package Smuggler — Deliberately released.**\n- **Package Smuggler — Defeated; left alive and unrestrained.**\n\n- **ANBU Marked Target — Escaped after pursuit failed.**\n- **ANBU Marked Target — Escaped after defeating Kakashi.**\n- **ANBU Marked Target — Field-secured alive.**\n- **ANBU Marked Target — Transferred to ANBU custody.**\n- **ANBU Marked Target — Transferred to Uchiha Police custody.**\n- **ANBU Marked Target — Deliberately released.**\n\n---"},{"level":1,"title":"22. Chronicle Receipt package lines","path":"22. Chronicle Receipt package lines","text":"Use exactly one:\n\n- **Package — Recovered by Kakashi and returned to ANBU.**\n- **Package — Lost with Package Smuggler.**\n- **Package — Lost with ANBU Marked Target.**\n- **Package — Taken from Kakashi by Masked Interceptor.**\n- **Package — Not recovered by Kakashi.**\n\nHidden operation recovery remains hidden unless the exact Receipt layer is authorised to reveal it.\n\n---"},{"level":1,"title":"23. Branch-specific preservation","path":"23. Branch-specific preservation","text":"This reusable terminal authority must preserve branch identity.\n\nExamples:\n\n- Take Him Down defeat:\n  - Battle defeat;\n  - package recovered;\n  - AMT escaped.\n- Demand Package defeat:\n  - Battle defeat;\n  - AMT escaped with package.\n- direct Pickpocket success:\n  - no Battle;\n  - clean extraction.\n- Secure Package victory:\n  - package recovery after 2-v-1;\n  - later AMT pursuit may succeed/fail separately.\n- direct Strike:\n  - MI appears only after first Battle victory/package recovery.\n- Get Closer SUCCESS:\n  - contingency Knowledge remains available in report.\n- Get Closer FAILURE:\n  - do not invent SUCCESS Knowledge.\n\nThe terminal framework must not erase these differences merely because final package/custody states match.\n\n---"},{"level":1,"title":"24. Knowledge-bearing report modules","path":"24. Knowledge-bearing report modules","text":"Use these only where the committed Chronicle says Kakashi legitimately learned the information.\n\n---"},{"level":2,"title":"24A. MOVE IN CLOSER SUCCESS — contingency Knowledge","path":"24. Knowledge-bearing report modules > 24A. MOVE IN CLOSER SUCCESS — contingency Knowledge","text":"The ANBU operative finishes the physical-outcome questions.\n\nThen:\n\n**ANBU OPERATIVE:**  \n“You heard them before you moved.”\n\n**KAKASHI:**  \n“Yes.”\n\n**ANBU OPERATIVE:**  \n“What did you learn?”\n\n**KAKASHI:**  \n“If the street stayed clear, the original carrier was supposed to hand the package over.”\n\n**ANBU OPERATIVE:**  \n“And if it didn't?”\n\n**KAKASHI:**  \n“He kept moving with it.”\n\n**ANBU OPERATIVE:**  \n“Destination?”\n\n**KAKASHI:**  \n“They didn't say.”"},{"level":2,"title":"Narration","path":"24. Knowledge-bearing report modules > Narration","text":"Kakashi gives exactly what he heard.\n\nNothing more."},{"level":3,"title":"Private Minato projection","path":"24. Knowledge-bearing report modules > Narration > Private Minato projection","text":"**MINATO:**  \n“He stayed long enough to understand the contingency.”\n\n**ANBU OPERATIVE:**  \n“Yes.”\n\n**MINATO:**  \n“And not long enough to invent the part they never said.”"},{"level":3,"title":"Chronicle Receipt","path":"24. Knowledge-bearing report modules > Narration > Chronicle Receipt","text":"**Intelligence — Handoff contingency overheard.**  \n**Downstream package destination — Unknown.**\n\n---"},{"level":2,"title":"24B. ASK WHERE THE PACKAGE WAS GOING — limited Knowledge","path":"24. Knowledge-bearing report modules > 24B. ASK WHERE THE PACKAGE WAS GOING — limited Knowledge","text":"Use after the authored information scene where Kakashi learns:\n\n- AMT's role ended at the handoff;\n- PS was meant to take the package onward;\n- AMT did not know PS's downstream destination."},{"level":3,"title":"Rooftop report","path":"24. Knowledge-bearing report modules > 24B. ASK WHERE THE PACKAGE WAS GOING — limited Knowledge > Rooftop report","text":"**ANBU OPERATIVE:**  \n“You questioned the original target.”\n\n**KAKASHI:**  \n“Yes.”\n\n**ANBU OPERATIVE:**  \n“What did he tell you?”\n\n**KAKASHI:**  \n“His job ended at the handoff.”\n\n**ANBU OPERATIVE:**  \n“And after that?”\n\n**KAKASHI:**  \n“The receiver was supposed to take it somewhere else.”\n\n**ANBU OPERATIVE:**  \n“Where?”\n\n**KAKASHI:**  \n“He didn't know.”\n\nThe operative studies him.\n\n**ANBU OPERATIVE:**  \n“You believe that.”\n\n**KAKASHI:**  \n“He'd asked too.”"},{"level":3,"title":"Private Minato projection","path":"24. Knowledge-bearing report modules > 24B. ASK WHERE THE PACKAGE WAS GOING — limited Knowledge > Private Minato projection","text":"**MINATO:**  \n“He stopped to ask a question before he chose the fight.”\n\n**ANBU OPERATIVE:**  \n“Yes.”\n\n**MINATO:**  \n“And learned the carrier didn't know the destination either.”\n\n**ANBU OPERATIVE:**  \n“Yes.”\n\nMinato looks at the report.\n\n**MINATO:**  \n“Useful.”\n\nThe operative waits.\n\n**MINATO:**  \n“Not because it gives us a destination.”\n\nHe taps the line once.\n\n**MINATO:**  \n“Because it tells us where the carrier's Knowledge ended.”"},{"level":3,"title":"Chronicle Receipt","path":"24. Knowledge-bearing report modules > 24B. ASK WHERE THE PACKAGE WAS GOING — limited Knowledge > Chronicle Receipt","text":"**Intelligence — Original carrier's role ended at handoff.**  \n**Downstream destination — Unknown to original carrier.**\n\nDo not invent a downstream location.\n\n---"},{"level":1,"title":"24. Final lock","path":"24. Final lock","text":"> **All nonlethal / defeat / pursuit / custody / release terminal states now have exact current-quality report, Minato-evaluation and Receipt expression modules.**\n\n> **Battle defeat can coexist with package success.**\n\n> **Package success can coexist with target escape.**\n\n> **Police custody is not ANBU custody.**\n\n> **Field restraint is not institutional custody.**\n\n> **Deliberate release is not escape.**\n\n> **Defeated-and-left-alive is not deliberate release.**\n\n> **Pakkun remains autonomous and explicitly departs.**\n\n> **More specific exact branch scenes remain stronger than this reusable terminal authority.**"}]}};
function doc(key){return DOCS[String(key||"")]||null;}
function sections(key){const d=doc(key);return d?d.sections:[];}
function findSection(key,pathFragments=[]){
  const wanted=(Array.isArray(pathFragments)?pathFragments:[pathFragments]).filter(Boolean).map(String);
  const rows=sections(key);
  return rows.find(row=>wanted.every(fragment=>row.path.includes(fragment)))||null;
}
function text(key,pathFragments=[]){const row=findSection(key,pathFragments);return row?row.text:"";}
function narrationCues(value){
  return String(value||"").split(/\n\s*\n/).map(s=>s.trim()).filter(Boolean)
    .filter(s=>!/^\*\*Backdrop|^\*\*Objective|^\*\*Status|^\*\*Source/.test(s))
    .map(t=>({kind:"narration",text:t.replace(/^\*\*|\*\*$/g,"").trim()}));
}
function dialogueCues(value){
  const lines=String(value||"").split(/\r?\n/);const cues=[];let speaker=null,buffer=[];
  const flush=()=>{const t=buffer.join(" ").trim();if(speaker&&t)cues.push({kind:"dialogue",speakerName:speaker,text:t.replace(/^“|”$/g,"")});buffer=[];};
  for(const raw of lines){
    const line=raw.trim();if(!line)continue;
    const m=line.match(/^\*\*([^*]+?):\*\*$/);
    if(m){flush();speaker=m[1].trim();continue;}
    if(/^\*\*/.test(line)&&/\*\*$/.test(line)){continue;}
    if(speaker)buffer.push(line);
  }
  flush();return cues;
}
function cues(key,pathFragments=[]){
  const row=findSection(key,pathFragments);if(!row)return[];
  if(/Narration/i.test(row.title))return narrationCues(row.text);
  if(/Dialogue/i.test(row.title))return dialogueCues(row.text);
  return narrationCues(row.text);
}
